INSERT INTO raw_events VALUES(174,'https://meinstutensee.de/termine/','Vögel der Feldflur: Exkursion mit Jochen Lehmann (OAG Karlsruhe)','2026-05-31','2026-05-31','07:30','Tennisclub Spöck, Spechaastr. 86, 76297 Stutensee','','Auf einer kleinen Wanderung durch die Feldflur in Stutensee wollen wir dem Gesang von Feldlerche &amp; Co lauschen und Arten wie Wiesenschafstelze und Schwarzkehlchen beobachten. Mit Hilfe beteiligter Landwirte konnten hier Maßnahmen wie Buntbrachen und extensive Ackerbewirtschaftung umgesetzt und der Rückgang vieler Feldvögel gestoppt werden.','https://www.meinstutensee.de/veranstaltungen/voegel-der-feldflur-exkursion-mit-jochen-lehmann-oag-karlsruhe/','0493288cd5d3ffaf60c1e791e70e81f08d94ab2a612b95b670bc0f1fcc1ab4c5','2026-04-25 16:27:21');
