INSERT INTO raw_events VALUES(266,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2025-10-29','2025-10-29','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2025-10-29/','843b73548a46e26a0e22037e98b63ab02af82fdfac929251e726480d40172ec0','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(267,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2025-10-29','2025-10-29','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2025-10-29/','41b290b562888e7ece0fb0a6a0503f05d5ec1f969b031bc46663d7da6f78ee26','2026-04-25 16:35:37');
