INSERT INTO raw_events VALUES(463,'https://stutenseekinderkalender.de','Selbstbehauptung & Selbstverteidigung für Jugendliche (10-16 Jahre)','2025-12-06','2025-12-06','10:00','Sporthalle, Heinrich-Heine-Straße 1, Stutensee-Spöck, 76297','vhs Karlsruhe Land',unistr('In diesem Kurs lernen Mädchen und Jungen, sich in schwierigen Situationen sicher und selbstbewusst zu verhalten. Es geht um den Umgang mit Belästigungen, Gewalt, Grenzüberschreitungen oder Konflikten – sei es auf dem Schulweg, an der Haltestelle oder in der Freizeit.\u000aDurch Rollenspiele und Übungen werden Alltagssituationen nachgestellt, um zu üben, wie man sich klar behauptet und schützt – mit Körpersprache, Stimme und Selbstsicherheit.\u000aAuch einfache, altersgerechte Selbstverteidigungstechniken werden vermittelt, damit die Teilnehmenden wissen, wie sie sich im Ernstfall wehren können.'),'https://stutenseekinderkalender.de/event/selbstbehauptung-selbstverteidigung-fuer-jugendliche-10-16-jahre/','7507072ed69bb20f5f16b9e2c19e47931d9b51168fbc6f7cc4d8cf517e19fe0f','2026-04-25 16:35:37');
