INSERT INTO raw_events VALUES(465,'https://stutenseekinderkalender.de','Tag der offenen Tür – Waldorfkindergarten Stutensee','2025-12-06','2025-12-06','15:00','Waldorfkindergarten Stutensee, Rheinstraße Ost 12, Stutensee, 76297','Waldorfkindergarten Stutensee',unistr('Der Waldorfkindergarten Stutensee lädt herzlich zum Tag der offenen Tür ein. Besucherinnen und Besucher haben die Gelegenheit, den Kindergarten kennenzulernen, Einblicke in den Alltag mit den Kindern zu gewinnen und die besondere Atmosphäre vor Ort zu erleben.\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/tag-der-offenen-tuer-waldorfkindergarten-stutensee/','50d02b7c5b8e29ea3a8b1957a85787bd78726720c5361ec0d1c144d1fe36f4e8','2026-04-25 16:35:37');
