INSERT INTO raw_events VALUES(511,'https://stutenseekinderkalender.de','Büchiger Adventsfest','2025-12-12','2025-12-12','19:00','Familie Hassmann, Waldstraße 106, Stutensee-Büchig, 76297','Büchig(er)leben',unistr('Es wird weihnachtlich in Büchig. Mit Glühwein, Punsch, Gegrilltem, Waffeln und natürlich ganz viel Adventsstimmung. Wir freuen uns sehr, dass der Musikverein Harmonie Blankenloch e. V. uns um 19 Uhr mit tollen Klängen die Weihnachtszeit versüßt.\u000a'),'https://stutenseekinderkalender.de/event/buechiger-adventsfest/','3daf457facfbd6a19920b0cb3995108748bde4b2780bb53c2ad7fbf4f07e21aa','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(512,'https://stutenseekinderkalender.de','Blankenlocher Weihnachtsmarkt 2025','2025-12-13','2025-12-13','15:00','Blankenloch, Stutensee-Blankenloch, 76297','Stadt Stutensee',unistr('Der Blankenlocher Weihnachtsmarkt lädt zu einem stimmungsvollen Adventswochenende ein – mit Musik, warmem Punsch, vielen Leckereien und abwechslungsreichen Programmpunkten für Kinder und Familien.\u000aHighlights laut Programm:Samstag, 13.12.\u000a\u000a14:30 Uhr: Enthüllung der neuen Namenstafel (Altes Rathaus)\u000a15:30 Uhr: Offizielle Eröffnung & Kinderchor der Pestalozzi-Grundschule\u000aIm Anschluss: Besuch des Weihnachtsmanns\u000aErzähltheater für Kinder, Bücherflohmarkt & Weihnachtskonzert des TMG\u000a\u000aSonntag, 14.12.\u000a\u000aBücherflohmarkt in der Stadtbibliothek\u000aErzähltheater für Kinder\u000a16:30 Uhr: Weihnachtliches Singen in der Michaeliskirche\u000a18:00 Uhr: Adventschoralblasen\u000a\u000aAn beiden Tagen geöffnet:– Kerns-Max-Haus (inkl. Museumscafé & Ausstellung)– Gebäude Hauptstraße 86 mit Kunstausstellung\u000aDer Weihnachtsmarkt bietet zudem viele Stände mit Essen, Getränken, Selbstgemachtem und lokalen Vereinen.\u000aFlyer Blankenlocher Weihnachtsmarkt 2025'),'https://stutenseekinderkalender.de/event/blankenlocher-weihnachtsmarkt-2025/2025-12-13/','a3ad631f45a1e8aa21c8f48fe039ec45edfa16b01f2b320aaf86454e82f18c9a','2026-04-25 16:35:37');
