INSERT INTO raw_events VALUES(538,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2025-12-18','2025-12-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2025-12-18/','47a9152802e51ba19961fff6e10aa00395087a1cba4ed9a7d5c353ac8e9a9b35','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(539,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2025-12-18','2025-12-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2025-12-18/','d3d670da981a7e0b36a80a686d2ceaacbf2e9b073ceac2321bc39ab0d8837523','2026-04-25 16:35:37');
