INSERT INTO raw_events VALUES(1156,'https://stutenseekinderkalender.de','Eltern-Baby-Treff','2026-05-08','2026-05-08','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-05-08/','a28d579400188b851ffe25160165f5c1b68388b88dc58712515e6dbdcf5ad08b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(1157,'https://stutenseekinderkalender.de','Themenvormittage für Eltern von den Frühen Hilfen','2026-05-08','2026-05-08','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Mit Kindern von 0 – 3 Jahren, freitags 9:30 Uhr, 1 montl.\u000aTermine 2026:\u000a16.01., 13.03., 08.05., 10.07.26\u000aKostenfrei und ohne Anmeldung!'),'https://stutenseekinderkalender.de/event/themenvormittage-fuer-eltern-von-den-fruehen-hilfen/2026-05-08/','ea416fd3ffd8aa5fc941c02f52892d004ddf079e28222cd579bed24e2fed4ae6','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(1158,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2026-05-08','2026-05-08','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-05-08/','e25d0cd0e411c92f6bbec4a540c690a000841e338bae1bf24877d4c7cae82b27','2026-04-25 16:35:37');
