INSERT INTO raw_events VALUES(3081,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2027-09-11','2027-09-11','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-09-11/','c171cb09b3df76baf5e9c9f9583f386bb60d4076ee170ad817d23b3970d8dfdf','2026-04-25 16:35:37');
