INSERT INTO raw_events VALUES(3281,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2027-11-06','2027-11-06','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-11-06/','0db588f3aef6f0556da00338d30945a65b9921e6acd0d36c4b303c826b4f351b','2026-04-25 16:35:37');
