INSERT INTO raw_events VALUES(3302,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2027-11-11','2027-11-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-11-11/','bd48d7bb39ae85f20f8817944006c6446744f9acf02ff474481397169409e1f5','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(3303,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2027-11-12','2027-11-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-11-12/','1bdc3b57b5774280a11b71b02ed4fa241b168af12369720c5c209fb593b2cd8f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(3304,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2027-11-12','2027-11-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-11-12/','6a2cf2e5b03fa33c9f1acca1e2c1661eb8d5925cd4760e2285e723232b14d1c2','2026-04-25 16:35:37');
