INSERT INTO raw_events VALUES(3605,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-02-04','2028-02-04','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-02-04/','f0141947203e6a78eaf042b9802f3376b4c03b47de01fbb82c3f2e76eceea502','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(3606,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-02-05','2028-02-05','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-02-05/','222cf8838b4fb8848b4276f06995c75bb5502e6f195bca4577fa7d476ea86e2c','2026-04-25 16:35:37');
