INSERT INTO raw_events VALUES(4256,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-08-05','2028-08-05','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-08-05/','b6ab1727fee2de8e3b767f2da955300301ad95f3c332dc68d48bd707a5b27744','2026-04-25 16:35:37');
