INSERT INTO raw_events VALUES(4381,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-09-09','2028-09-09','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-09/','499850a8217df50f54a72f18bf715275dfbb7a4bb0e1cf381e66a57a9eae1d0d','2026-04-25 16:35:37');
