INSERT INTO raw_events VALUES(4402,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-09-14','2028-09-14','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-09-14/','fd698df46f86235c34eab2f991ad8187a7203b0b9d911ae1656e59a7f833c80b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4403,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-09-15','2028-09-15','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-15/','e4566fc279481c3fd901c4a198d3b899be333d7a0d362b6b63a55ba146271b02','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4404,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-09-15','2028-09-15','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-15/','a858bc4f194eacfd08c31d1b6c987fbc0c53208fdaee8a4265e4533303225c99','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4405,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-09-15','2028-09-15','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-15/','9b82a0336ac772b4a0da4f81a4ec21a8b03679ae511a613fa7f2cf989c91a395','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4406,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-09-16','2028-09-16','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-16/','161025f5245636698c3e98a48dbf66cd8d5267840dd20d8d626bf23736b430e4','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4407,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-09-18','2028-09-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-18/','66e6f72d19e56df3340b07a504904366440fa9fba4bce9417701dfed618bfc8d','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4408,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2028-09-18','2028-09-18','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-09-18/','f46196990c38756f91bab64191f10e67d0e8e50f75bf4beb2d971edb7ef6bef3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4409,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2028-09-18','2028-09-18','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-09-18/','d6ccffd77f3578bcbb045c7f47072ade4e890a8b6e64e313aee181e49b4b460b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4410,'https://stutenseekinderkalender.de','Kinder- und Jugendtraining – Wilde 13','2028-09-18','2028-09-18','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-09-18/','2663655553b2da493eb4b5d011a73874c3bf7667d195cd2591adbb376a55c23b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4411,'https://stutenseekinderkalender.de','Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück','2028-09-19','2028-09-19','09:00','Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297','Heilig-Geist-Gemeinde Büchig',unistr('Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.\u000aAuch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.\u000aZurzeit in der Belchenstraße (privat bei Melanie Reuter).\u000aKontakt zum Veranstalter\u000a\u000aAnsprechpartnerin: Melanie Reuter\u000aE-Mail: info@krabbelkäfer-stutensee.de\u000aoder übers Pfarramt\u000a\u000a \u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2028-09-19/','939e1512d9059f0a36e7e336d904a731cb2cbf3c93a2c792a386e73fc61e63bc','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4412,'https://stutenseekinderkalender.de','Krabbelgruppe in Spöck','2028-09-19','2028-09-19','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-09-19/','e3f07627d75e4b32f398e4263ee55ead2ae14cbcfa9f3d039623643907eb58f4','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4413,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-09-19','2028-09-19','16:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-09-19/','b45472f1dfad65ac46fa9223ed4318897386ac217ecb084125744fee91e76444','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4414,'https://stutenseekinderkalender.de','Schach für Schüler, Jugendliche & Anfänger','2028-09-19','2028-09-19','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-09-19/','1f0678be40634b9c8c4d733fb658f614f45065ad7c5a8f894b005509c01c121e','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4415,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe Wölflinge','2028-09-19','2028-09-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-09-19/','e5d021367057904dd585f28cabb435be79936a72489e004847d687cc64f43649','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4416,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe (11–15 Jahre)','2028-09-19','2028-09-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-09-19/','6bb0a306d47d584dd9ef6cbc75c3917c564d3c91a8024e4e793606a52dab22ab','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4417,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-09-19','2028-09-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-19/','072ea02af9d677793625a354ef3cd821ec47df0504057c499bd903baac38beb4','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4418,'https://stutenseekinderkalender.de','Selbsthilfegruppe für Angehörige von AD(H)S-Kindern','2028-09-19','2028-09-19','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-09-19/','cb0d10111b1117ac3c9c322c9d0af92f6e076eef56e3f71d01411367eae16016','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4419,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2028-09-20','2028-09-20','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-09-20/','e598cde566b6aaadfc827da52733b804f4f778fe56607863b4f058c8785ff44c','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4420,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2028-09-20','2028-09-20','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-09-20/','e66442323ae4e383bbcc9321451483c74b2a57bfe9b4d6bea62741f257bcee0d','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4421,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-09-21','2028-09-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-21/','2895f77b26c7343b44b7be7e0c9cf3f76d973145a47a8336f206b95e1c9e281d','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4422,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2028-09-21','2028-09-21','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-09-21/','01cb4936ae776588d35c995182ad34ff049827440c98353d499928ded78e8429','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4423,'https://stutenseekinderkalender.de','Tee- und Spielstube','2028-09-21','2028-09-21','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-09-21/','0758ce2bf70beaaa0c97cd767cf97719cff307fc9f911a1677b9048e5da40c16','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4424,'https://stutenseekinderkalender.de','Seesternchengarde (3–6 Jahre)','2028-09-21','2028-09-21','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-09-21/','ac5225047590d2f267fd6a5ff88ad639d1b8fd909f6c3b159da13f51a9ef07aa','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4425,'https://stutenseekinderkalender.de','Teen Girls im GrauBau','2028-09-21','2028-09-21','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-09-21/','a24f78d5cfe3a616531ae8126ef1b7a1cd6849848578bd1330abdf44b0ad6643','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4426,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-09-21','2028-09-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-21/','177776a1381621f0d484c441d0d26d9eea3575cbae6bd1a386e9d3803b156e48','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4427,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-09-21','2028-09-21','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-09-21/','9edf13fae10114cfa994b7c5b30f644e1cc7f34dc8112180ccd314cea668a2ed','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4428,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-09-22','2028-09-22','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-22/','263172aae6023cd335bc74ced78592249b1fdc09169785caa1f2903c1d52659f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4429,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-09-22','2028-09-22','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-22/','31fbdf3991ae5af65117331ae042335b1b764deb49189998e389d7fbde91f2b2','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4430,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-09-22','2028-09-22','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-22/','74c0ad13f924d4916bdd85d0e8118dfaed4c6af690d4c4e836c1f44157aec852','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4431,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-09-23','2028-09-23','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-23/','49ad27ceda1fb57c9beb9c910d6d14c3e416571da21bb1395aab695ce0ab2cae','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4432,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-09-25','2028-09-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-25/','512d6e5811ee806bcbf7197fde04af0dfadd471752ec7dc6b284c430ccb312da','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4433,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2028-09-25','2028-09-25','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-09-25/','dd12dff57412b1bf9247c52e130bf03f3e379a81b02b194739b00ffc21fcca37','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4434,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2028-09-25','2028-09-25','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-09-25/','99ab9b53ea50965ab9dbb8b3ff74546812687d3addba233f995e3f45ab13fd49','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4435,'https://stutenseekinderkalender.de','Kinder- und Jugendtraining – Wilde 13','2028-09-25','2028-09-25','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-09-25/','4008945f3c4a63e9007f1cb42ca03644cf5de82ffbdc538c21a4e58a4b7b74bb','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4436,'https://stutenseekinderkalender.de','Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück','2028-09-26','2028-09-26','09:00','Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297','Heilig-Geist-Gemeinde Büchig',unistr('Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.\u000aAuch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.\u000aZurzeit in der Belchenstraße (privat bei Melanie Reuter).\u000aKontakt zum Veranstalter\u000a\u000aAnsprechpartnerin: Melanie Reuter\u000aE-Mail: info@krabbelkäfer-stutensee.de\u000aoder übers Pfarramt\u000a\u000a \u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2028-09-26/','acb15a1c2c1a5baf53d55f8a34c7a375aa87a1e52521389f140177eb999db1c9','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4437,'https://stutenseekinderkalender.de','Krabbelgruppe in Spöck','2028-09-26','2028-09-26','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-09-26/','1875bb4bf0c2c018c85dc6aec6f90df5305824c2cd8bf605da3d1a834f1a920d','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4438,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-09-26','2028-09-26','16:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-09-26/','6f85648f8e7af8b5e6358730cc339c37d32e70bba282ce72f44e5804e3535d3a','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4439,'https://stutenseekinderkalender.de','Schach für Schüler, Jugendliche & Anfänger','2028-09-26','2028-09-26','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-09-26/','d2cd1d94b0f09dcbd7ec69a619be91e6828cf835b1cd93f32afd5a2928c19575','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4440,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe Wölflinge','2028-09-26','2028-09-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-09-26/','bffa1a23c17f3fc2087a4d377e2f9c0b5c79cd09e1efe09d2bf19a6af8bb5d6b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4441,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe (11–15 Jahre)','2028-09-26','2028-09-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-09-26/','e080d350ac25878fd574160b1da4a4167820a4e05cc4bbb9f0fc9c70303f1225','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4442,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-09-26','2028-09-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-26/','28c16ae6361d0676d3f3c97e8be979ca1d3391868ae02486a167ecf996ec4cf5','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4443,'https://stutenseekinderkalender.de','Selbsthilfegruppe für Angehörige von AD(H)S-Kindern','2028-09-26','2028-09-26','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-09-26/','4a19bd1583ead7361ef12472b9f3b5361d315518867ee549ce6fd5ea210b4c72','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4444,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2028-09-27','2028-09-27','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-09-27/','dd24db33af5c3abf40c271eeff600d74c155d895e7f6e86c2156413f0a3eae1e','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4445,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2028-09-27','2028-09-27','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-09-27/','790b13f0d3d7216a5effcaae4299683fa90491abd55288b1212d4ee66aa79304','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4446,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-09-28','2028-09-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-28/','c84e07cd5483868c9e82ec6a66d022303b69f65aeb99eda80099d135eaec6cce','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4447,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2028-09-28','2028-09-28','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-09-28/','48d6f5b5211a2f6276893121182aecd0be9a8055cf6bbd0bcb2c92a3798693be','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4448,'https://stutenseekinderkalender.de','Tee- und Spielstube','2028-09-28','2028-09-28','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-09-28/','609bb0aa1c864a468ca9bf4d64ecdd00fb3ed56bd67c59486b165ba98d93e2fd','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4449,'https://stutenseekinderkalender.de','Seesternchengarde (3–6 Jahre)','2028-09-28','2028-09-28','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-09-28/','d3cbb82152369678fe9b142d6980551eb6a667872d26a945140cc4efccf280eb','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4450,'https://stutenseekinderkalender.de','Teen Girls im GrauBau','2028-09-28','2028-09-28','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-09-28/','4ed3b30282169017bad1bd30910b3cfb862944c23c191709d206f438fc91472d','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4451,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-09-28','2028-09-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-28/','44c20c975e08691e7e97d0e0cd1f0c538d14cf833d39a68a5d55c87752122f58','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4452,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-09-28','2028-09-28','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-09-28/','262a783897ff91037c9640c290678dccccf571f1c4dc84028e67d78d58d4a4c3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4453,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-09-29','2028-09-29','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-29/','d48ad35fb06397b719f11750a2458b36c4a6e5fe500f153eba03f7f82c34d67a','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4454,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-09-29','2028-09-29','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-29/','53414b641803c758ff7e0b7c6db0d3215c6566704ee70d99ebde7204d1b5ed88','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4455,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-09-29','2028-09-29','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-29/','6a707441fd385fcbc02446d13563de75b255e77c57c52d7ef96c9ebd46c1b5e8','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4456,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-09-30','2028-09-30','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-30/','7c8549aa78831538472f27c6c84989f17df4931a3f1c170f00cd865a3711b440','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4457,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-02','2028-10-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-02/','d65ffa06ee20cee3229b2fa579c8f5a9380c211273f7e767ce8418d257a83524','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4458,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2028-10-02','2028-10-02','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-02/','a9414f21a846be596a7ab02742fa7b6a7ef74c235187b9883925158456768547','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4459,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2028-10-02','2028-10-02','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-02/','e515ca299bbc355b8a2acd83f8beb5163f5a198cdd4c3aca7ad7b536c2c43efa','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4460,'https://stutenseekinderkalender.de','Kinder- und Jugendtraining – Wilde 13','2028-10-02','2028-10-02','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-02/','8c02348988f043065733303328711c9b2fa3a4bec0d27d126271210bd863239f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4461,'https://stutenseekinderkalender.de','Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück','2028-10-03','2028-10-03','09:00','Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297','Heilig-Geist-Gemeinde Büchig',unistr('Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.\u000aAuch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.\u000aZurzeit in der Belchenstraße (privat bei Melanie Reuter).\u000aKontakt zum Veranstalter\u000a\u000aAnsprechpartnerin: Melanie Reuter\u000aE-Mail: info@krabbelkäfer-stutensee.de\u000aoder übers Pfarramt\u000a\u000a \u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2028-10-03/','4e527f146d68246ca5b91c8992e1be2cf7872c6a9c4cd9dff9800cefb26fb656','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4462,'https://stutenseekinderkalender.de','Krabbelgruppe in Spöck','2028-10-03','2028-10-03','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-03/','23bec1830112a4ca29a924e8d52c9ad70bcf49c9d318b315143242c85caec48e','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4463,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-03','2028-10-03','16:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-10-03/','6599322a355559fdb08a08dceced54b6f662a26b32bcedb693640b1b2f1014b3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4464,'https://stutenseekinderkalender.de','Schach für Schüler, Jugendliche & Anfänger','2028-10-03','2028-10-03','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-03/','a2827aef21a93e146b8ffad35046ab79fa7a3b5435e890735f777ac1e74c0327','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4465,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe Wölflinge','2028-10-03','2028-10-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-03/','3591a9d00f70c1bc240652a3d369bc3aef1dc930153e10d98020bcd13b3b7c9a','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4466,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe (11–15 Jahre)','2028-10-03','2028-10-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-03/','18b4132be3524d1c222dea293c19a514d5beb84cf6dc40dc47bd526ab3d32065','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4467,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-03','2028-10-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-03/','2e65dde6dd3cf38978535b9b1de6659ac0399127d89f038a3df2229bd2a98b8b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4468,'https://stutenseekinderkalender.de','Selbsthilfegruppe für Angehörige von AD(H)S-Kindern','2028-10-03','2028-10-03','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-03/','d12fd0e42e31f099097d59968097b4fc0e17a4ac4429a8a758530dd867cc65b1','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4469,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2028-10-04','2028-10-04','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-04/','7731d222e39e0220b4d07bf086a867414b5148f879280b081d61378aa9ca688a','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4470,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2028-10-04','2028-10-04','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-04/','40306d05b8405ce50550fedb50d59f99699b1ee23d8fa6c6fd3b8d503fa78145','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4471,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-05','2028-10-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-05/','733b78d61099d53954b0e03643c9c104042c549cca0ae985b4f276aa71c9d2e7','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4472,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2028-10-05','2028-10-05','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-05/','7c0d83c5781cd079306ab7eb7c2ee292c6adec336974d952134407397cc8a4c5','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4473,'https://stutenseekinderkalender.de','Tee- und Spielstube','2028-10-05','2028-10-05','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-05/','9d2f8e95da2ca0840ce3d682d4016da7d870e398dbe7eeb0d3f3250e69ed52c3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4474,'https://stutenseekinderkalender.de','Seesternchengarde (3–6 Jahre)','2028-10-05','2028-10-05','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-05/','3a9cc6dc7b384a76905014a295cbc87ceba3bec337f0a437ca413c26913c0d7a','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4475,'https://stutenseekinderkalender.de','Teen Girls im GrauBau','2028-10-05','2028-10-05','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-05/','dded228c810b752f313780f624b6cf9b4e55c76075cf2f4511395949425bdcb6','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4476,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-05','2028-10-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-05/','1856d7b60be239510f4b5b9a9a26abc8b8e1faef379987d2d1105f24c8eda2de','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4477,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-10-05','2028-10-05','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-05/','94791a3f2519cbe9cc02867f7299a6c49f3317141b75a417c98432527d2946ac','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4478,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-10-06','2028-10-06','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-06/','6ed1ab4f46022b45340b55d0231a6128af3b8a64092395f74f3ffb3b253458da','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4479,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-10-06','2028-10-06','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-06/','69e7ac03db079b2fcf2802632c8f8608722ee7efdeb92304c584b20a4063cea3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4480,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-06','2028-10-06','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-06/','3636c467e250e52285eb8562ca4e140b4d241e6dc4aa0230a83494fd97cc82c7','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4481,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-10-07','2028-10-07','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-07/','5f830076452b996bfdc2c898aa001be9ca76e38273363d3d932a3e4eb4f5cc58','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4482,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-09','2028-10-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-09/','11032591279ae6ad83bfba0d5fef20c0d17d05de4f6bc6df8bdb1cc5a3960296','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4483,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2028-10-09','2028-10-09','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-09/','8bc9a10c1f5c29cc8b86898b7a16fc5d8c36e4edd0b7bcc1908f510f0190fe68','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4484,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2028-10-09','2028-10-09','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-09/','8cb6ef291be7857b00f7da0d05884edf27fff3ae358960ee067970966b7de468','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4485,'https://stutenseekinderkalender.de','Kinder- und Jugendtraining – Wilde 13','2028-10-09','2028-10-09','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-09/','80864ea174b74df3ca0df3d4dfc083525741a3066b35b66bc63b20069c70012b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4486,'https://stutenseekinderkalender.de','Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück','2028-10-10','2028-10-10','09:00','Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297','Heilig-Geist-Gemeinde Büchig',unistr('Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.\u000aAuch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.\u000aZurzeit in der Belchenstraße (privat bei Melanie Reuter).\u000aKontakt zum Veranstalter\u000a\u000aAnsprechpartnerin: Melanie Reuter\u000aE-Mail: info@krabbelkäfer-stutensee.de\u000aoder übers Pfarramt\u000a\u000a \u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2028-10-10/','7b391f59e27b166c0670091858a986da975e4cb123242d53f5a2b52c34b9de6b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4487,'https://stutenseekinderkalender.de','Krabbelgruppe in Spöck','2028-10-10','2028-10-10','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-10/','f53ea141eafa7f2bd52e7dddd2e91c455a3f8194267c65f2767d62c0741ec9c5','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4488,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-10','2028-10-10','16:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-10-10/','bd9707e0d18551134a587acda80cd31718fc7cfb6f0fb37afd00ae9305117e60','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4489,'https://stutenseekinderkalender.de','Schach für Schüler, Jugendliche & Anfänger','2028-10-10','2028-10-10','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-10/','6507d38e7ac0aeedbefc0fabd0a1c7e023e8bc9cb09ae09911f74dd91a6b4b17','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4490,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe Wölflinge','2028-10-10','2028-10-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-10/','eee4937d2b44f7be1bb776aea9c00142bdc0f811801e07c8a75c1bfa1e78fa80','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4491,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe (11–15 Jahre)','2028-10-10','2028-10-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-10/','9e07f29bacafe22fa503f9ff706dee86fd465e955d00c0a195f513adea939a13','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4492,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-10','2028-10-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-10/','2b6de66466f65c3e515f33d6f305948f304c4a10828c8f3fc3c78bf7c13dfcb5','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4493,'https://stutenseekinderkalender.de','Selbsthilfegruppe für Angehörige von AD(H)S-Kindern','2028-10-10','2028-10-10','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-10/','e24967dbde7af08dd5a92ce29fcd1659251925e77141b73605e8b2bb9090e048','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4494,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2028-10-11','2028-10-11','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-11/','308900e869e2778e17673ce657472cde56af2133af861a57e6c4f7d25b1d9ed7','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4495,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2028-10-11','2028-10-11','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-11/','606691c1e91a4863e9cd99d8f1e77dafc29c9ecdfa9a8209a8bcb693d91a788d','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4496,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-12','2028-10-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-12/','814f216ae9eac53b564cf1bf5dd47868b540698d1d7906a07a62feddb0891df0','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4497,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2028-10-12','2028-10-12','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-12/','b33e85c43487ec6c8a9e2413d16c3a7fba0121fc87d02631c645bb8d82b68958','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4498,'https://stutenseekinderkalender.de','Tee- und Spielstube','2028-10-12','2028-10-12','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-12/','38267abb01fd09ecd4b8df955015f58de5792533963e1a743349631048075e26','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4499,'https://stutenseekinderkalender.de','Seesternchengarde (3–6 Jahre)','2028-10-12','2028-10-12','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-12/','8bcd6854865dd85caa3a9e893624a140bdeabf85105b5033faa5da87d2ae9b1f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4500,'https://stutenseekinderkalender.de','Teen Girls im GrauBau','2028-10-12','2028-10-12','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-12/','d0b8bb4745818a452bd7f8660670354666f12063220cf76eff58326cc1ecb153','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4501,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-12','2028-10-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-12/','3cf4916ec2f2d364218733ef90dce99e7f5d66eb5a44376befb9e54e24725d90','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4502,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-10-12','2028-10-12','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-12/','691cf81e7e970322494abd613012596bacb7ada42dfd70eb98a61a316549b682','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4503,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-10-13','2028-10-13','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-13/','d7421b4ca3016941b3b6242c78c1c8bfc43ecadd55b7ae1baca9244b06afc586','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4504,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-10-13','2028-10-13','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-13/','b293e4722b038329e02f8232d17be3726b85444450ad9ca18a5845dda3101963','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4505,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-13','2028-10-13','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-13/','e69d01c0924ccfc99fe73d0caf6adc6c84af6dd215d6ed2b818b1c37a7a74519','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4506,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-10-14','2028-10-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-14/','596f8db9766e44346a10df9b00ba1a77ad5be3b88983cff9e96c131e0d474676','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4507,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-16','2028-10-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-16/','3f35adba1ff9c6739783be1d0fcf60362b7295dcfef1d12bbad927f54ff0dba3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4508,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2028-10-16','2028-10-16','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-16/','d6ca299c51ef3b964b3a8a46afca19d3c3350e906494508e2c892168ee42d4f0','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4509,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2028-10-16','2028-10-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-16/','24950b6785203cfcc242d21e9d46a8915510adb3833c85824b3c10284431459f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4510,'https://stutenseekinderkalender.de','Kinder- und Jugendtraining – Wilde 13','2028-10-16','2028-10-16','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-16/','bc027d1279929f286fe072a59d0de447e7108a60c9f9e11feaa38f9d7b9fddba','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4511,'https://stutenseekinderkalender.de','Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück','2028-10-17','2028-10-17','09:00','Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297','Heilig-Geist-Gemeinde Büchig',unistr('Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.\u000aAuch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.\u000aZurzeit in der Belchenstraße (privat bei Melanie Reuter).\u000aKontakt zum Veranstalter\u000a\u000aAnsprechpartnerin: Melanie Reuter\u000aE-Mail: info@krabbelkäfer-stutensee.de\u000aoder übers Pfarramt\u000a\u000a \u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2028-10-17/','c91f4b864aa7f5351adbc61c3a25431b4e91870073ac1e84292d47edce4b44a9','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4512,'https://stutenseekinderkalender.de','Krabbelgruppe in Spöck','2028-10-17','2028-10-17','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-17/','8b763e1e4089878707005e28456d4208d491cee4aba76d73ad64f159e5ac2f94','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4513,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-17','2028-10-17','16:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-10-17/','affb3edfe523988ca545ee241fcaf3214ceea2e1b860a7eb40dad0f4b500f50c','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4514,'https://stutenseekinderkalender.de','Schach für Schüler, Jugendliche & Anfänger','2028-10-17','2028-10-17','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-17/','0f1a3eacc71278d2474dd03748cfbdb9d6c8da02550132669812f80c5a029046','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4515,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe Wölflinge','2028-10-17','2028-10-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-17/','f317c5d102a74fd33afa81e7f4d55f35acfe2c3a757bb9a2da3055e3fa9a195e','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4516,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe (11–15 Jahre)','2028-10-17','2028-10-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-17/','6d78fd4ec5a96ac321427f12284990b8c87a7f1f92873d71c9d7396f30e1911e','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4517,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-17','2028-10-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-17/','faeaa7506c7b85291a9b1ce648d5a73bc683e63052cebddf4987906cfe39c4c7','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4518,'https://stutenseekinderkalender.de','Selbsthilfegruppe für Angehörige von AD(H)S-Kindern','2028-10-17','2028-10-17','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-17/','68eaf8212b226650dae3b101bb3a09116896ae8445e3f9f2d8a2c560bf1656d5','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4519,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2028-10-18','2028-10-18','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-18/','8c4ac7d6bec8f54d85bd2c48bd9de041a48f7043d0bd356c440d0236ec38f4a0','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4520,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2028-10-18','2028-10-18','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-18/','651f5c26dfa9f6365b646cc102a1d676907b3bb79eea260922d323f13df6e6c9','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4521,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-19','2028-10-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-19/','95ba6cb95aa0b9ee84e2b3fdd308ecb6e9ec46f83d9c5bce9765e545cc39c2e7','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4522,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2028-10-19','2028-10-19','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-19/','e9c12e23488384581ac37580eedd8ecd2fd5353190949aa86e1a63459b6d6edf','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4523,'https://stutenseekinderkalender.de','Tee- und Spielstube','2028-10-19','2028-10-19','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-19/','abb47ef890507c98803efce6a571766dbd090c591b8e8f0e216c8d376cff176e','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4524,'https://stutenseekinderkalender.de','Seesternchengarde (3–6 Jahre)','2028-10-19','2028-10-19','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-19/','321c09cbe520d933df7679e0aaf7214d695c81b16773a5acb090aba32a500805','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4525,'https://stutenseekinderkalender.de','Teen Girls im GrauBau','2028-10-19','2028-10-19','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-19/','0a6ca0d9728ca9751a8f2a79b594468c506c0838b6c63be51f7d775da470f617','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4526,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-19','2028-10-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-19/','bbf679bc8c8a9136f40c161717a8b068785b01ea426564ab02274c289636fc1b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4527,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-10-19','2028-10-19','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-19/','3726d0846756fdd7885045bd955314daefcc899ed5e14c1f3fa2e78969f9af22','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4528,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-10-20','2028-10-20','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-20/','5daa07a75fb5075dd73a0a3e462be1a240484aab0c4091ef419ec25307ea79cb','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4529,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-10-20','2028-10-20','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-20/','2c6b78f62ea2bef6d4985b6f56420410084dae857cf35ed53916d408186147e9','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4530,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-20','2028-10-20','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-20/','70d16c2eff19884e26064b87ded67ab1b151b14d27b0c6f02389958671a0295f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4531,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-10-21','2028-10-21','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-21/','4f2dc00f4048d2f3491e5a720ce74b6f516e2f293a8623ff00b760ef98693af9','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4532,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-23','2028-10-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-23/','57f1fde244dd80ede9aee18ffa397d1e3abe10909557d327549dfd352c6d2329','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4533,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2028-10-23','2028-10-23','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-23/','d37a0e7cdec7d784f56dd81997e667b40c02fe3330ba49faba8f947ddedc3216','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4534,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2028-10-23','2028-10-23','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-23/','9c980268b0498d60fdd1d331d7b431a2c2c91ddc244d00fa28f6f58c30308cbe','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4535,'https://stutenseekinderkalender.de','Kinder- und Jugendtraining – Wilde 13','2028-10-23','2028-10-23','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-23/','ec24c48c619faba3413c139d946b0d0ae08c699a3611ccabac70ed6126567849','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4536,'https://stutenseekinderkalender.de','Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück','2028-10-24','2028-10-24','09:00','Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297','Heilig-Geist-Gemeinde Büchig',unistr('Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.\u000aAuch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.\u000aZurzeit in der Belchenstraße (privat bei Melanie Reuter).\u000aKontakt zum Veranstalter\u000a\u000aAnsprechpartnerin: Melanie Reuter\u000aE-Mail: info@krabbelkäfer-stutensee.de\u000aoder übers Pfarramt\u000a\u000a \u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2028-10-24/','f2417afd3e9875d6dade6d75a88fae891a11deab0c7a69871a4029b10910f15b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4537,'https://stutenseekinderkalender.de','Krabbelgruppe in Spöck','2028-10-24','2028-10-24','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-24/','96069fb80358787ed716525ad40b13f696f48b2320c60f8685a914ed841d2bcc','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4538,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-24','2028-10-24','16:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-10-24/','93b0e5bdc4ef843c39933c4c7ca404a29ea8cef2848c9534bfcdef40dae5980c','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4539,'https://stutenseekinderkalender.de','Schach für Schüler, Jugendliche & Anfänger','2028-10-24','2028-10-24','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-24/','4fb684fdcae0bb94f2e85e9edbd472aaeb5e0109796a033d0b395806a29c3f17','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4540,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe Wölflinge','2028-10-24','2028-10-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-24/','538f140acd99a6e64306ca2e61a5bf303a0d6437b72b6b97ad8b8265f4778b19','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4541,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe (11–15 Jahre)','2028-10-24','2028-10-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-24/','e46ac9cae81aff8a13f43a4429d82cdc0535350283a4562b2a8f61fc7a95b483','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4542,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-24','2028-10-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-24/','b8dd0455d9b22382061d3588f82cf85167aa059d3e69beb835803a14c40a3777','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4543,'https://stutenseekinderkalender.de','Selbsthilfegruppe für Angehörige von AD(H)S-Kindern','2028-10-24','2028-10-24','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-24/','d858c6156f2d4f39a5a3c14d95795f410c7a42d8b222e65f26b9fb009a0d51f9','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4544,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2028-10-25','2028-10-25','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-25/','3c4889a90df73d071318a7f80ffdb3868dac2deaa9582f3fbbbb94f95c5f93f3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4545,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2028-10-25','2028-10-25','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-25/','418a858c3b2436841cf4fb838998067c8db6fa517311c386a02aeeea91e1bc58','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4546,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-26','2028-10-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-26/','d62d801ff777a4d5287b44bd298722c08eeff9b87c39849c4234f7d3f2288f4b','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4547,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2028-10-26','2028-10-26','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-26/','8f186dd40e2d348206f70aeb75a97141a97b5e78014265a1d38459b3f52226a1','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4548,'https://stutenseekinderkalender.de','Tee- und Spielstube','2028-10-26','2028-10-26','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-26/','48456f7730cce64853754443d7986d2041172ab27c51f9e3996528555fdcb8de','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4549,'https://stutenseekinderkalender.de','Seesternchengarde (3–6 Jahre)','2028-10-26','2028-10-26','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-26/','d38ed84bde6fa653601318ea89caa7106a91e61bb6bfb247350b9647047a2051','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4550,'https://stutenseekinderkalender.de','Teen Girls im GrauBau','2028-10-26','2028-10-26','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-26/','2ba13d929e467b7f4ce04772624b355174e2c2ba1ea0955b066be6ef833c0262','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4551,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-26','2028-10-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-26/','2d96fe1e3101639fce2366d029ce6072fc1d83cd39dc558331d4e86b17eba082','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4552,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-10-26','2028-10-26','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-26/','88cf31aa6a61db592750e5c9f8fbc0d72860ba0542c65823842d55fa05ba698d','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4553,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-10-27','2028-10-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-27/','21ca051f17cc1431b0120cc857eaee64182e405cddb4689c4c4acfd154d1762c','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4554,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-10-27','2028-10-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-27/','b04a58e385aeeaf53faf4e74223cf3e04fc219f5ab3c1eed5b88d6885bd89cc2','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4555,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-27','2028-10-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-27/','3423eb74d5a93b5595ae45bcfc51e8351aaf85f04cddbec530c500411d974607','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4556,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-10-28','2028-10-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-28/','d0c7ba34c96cb871f0c236f3623d96e02a0f81d7087b7bd5f682b61f424ef1dd','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4557,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-10-30','2028-10-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-30/','e0f38ca218352d0bb4812e225885654e35f5457ed1dec2a5e5dd0127b5829f90','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4558,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2028-10-30','2028-10-30','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-30/','d66ae45e69c5c6ca958f894bc14a9c7eadb66208239a28867c1933b66e49f4aa','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4559,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2028-10-30','2028-10-30','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-30/','6e03dc5a2c70b82e16f4851bc9465437525b712bc10285331f30059aa8a24759','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4560,'https://stutenseekinderkalender.de','Kinder- und Jugendtraining – Wilde 13','2028-10-30','2028-10-30','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-30/','2aca8018421ca14c8efd77d08088c9375d23f37f29cbd65e398e362b12a4e145','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4561,'https://stutenseekinderkalender.de','Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück','2028-10-31','2028-10-31','09:00','Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297','Heilig-Geist-Gemeinde Büchig',unistr('Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.\u000aAuch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.\u000aZurzeit in der Belchenstraße (privat bei Melanie Reuter).\u000aKontakt zum Veranstalter\u000a\u000aAnsprechpartnerin: Melanie Reuter\u000aE-Mail: info@krabbelkäfer-stutensee.de\u000aoder übers Pfarramt\u000a\u000a \u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.'),'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2028-10-31/','18d9dbf15b3988386a731832f570df2bdc8c9b0d368a6d896a34be02158d40ce','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4562,'https://stutenseekinderkalender.de','Krabbelgruppe in Spöck','2028-10-31','2028-10-31','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-31/','7a21db9865e7690a17a695faca9df991fdf1ee918e630e21b90e1722a5b0ce97','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4563,'https://stutenseekinderkalender.de','Seepferdchengarde (6–10 Jahre)','2028-10-31','2028-10-31','16:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-10-31/','0d419a9dd13a35ce27fa154842da662d65e753daac6c1043d934bfc0cb481d10','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4564,'https://stutenseekinderkalender.de','Schach für Schüler, Jugendliche & Anfänger','2028-10-31','2028-10-31','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-31/','5fa0d9aec48fe8410ef614da27425e93eb3562f53166cdfea3788ba9515c47da','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4565,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe Wölflinge','2028-10-31','2028-10-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-31/','c633ff5b145c497a79847c12c4bd160b5df4047bf69ec9ba5425439bc00dad31','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4566,'https://stutenseekinderkalender.de','Pfadfinder*innengruppe (11–15 Jahre)','2028-10-31','2028-10-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-31/','a57a4322685b36d3ee5a4a91aa6def864f2ee41fdb2f0ae245e9c9e2acb3bffe','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4567,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-10-31','2028-10-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-31/','e62fde1223cfcbd3d6bc436bd4df2fa94dabd5ced201767dc9f99ee511bf3283','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4568,'https://stutenseekinderkalender.de','Selbsthilfegruppe für Angehörige von AD(H)S-Kindern','2028-10-31','2028-10-31','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-31/','39a8c5defea71b1b1a159df7a09325d4b8a13bf6e276f668381934ec98673285','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4569,'https://stutenseekinderkalender.de','Krabbelgruppe im ev. Gemeindehaus Staffort','2028-11-01','2028-11-01','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-11-01/','e5087f0d09e9ef159fa37d4e55c1a4285ee8e87a14dee94f7365e11b7ebc336f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4570,'https://stutenseekinderkalender.de','Eltern-Kind-Kreis in Friedrichstal','2028-11-01','2028-11-01','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-11-01/','f2f892033d01c93c5f80c7f0ef2488dfcf411e2a036e914ae5e4dc777b59f5db','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4571,'https://stutenseekinderkalender.de','Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal','2028-11-02','2028-11-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-02/','82f3cb7bb1ec765278f0965e78c4ceef498b0fa4197b49ad94439c63f04cebc3','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4572,'https://stutenseekinderkalender.de','Krabbelgruppe Stutensee-Blankenloch','2028-11-02','2028-11-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-11-02/','0a864b4916a57468fb4d4d4efe2e17839e501115ab8857c5dc99ca0180d4eff2','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4573,'https://stutenseekinderkalender.de','Tee- und Spielstube','2028-11-02','2028-11-02','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-11-02/','6c0cfc496cebc12671d19f33769e56e9eda1be3993e48596a04de9dc47bbf9a6','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4574,'https://stutenseekinderkalender.de','Seesternchengarde (3–6 Jahre)','2028-11-02','2028-11-02','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-11-02/','69cb603047e15c78206aaf4e26df49221fa6759ce6b8f63c685e76cc770c8d7c','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4575,'https://stutenseekinderkalender.de','Teen Girls im GrauBau','2028-11-02','2028-11-02','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-11-02/','db53da3e3ef1bfabe5cc47ef80dcc379af253290ba9c049c262cba55e55ae299','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4576,'https://stutenseekinderkalender.de','Korallengarde (10–14 Jahre)','2028-11-02','2028-11-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-02/','bb9146e69919d0ce2742ef1eb10a2ba8d28ac5fd2f3f9f9f2d6c57bf69ba8e2f','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4577,'https://stutenseekinderkalender.de','Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)','2028-11-02','2028-11-02','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-11-02/','cbed7056f44fc6048a8a85cd79a1196db4e2501bfe727bcd4f5a40afd1fa52ec','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4578,'https://stutenseekinderkalender.de','Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee','2028-11-03','2028-11-03','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-11-03/','15bdc55ef6cf2cbcaef3b5e03974477a99e665f166923d974c51e7ff6b589deb','2026-04-25 16:35:37');
INSERT INTO raw_events VALUES(4579,'https://stutenseekinderkalender.de','Kreativfreitag im GrauBau','2028-11-03','2028-11-03','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-11-03/','f35369065abf5b9d4b434cc24eb15688c348e61c5dcbbd946e604e8fa83858bf','2026-04-25 16:35:37');
