INSERT INTO raw_events VALUES(4581,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2028-11-04','2028-11-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-11-04/','2ae3d1b7096836627cf72d2f2dfa56c762b997b41dd4ec555ce1b0b53e55c876','2026-04-25 16:35:37');
