INSERT INTO raw_events VALUES(9774,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2029-03-10','2029-03-10','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-03-10/','f3352a430cddf05c4bebfd498e711f6e95e22c39d23ae855b84127cbaf3f3e12','2026-04-25 16:54:43');
