INSERT INTO raw_events VALUES(10174,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2029-06-30','2029-06-30','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-06-30/','2340dc9db9fe7eb6882459e316d1606e5bf92c8d26ede7cdb0b52c69fab55656','2026-04-25 16:54:43');
