INSERT INTO raw_events VALUES(10224,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2029-07-14','2029-07-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-07-14/','c374f3c75cbb746e887175d42afb9272b348b76221dbf8aac88c717bce64a0de','2026-04-25 16:54:43');
