INSERT INTO raw_events VALUES(10424,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2029-09-08','2029-09-08','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-09-08/','13fcaf85e914b4b6a53282ec53749b97dce3d7752ce91dc9c0df9d59be52720e','2026-04-25 16:54:43');
