INSERT INTO raw_events VALUES(10624,'https://stutenseekinderkalender.de','Tanzen für die Kleinsten (4-6 Jahre)','2029-11-03','2029-11-03','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-11-03/','8a705f4e1743669df6882d5bed2a2925b451d864dddb76c948f391d37eae343c','2026-04-25 16:54:43');
