INSERT INTO raw_events VALUES(10826,'https://stutenseekinderkalender.de','Eltern-Baby-Café','2029-12-31','2029-12-31','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-12-31/','6075479387fc91ba45df5cc9fbc0efec6fdf7b7d0af3b2908e86f2e4cc4fda9d','2026-04-25 16:54:43');
INSERT INTO raw_events VALUES(10827,'https://stutenseekinderkalender.de','Spiele-Treff vom Teenie bis zum Oldie','2029-12-31','2029-12-31','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-12-31/','ad08415459d33a1472149b11b955325987766bc2edbc61a8d0ee5cf1261a7454','2026-04-25 16:54:43');
