INSERT INTO curated_events VALUES(12430,'Spielzeit im GrauBau',NULL,'2025-10-01','2025-10-01','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aDas Programm im Oktober: Jeden Mittwoch, 15:00 – 17:00 Uhr\u000a\u000a01.10. Stoffe gestalten mit Linoldruck (gerne eigene T-Shirts oder Baumwolltaschen mitbringen)\u000a08.10. Kinotag mit Popcorn\u000a15.10. Natur- und Basteltag\u000a22.10. Wir kochen gemeinsam Kürbissuppe à la GrauBau\u000a\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau/2025-10-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Natur,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12431,'Girls Club im GrauBau',NULL,'2025-10-02','2025-10-02','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Girls Club treffen sich Mädchen zwischen 10 und 13 Jahren, um gemeinsam kreativ zu sein, Neues auszuprobieren und einfach Spaß zu haben.\u000aJede Woche gibt es ein besonderes Thema oder Angebot. Jeden Donnerstag, 15:30 – 17:30 Uhr: \u000a\u000a02.10. Der Girls Club sucht das Supertalent\u000a09.10. Schmuckdesign – wir stellen eigenen Schmuck her\u000a16.10. Beauty- und Hair-Workshop mit einem Make-up-Artist\u000a23.10. Wir kochen gemeinsam Kürbissuppe\u000a\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweise\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/girls-club-im-graubau/2025-10-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Treff,Workshop',12431,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12432,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2025-10-02','2025-10-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2025-10-02/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
