INSERT INTO curated_events VALUES(12633,'Familientag mit Kleintierschau',NULL,'2025-11-23','2025-11-23','11:00','Kleintierzuchtverein Friedrichstal e.V., Am Waldfestpl. 1, Stutensee, 76297','Kleintierzuchtverein Friedrichstal e.V.',unistr('Ein schöner Tag für die ganze Familie erwartet euch beim Familientag des Kleintierzuchtvereins Friedrichstal.Neben der Kleintierschau und den Vereinsmeisterschaften gibt es viele Tiere zum Anfassen sowie spannende Infos rund um Haltung und Zucht.\u000aFür das leibliche Wohl ist bestens gesorgt – mit hausgemachtem Wildgulasch, Semmelknödeln mit Pilzrahm, weiteren Leckereien aus der Küche sowie Kaffee und Kuchen.\u000a'),'https://stutenseekinderkalender.de/event/familientag-mit-kleintierschau/','https://stutenseekinderkalender.de','Essen,Fest,Friedrichstal,Kinder,Natur,Treff,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
