INSERT INTO curated_events VALUES(12718,'Seepferdchengarde (6–10 Jahre)',NULL,'2025-12-09','2025-12-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2025-12-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(12719,'Krabbelgruppe in Spöck',NULL,'2025-12-09','2025-12-09','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2025-12-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12720,'Lebendiger Adventskalender Friedrichstal',NULL,'2025-12-09','2025-12-09','17:45','Friedrichstal, Stutensee-Friedrichstal, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Jeden Abend um 17.45 Uhr ist ein adventlich gestaltetes Fenster Treffpunkt, um in der folgenden Viertelstunde gemeinsam die Vorfreude auf Heiligabend mit Geschichten und Liedern zu feiern.\u000a\u000aKommen Sie doch einfach vorbei – egal ob Sie die Gastgeber bereits kennen oder an diesem Abend kennen lernen!\u000a\u000a'),'https://stutenseekinderkalender.de/event/lebendiger-adventskalender-friedrichstal/2025-12-09/','https://stutenseekinderkalender.de','Bildung,Fest,Friedrichstal,Kirche,Musik,Sport,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12721,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2025-12-09','2025-12-09','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2025-12-09/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12723,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2025-12-09','2025-12-09','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2025-12-09/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12724,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2025-12-10','2025-12-10','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2025-12-10/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12725,'Entdecke, gestalte, mach mit! Ideen zur Mediennutzung für Familien mit Vorschulkindern',NULL,'2025-12-10','2025-12-10','20:00','Online','Kinderbüro ON AIR',unistr('In dieser Online-Veranstaltung erhalten Familien mit Vorschulkindern praktische Ideen, wie digitale Medien kreativ genutzt werden können. Spielerisch entstehen Bilderbuchkinos, Trickfilme, Klang- und Hörgeschichten, selbst gemachte Memorys oder Wimmelbilder – alles leicht umsetzbar mit Smartphone oder Tablet.\u000aDie Kinder entdecken: Mit Medien kann man selbst gestalten. So lernen sie, wie Filme aus Einzelbildern bestehen, Töne für Hörspiele entstehen und Bilder oder Videos montiert werden können.\u000aReferentinDr. Kirsten Bresch, Stadtmedienzentrum Karlsruhe\u000aZielgruppeEltern mit Kindern im Alter von 3 bis 6 Jahren'),'https://stutenseekinderkalender.de/event/entdecke-gestalte-mach-mit-ideen-zur-mediennutzung-fuer-familien-mit-vorschulkindern/','https://stutenseekinderkalender.de','Bildung,Digital,Handwerk,Kinder,Kultur,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12726,'Family Adventskalender Spöck',NULL,'2025-12-10','2025-12-10','15:30','Spöck, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Entdeckt den Advent auf besondere Weise mit dem CVJM Family Adventskalender.\u000aWann? Täglich vom 1. bis 24. Dezember, zwischen 15:30 und 18:30 Uhr\u000aWo? Adventskalender-Stationen des CVJM Spöck\u000aFreut euch auf ein buntes Programm mit Geschichten, Liedern, Gedichten und mehr für die ganze Familie.\u000aLasst euch überraschen und kommt vorbei!\u000a '),'https://stutenseekinderkalender.de/event/family-adventskalender-spoeck/2025-12-10/','https://stutenseekinderkalender.de','Kinder,Musik,Spöck,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12727,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2025-12-10','2025-12-10','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2025-12-10/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12728,'Lebendiger Adventskalender Friedrichstal',NULL,'2025-12-10','2025-12-10','17:45','Friedrichstal, Stutensee-Friedrichstal, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Jeden Abend um 17.45 Uhr ist ein adventlich gestaltetes Fenster Treffpunkt, um in der folgenden Viertelstunde gemeinsam die Vorfreude auf Heiligabend mit Geschichten und Liedern zu feiern.\u000a\u000aKommen Sie doch einfach vorbei – egal ob Sie die Gastgeber bereits kennen oder an diesem Abend kennen lernen!\u000a\u000a'),'https://stutenseekinderkalender.de/event/lebendiger-adventskalender-friedrichstal/2025-12-10/','https://stutenseekinderkalender.de','Bildung,Fest,Friedrichstal,Kirche,Musik,Sport,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12729,'MamaMachts – Weihnachtspost mit Herz',NULL,'2025-12-10','2025-12-10','15:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','MamaMachts',unistr('Wir gestalten kreative Weihnachtskarten mit Fingerfarben, Papierfiligran und einem kleinen Polaroid-Foto als Erinnerung. Dein Kind darf mitpatschen und eigene kleine Kunstwerke erschaffen.\u000aDer Kreativtreff lädt zum gemeinsamen Gestalten und Wohlfühlen ein – ein kreativer Mama-Moment mit viel Herz.\u000aTeilnahme & Anmeldung\u000a\u000aTeilnahmebeitrag: 5 € pro Termin\u000aGetränke & Snacks nach Verzehr\u000aAnmeldung bitte vorab, begrenzte Plätze.\u000a'),'https://stutenseekinderkalender.de/event/mamamachts-weihnachtspost-mit-herz/','https://stutenseekinderkalender.de','Handwerk,Kinder,Kultur,Politik,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12730,'Offene Sprechstunde der Psychologischen Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe',NULL,'2025-12-10','2025-12-10','12:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Psychologische Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe',unistr('\u000aHast du Stress mit deinen Eltern, Probleme in der Schule oder im Freundeskreis oder belasten dich andere Dinge, die dir Druck machen?\u000aHaben Sie Fragen zur Entwicklung und Erziehung Ihrer Kinder, beunruhigen Sie Verhaltensauffälligkeiten oder sorgen Sie sich bezüglich Kindergarten, Schule oder Ausbildung?\u000a\u000aIm Rahmen unserer offenen Sprechstunden bieten wir Eltern, Kindern und Jugendlichen, aber auch Mitarbeiterinnen und Mitarbeiter sozialer Institutionen, Kindergärten sowie Schulen eine Beratung vor Ort und ohne Voranmeldung an.\u000aDie Gespräche sind vertraulich und kostenfrei.\u000aAlle Mitarbeiterinnen und Mitarbeiter unterliegen der Schweigepflicht.'),'https://stutenseekinderkalender.de/event/offene-sprechstunde-der-psychologischen-beratungsstelle-fuer-eltern-kinder-und-jugendliche-des-landkreises-karlsruhe/2025-12-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Natur,Politik,Treff,Wohltätigkeit,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12731,'Spielzeit im GrauBau',NULL,'2025-12-10','2025-12-10','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aDas Programm im Oktober und Dezember: Jeden Mittwoch, 15:00 – 17:00 Uhr\u000a05. November: Wir machen Origami: Tolle Dinge aus Papier\u000a12. November: Wir machen Spaß: Talentshow Karaoke &Co\u000a19. November: Wir machen Druck: Wir bringen coole Sachen auf die Leinwand\u000a26. November: Monster, Dinos & Co. Wir gestalten witzige Handpuppen (Bringt bitte eine Socke mit!)\u000a03. Dezember: Filmzeit im GrauBau: Kino & Popcorn\u000a10. Dezember: Weihnachtsbäckerei: Wir backen leckere Plätzchen\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-2/2025-12-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12732,'Weihnachtsabend am Schloss Stutensee',NULL,'2025-12-10','2025-12-10','17:00','Jugendeinrichtung Schloss Stutensee gGmbH, Schloss Stutensee, Stutensee, 76297','Jugendeinrichtung Schloss Stutensee gGmbH',unistr('\u000a\u000aAm Mittwoch, den 10. Dezember 2025, laden wir Sie wieder herzlich zu unserem stimmungsvollen Weihnachtsabend am Schloss ein. Lassen Sie sich von der festlichen Beleuchtung, wärmenden Feuerschalen und dem prachtvollen Weihnachtsbaum verzaubern!\u000aHighlights des Abends:\u000a\u000aKleiner Weihnachtsmarkt mit handgemachten Geschenken\u000aKulinarische Köstlichkeiten wie Pommes, Bratwürste, Rahmflecken, Kartoffelsuppe, Waffeln und gebrannte Mandeln\u000aGlühwein- und Punschstand des Lions Club Stutensee Hardt – alle Einnahmen kommen unseren Kindern und Jugendlichen zugute\u000aMusikalische Eröffnung durch den Musikverein Blankenloch\u000aBesuch des Nikolaus und Knecht Ruprecht mit kleinen Überraschungen für die Kinder\u000aBunt beleuchtete Traktoren der Bulldogfreunde Stutensee als besonderer Hingucker\u000a\u000aGenießen Sie die vorweihnachtliche Stimmung, schlendern Sie über den Markt und lassen Sie sich von der einzigartigen Atmosphäre verzaubern. Wir freuen uns auf Ihren Besuch!\u000a'),'https://stutenseekinderkalender.de/event/festliche-atmosphaere-und-besinnliche-begegnungen-weihnachtsabend-am-schloss-stutensee/','https://stutenseekinderkalender.de','Essen,Fest,Kinder,Markt,Musik,Natur,Politik,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12733,'Family Adventskalender Spöck',NULL,'2025-12-11','2025-12-11','15:30','Spöck, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Entdeckt den Advent auf besondere Weise mit dem CVJM Family Adventskalender.\u000aWann? Täglich vom 1. bis 24. Dezember, zwischen 15:30 und 18:30 Uhr\u000aWo? Adventskalender-Stationen des CVJM Spöck\u000aFreut euch auf ein buntes Programm mit Geschichten, Liedern, Gedichten und mehr für die ganze Familie.\u000aLasst euch überraschen und kommt vorbei!\u000a '),'https://stutenseekinderkalender.de/event/family-adventskalender-spoeck/2025-12-11/','https://stutenseekinderkalender.de','Kinder,Musik,Spöck,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12734,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2025-12-11','2025-12-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2025-12-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12735,'Korallengarde (10–14 Jahre)',NULL,'2025-12-11','2025-12-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2025-12-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12736,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2025-12-11','2025-12-11','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2025-12-11/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12737,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2025-12-11','2025-12-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2025-12-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12738,'Lebendiger Adventskalender Friedrichstal',NULL,'2025-12-11','2025-12-11','17:45','Friedrichstal, Stutensee-Friedrichstal, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Jeden Abend um 17.45 Uhr ist ein adventlich gestaltetes Fenster Treffpunkt, um in der folgenden Viertelstunde gemeinsam die Vorfreude auf Heiligabend mit Geschichten und Liedern zu feiern.\u000a\u000aKommen Sie doch einfach vorbei – egal ob Sie die Gastgeber bereits kennen oder an diesem Abend kennen lernen!\u000a\u000a'),'https://stutenseekinderkalender.de/event/lebendiger-adventskalender-friedrichstal/2025-12-11/','https://stutenseekinderkalender.de','Bildung,Fest,Friedrichstal,Kirche,Musik,Sport,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12739,'Seesternchengarde (3–6 Jahre)',NULL,'2025-12-11','2025-12-11','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2025-12-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12740,'Tee- und Spielstube',NULL,'2025-12-11','2025-12-11','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2025-12-11/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12741,'Teen Girls im GrauBau',NULL,'2025-12-11','2025-12-11','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2025-12-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12742,'Zahnpflege bei Kindern',NULL,'2025-12-11','2025-12-11','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Frühe Hilfen Landkreis Karlsruhe',unistr('Eltern-Kind-Treff mit dem Thema „Zahnpflege bei Kindern“. Frau Wolf (Zahnärztin Gesundheitsamt) informiert über die richtige Zahnpflege von Anfang an.\u000aHinweis: Teilnahme kostenfrei, Anmeldung erwünscht.\u000a'),'https://stutenseekinderkalender.de/event/zahnpflege-bei-kindern/','https://stutenseekinderkalender.de','Kinder,Politik,Treff,Wohltätigkeit',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12743,'Babys in Bewegung (Block III): Für Herbst- und Winterkinder 2024/25 (Jan-Mär 2025)',NULL,'2025-12-12','2025-12-12','10:45','TSG Blankenloch, Mühlenweg 4a, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Im Kurs Babys in Bewegung – Block III entdecken die Jüngsten spielerisch ihren Körper und ihre Umgebung. Mit Bewegungsangeboten, Liedern und Sinnesanregungen fördert der Kurs die motorische Entwicklung und stärkt die Bindung zwischen Eltern und Kind in entspannter Atmosphäre.\u000aStart: voraussichtlich Freitag, 5. Dezember 2025, 10:45 UhrUmfang: 8 Termine jeweils 75 MinutenOrt: Kleiner Saal, TSG BlankenlochKursgebühr: 130 €\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com'),'https://stutenseekinderkalender.de/event/babys-in-bewegung-block-iii-fuer-herbst-und-winterkinder-2024-25-jan-maer-2025/2025-12-12/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Workshop',12696,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12744,'Babys in Bewegung – Juniors (ab ca. 12 Monaten)',NULL,'2025-12-12','2025-12-12','09:15','TSG Blankenloch, Mühlenweg 4a, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Sanfte Bewegung, Spiel und Sinnesanregungen für die Kleinsten: Im Kurs „Babys in Bewegung – Juniors“ entdecken Kinder ab etwa 12 Monaten gemeinsam mit ihrer Bezugsperson neue Bewegungslandschaften, Rhythmus und Körperwahrnehmung. Im Mittelpunkt stehen Freude an Bewegung, altersgerechte Impulse und Zeit für Austausch.\u000aStart: Freitag, 5. Dezember 2025, 9:15 UhrUmfang: 8 Termine jeweils 75 MinutenOrt: Kleiner Saal, TSG BlankenlochGebühr: 130 €\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com'),'https://stutenseekinderkalender.de/event/babys-in-bewegung-juniors-ab-ca-12-monaten/2025-12-12/','https://stutenseekinderkalender.de','Kinder,Sport,Workshop',12697,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12745,'Büchiger Adventsfest',NULL,'2025-12-12','2025-12-12','19:00','Familie Hassmann, Waldstraße 106, Stutensee-Büchig, 76297','Büchig(er)leben',unistr('Es wird weihnachtlich in Büchig. Mit Glühwein, Punsch, Gegrilltem, Waffeln und natürlich ganz viel Adventsstimmung. Wir freuen uns sehr, dass der Musikverein Harmonie Blankenloch e. V. uns um 19 Uhr mit tollen Klängen die Weihnachtszeit versüßt.\u000a'),'https://stutenseekinderkalender.de/event/buechiger-adventsfest/','https://stutenseekinderkalender.de','Büchig,Essen,Fest,Kinder,Musik,Natur,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12746,'Eltern-Baby-Treff',NULL,'2025-12-12','2025-12-12','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2025-12-12/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12747,'Family Adventskalender Spöck',NULL,'2025-12-12','2025-12-12','15:30','Spöck, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Entdeckt den Advent auf besondere Weise mit dem CVJM Family Adventskalender.\u000aWann? Täglich vom 1. bis 24. Dezember, zwischen 15:30 und 18:30 Uhr\u000aWo? Adventskalender-Stationen des CVJM Spöck\u000aFreut euch auf ein buntes Programm mit Geschichten, Liedern, Gedichten und mehr für die ganze Familie.\u000aLasst euch überraschen und kommt vorbei!\u000a '),'https://stutenseekinderkalender.de/event/family-adventskalender-spoeck/2025-12-12/','https://stutenseekinderkalender.de','Kinder,Musik,Spöck,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12748,'Kreativfreitag im GrauBau',NULL,'2025-12-12','2025-12-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2025-12-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12749,'Lebendiger Adventskalender Friedrichstal',NULL,'2025-12-12','2025-12-12','17:45','Friedrichstal, Stutensee-Friedrichstal, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Jeden Abend um 17.45 Uhr ist ein adventlich gestaltetes Fenster Treffpunkt, um in der folgenden Viertelstunde gemeinsam die Vorfreude auf Heiligabend mit Geschichten und Liedern zu feiern.\u000a\u000aKommen Sie doch einfach vorbei – egal ob Sie die Gastgeber bereits kennen oder an diesem Abend kennen lernen!\u000a\u000a'),'https://stutenseekinderkalender.de/event/lebendiger-adventskalender-friedrichstal/2025-12-12/','https://stutenseekinderkalender.de','Bildung,Fest,Friedrichstal,Kirche,Musik,Sport,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12750,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2025-12-12','2025-12-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2025-12-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12751,'Seepferdchengarde (6–10 Jahre)',NULL,'2025-12-12','2025-12-12','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2025-12-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12752,'Blankenlocher Weihnachtsmarkt 2025',NULL,'2025-12-13','2025-12-13','15:00','Blankenloch, Stutensee-Blankenloch, 76297','Stadt Stutensee',unistr('Der Blankenlocher Weihnachtsmarkt lädt zu einem stimmungsvollen Adventswochenende ein – mit Musik, warmem Punsch, vielen Leckereien und abwechslungsreichen Programmpunkten für Kinder und Familien.\u000aHighlights laut Programm:Samstag, 13.12.\u000a\u000a14:30 Uhr: Enthüllung der neuen Namenstafel (Altes Rathaus)\u000a15:30 Uhr: Offizielle Eröffnung & Kinderchor der Pestalozzi-Grundschule\u000aIm Anschluss: Besuch des Weihnachtsmanns\u000aErzähltheater für Kinder, Bücherflohmarkt & Weihnachtskonzert des TMG\u000a\u000aSonntag, 14.12.\u000a\u000aBücherflohmarkt in der Stadtbibliothek\u000aErzähltheater für Kinder\u000a16:30 Uhr: Weihnachtliches Singen in der Michaeliskirche\u000a18:00 Uhr: Adventschoralblasen\u000a\u000aAn beiden Tagen geöffnet:– Kerns-Max-Haus (inkl. Museumscafé & Ausstellung)– Gebäude Hauptstraße 86 mit Kunstausstellung\u000aDer Weihnachtsmarkt bietet zudem viele Stände mit Essen, Getränken, Selbstgemachtem und lokalen Vereinen.\u000aFlyer Blankenlocher Weihnachtsmarkt 2025'),'https://stutenseekinderkalender.de/event/blankenlocher-weihnachtsmarkt-2025/2025-12-13/','https://stutenseekinderkalender.de','Bildung,Essen,Fest,Kinder,Kirche,Kultur,Markt,Musik,Politik,Treff,Verein,Wohltätigkeit',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
