INSERT INTO curated_events VALUES(12778,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2025-12-18','2025-12-18','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2025-12-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12779,'Korallengarde (10–14 Jahre)',NULL,'2025-12-18','2025-12-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2025-12-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12780,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2025-12-18','2025-12-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2025-12-18/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12781,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2025-12-18','2025-12-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2025-12-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12782,'Lebendiger Adventskalender Friedrichstal',NULL,'2025-12-18','2025-12-18','17:45','Friedrichstal, Stutensee-Friedrichstal, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Jeden Abend um 17.45 Uhr ist ein adventlich gestaltetes Fenster Treffpunkt, um in der folgenden Viertelstunde gemeinsam die Vorfreude auf Heiligabend mit Geschichten und Liedern zu feiern.\u000a\u000aKommen Sie doch einfach vorbei – egal ob Sie die Gastgeber bereits kennen oder an diesem Abend kennen lernen!\u000a\u000a'),'https://stutenseekinderkalender.de/event/lebendiger-adventskalender-friedrichstal/2025-12-18/','https://stutenseekinderkalender.de','Bildung,Fest,Friedrichstal,Kirche,Musik,Sport,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12783,'Seesternchengarde (3–6 Jahre)',NULL,'2025-12-18','2025-12-18','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2025-12-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12784,'Tee- und Spielstube',NULL,'2025-12-18','2025-12-18','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2025-12-18/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12785,'Teen Girls im GrauBau',NULL,'2025-12-18','2025-12-18','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2025-12-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12786,'Babys in Bewegung (Block III): Für Herbst- und Winterkinder 2024/25 (Jan-Mär 2025)',NULL,'2025-12-19','2025-12-19','10:45','TSG Blankenloch, Mühlenweg 4a, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Im Kurs Babys in Bewegung – Block III entdecken die Jüngsten spielerisch ihren Körper und ihre Umgebung. Mit Bewegungsangeboten, Liedern und Sinnesanregungen fördert der Kurs die motorische Entwicklung und stärkt die Bindung zwischen Eltern und Kind in entspannter Atmosphäre.\u000aStart: voraussichtlich Freitag, 5. Dezember 2025, 10:45 UhrUmfang: 8 Termine jeweils 75 MinutenOrt: Kleiner Saal, TSG BlankenlochKursgebühr: 130 €\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com'),'https://stutenseekinderkalender.de/event/babys-in-bewegung-block-iii-fuer-herbst-und-winterkinder-2024-25-jan-maer-2025/2025-12-19/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Workshop',12696,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12787,'Babys in Bewegung – Juniors (ab ca. 12 Monaten)',NULL,'2025-12-19','2025-12-19','09:15','TSG Blankenloch, Mühlenweg 4a, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Sanfte Bewegung, Spiel und Sinnesanregungen für die Kleinsten: Im Kurs „Babys in Bewegung – Juniors“ entdecken Kinder ab etwa 12 Monaten gemeinsam mit ihrer Bezugsperson neue Bewegungslandschaften, Rhythmus und Körperwahrnehmung. Im Mittelpunkt stehen Freude an Bewegung, altersgerechte Impulse und Zeit für Austausch.\u000aStart: Freitag, 5. Dezember 2025, 9:15 UhrUmfang: 8 Termine jeweils 75 MinutenOrt: Kleiner Saal, TSG BlankenlochGebühr: 130 €\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com'),'https://stutenseekinderkalender.de/event/babys-in-bewegung-juniors-ab-ca-12-monaten/2025-12-19/','https://stutenseekinderkalender.de','Kinder,Sport,Workshop',12697,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12788,'Eltern-Baby-Treff',NULL,'2025-12-19','2025-12-19','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2025-12-19/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12789,'Family Adventskalender Spöck',NULL,'2025-12-19','2025-12-19','15:30','Spöck, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Entdeckt den Advent auf besondere Weise mit dem CVJM Family Adventskalender.\u000aWann? Täglich vom 1. bis 24. Dezember, zwischen 15:30 und 18:30 Uhr\u000aWo? Adventskalender-Stationen des CVJM Spöck\u000aFreut euch auf ein buntes Programm mit Geschichten, Liedern, Gedichten und mehr für die ganze Familie.\u000aLasst euch überraschen und kommt vorbei!\u000a '),'https://stutenseekinderkalender.de/event/family-adventskalender-spoeck/2025-12-19/','https://stutenseekinderkalender.de','Kinder,Musik,Spöck,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12790,'Kreativfreitag im GrauBau',NULL,'2025-12-19','2025-12-19','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2025-12-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12791,'Lebendiger Adventskalender Friedrichstal',NULL,'2025-12-19','2025-12-19','17:45','Friedrichstal, Stutensee-Friedrichstal, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Jeden Abend um 17.45 Uhr ist ein adventlich gestaltetes Fenster Treffpunkt, um in der folgenden Viertelstunde gemeinsam die Vorfreude auf Heiligabend mit Geschichten und Liedern zu feiern.\u000a\u000aKommen Sie doch einfach vorbei – egal ob Sie die Gastgeber bereits kennen oder an diesem Abend kennen lernen!\u000a\u000a'),'https://stutenseekinderkalender.de/event/lebendiger-adventskalender-friedrichstal/2025-12-19/','https://stutenseekinderkalender.de','Bildung,Fest,Friedrichstal,Kirche,Musik,Sport,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(12792,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2025-12-19','2025-12-19','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2025-12-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
