INSERT INTO curated_events VALUES(13067,'Bildschirmfrei und Spaß dabei',NULL,'2026-02-27','2026-02-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('\u000a\u000aAlle Angebote für Schüler:innen ab Klasse 5\u000aAnmeldung möglich bis: 18.02.2026, 23:00 Uhr\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/bildschirmfrei-und-spass-dabei/2026-02-27/','https://stutenseekinderkalender.de','Kinder',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13068,'Eltern-Baby-Treff',NULL,'2026-02-27','2026-02-27','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-02-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13069,'Kreativfreitag im GrauBau',NULL,'2026-02-27','2026-02-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-02-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13070,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-02-27','2026-02-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-02-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13071,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-02-27','2026-02-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-02-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13072,'Stadtputzete | Sauberes Stutensee',NULL,'2026-02-28',NULL,'','TSG Gelände, Blankenloch','TSG Blankenloch','Reinigung der Außen- und Freisportanlagen. Arbeitseinsatz.','https://www.tsg-blankenloch.de/Veranstaltungen/VeranstaltungenUebersicht/','https://www.tsg-blankenloch.de/','Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13073,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-02-28','2026-02-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-02-28/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13074,'Eltern-Baby-Café',NULL,'2026-03-02','2026-03-02','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-03-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13075,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-03-02','2026-03-02','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-03-02/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13076,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-02','2026-03-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13077,'Miniatur- & Holz-Workshop: Frühlings-Erwachen',NULL,'2026-03-02','2026-03-02','15:30','Blankenloch-Stutensee, 76297','Melanie Nagel',unistr('*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" tabindex="-1" data-turn-id="request-68c3e531-65d0-832d-8b53-53c50aae7a7c-1" data-testid="conversation-turn-464" data-scroll-anchor="true" data-turn="assistant">\u000a\u000a\u000a\u000a\u000a\u000a\u000aHier darf ein Holzbaum gestaltet werden. Dieser wird auf eine Holzplatte geklebt, welche sich in 90 Minuten in eine kreative und farbenfrohe Frühlingswiese verwandelt. Jedes Kind bekommt verschiedene Materialien, wie Holzstäbchen, einen Holzzaun, verschiedene Blumen- und Strauchelemente (Achtung: Deko kann immer etwas abweichen) sowie ein Set aus Raisin gegossener Tiere (zum Anmalen).\u000aKosten: 33 €; Geschwisterkinder 23€ (bei gleicher Begleitperson!)\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/miniatur-holz-workshop-fruehlings-erwachen/','https://stutenseekinderkalender.de','Handwerk,Kinder,Kultur,Musik,Natur,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13078,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-03-02','2026-03-02','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-03-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13079,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-03','2026-03-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13080,'Krabbelgruppe in Spöck',NULL,'2026-03-03','2026-03-03','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-03-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13081,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-03-03','2026-03-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-03-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13082,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-03-03','2026-03-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-03-03/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13083,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-03-03','2026-03-03','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-03-03/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13085,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-03-03','2026-03-03','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-03-03/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13086,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-03-04','2026-03-04','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-03-04/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13087,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-03-04','2026-03-04','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-03-04/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13088,'Spielzeit im GrauBau',NULL,'2026-03-04','2026-03-04','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-03-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13089,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-03-05','2026-03-05','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-03-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13090,'Korallengarde (10–14 Jahre)',NULL,'2026-03-05','2026-03-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13091,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-03-05','2026-03-05','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-03-05/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13092,'Kurs für Eltern mit Kinderbetreuung: Starke Eltern – Starke Kinder / Entspannte Eltern – Entspannte Kinder',NULL,'2026-03-05','2026-03-05','18:00','Städtischer Kindergarten &#8222;Märchenwald&#8220;, Sterntalerstraße 2, Stutensee-Büchig, 76297','Stadt Stutensee',unistr('Hier können Eltern Ihre Rolle neu reflektieren, sich von belastenden Denkmustern lösen und entdecken, wie sie mehr Freude, Ruhe und Wohlbefinden in ihr Leben und das der Kinder bringen können. Im Mittelpunkt stehen die Bedürfnisse von Kindern, der Umgang mit Gefühlen, Konflikten und Stress sowie das Setzen von Regeln und Grenzen. Themen wie Achtsamkeit, Selbstfürsorge, Resilienz, Elternburnout, Mediennutzung und praxisnahe Strategien für Gelassenheit und einen entspannten Familienalltag runden das Angebot ab. Sie lernen Bewältigungsstrategien bei Stress und Krisen, Entspannungstechniken und -methoden kennen, die für die Eltern und auch für die Kinder geeignet sind. Vielfältige (auch arbeitsplatztaugliche) Übungen können direkt ausprobiert werden.\u000aDer Kurs umfasst 10 Termine.\u000aKursleiterin ist Tatiana Schulmeister (Syst. Beraterin (AFS), Entspannungstherapeutin & -Pädagogin.\u000aEs wird eine Kinderbetreuung angeboten.\u000aAnmeldung und weitere Informationen direkt über schulmeister.tatiana@gmail.com oder Telefon 01578/8797656'),'https://stutenseekinderkalender.de/event/kurs-fuer-eltern-mit-kinderbetreuung-starke-eltern-starke-kinder-entspannte-eltern-entspannte-kinder/','https://stutenseekinderkalender.de','Bildung,Büchig,Essen,Kinder,Natur,Politik,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13093,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-05','2026-03-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13094,'Seesternchengarde (3–6 Jahre)',NULL,'2026-03-05','2026-03-05','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-03-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13095,'Tee- und Spielstube',NULL,'2026-03-05','2026-03-05','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-03-05/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13096,'Teen Girls im GrauBau',NULL,'2026-03-05','2026-03-05','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-03-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13097,'Eltern-Baby-Treff',NULL,'2026-03-06','2026-03-06','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-03-06/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13098,'Kreativfreitag im GrauBau',NULL,'2026-03-06','2026-03-06','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-03-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13099,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-03-06','2026-03-06','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-03-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13100,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-06','2026-03-06','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-03-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13101,'Großer Kinder-Flohmarkt Stutensee',NULL,'2026-03-07',NULL,NULL,'Festhalle Blankenloch, Badstraße 7, Stutensee, 76297','Flohmarkt Büchig (Kita Märchenwald & Kita Lachwald)',unistr('Die Kitas Lachwald und Märchenwald laden zum großen Flohmarkt „Rund ums große und kleine Kind“ in die Festhalle Stutensee-Blankenloch ein.Neben einem vielfältigen Angebot an Kinderbekleidung, Spielzeug und Ausstattung erwartet die Besucher ein riesiges Kuchenbuffet, heiße Würstchen mit Brötchen, sowie Maltisch und Kinderschminken für die kleinen Gäste.\u000aAnmeldung:Ab 26.02.2026 um 19:00 Uhr unter www.flohmarkt-buechig.de.'),'https://www.flohmarkt-buechig.de/','https://www.flohmarkt-buechig.de/,https://stutenseekinderkalender.de','Büchig,Fest,Markt,Natur',NULL,2,'2026-04-25 19:01:27','2026-04-25 19:10:14');
INSERT INTO curated_events VALUES(13105,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-03-07','2026-03-07','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-03-07/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13106,'Eltern-Baby-Café',NULL,'2026-03-09','2026-03-09','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-03-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13107,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-03-09','2026-03-09','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-03-09/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13108,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-09','2026-03-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13109,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-03-09','2026-03-09','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-03-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13110,'Jahreshauptversammlung 2026',NULL,'2026-03-10',NULL,'','Vereinsheim, TSG Blankenloch','TSG Blankenloch','Jahreshauptversammlung der TSG Blankenloch. Anmeldeschluss: 25.02.2026.','https://www.tsg-blankenloch.de/Veranstaltungen/VeranstaltungenUebersicht/','https://www.tsg-blankenloch.de/','Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13111,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-10','2026-03-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13112,'Krabbelgruppe in Spöck',NULL,'2026-03-10','2026-03-10','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-03-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13113,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-03-10','2026-03-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-03-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13114,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-03-10','2026-03-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-03-10/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13115,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-03-10','2026-03-10','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-03-10/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13117,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-03-10','2026-03-10','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-03-10/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13118,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-03-11','2026-03-11','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-03-11/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13119,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-03-11','2026-03-11','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-03-11/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13120,'Offene Sprechstunde der Psychologischen Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe',NULL,'2026-03-11','2026-03-11','12:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Psychologische Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe',unistr('Für Eltern, Kinder und Jugendliche bietet die psychologischen Beratungsstelle des Landkreises Karlsruhe bei Fragen zu Erziehung, Entwicklung, familiären und persönlichen Problemen monatlich eine offene Sprechstunde im Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V. an – kostenfrei, vertraulich und ohne Anmeldung.\u000aMittwoch 12 – 15 Uhr (einmal im Monat): 11. März, 15. April, 13. Mai, 10. Juni, 8. Juli, 16. September, 14. Oktober, 11. November, 9. Dezember 2026\u000aFlyer Offene Sprechstunde'),'https://stutenseekinderkalender.de/event/offene-sprechstunde-der-psychologischen-beratungsstelle-fuer-eltern-kinder-und-jugendliche-des-landkreises-karlsruhe-2/2026-03-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13121,'Spielzeit im GrauBau',NULL,'2026-03-11','2026-03-11','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-03-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13122,'Eltern-Kind-Treff „Frühe Hilfen“',NULL,'2026-03-12','2026-03-12','10:15','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Frühe Hilfen Landkreis Karlsruhe',unistr('Einmal im Monat treffen sich Mütter und Väter mit ihren Kindern im Alter von 0 – 2 Jahren unter der Leitung einer Sozialpädagogin.\u000aDie Treffen bieten Raum sich mit anderen Eltern auszutauschen und Fragen und Anliegen mit der pädagogischen Gruppenleitung zu besprechen. Sie erfahren Interessantes zu verschiedenen Themen rund um die Erziehung und Entwicklung und erhalten Spiel- und Beschäftigungsanregungen. Die Kinder haben währenddessen Zeit zum Spielen und Entdecken.\u000a\u000a12.03.2026 Von (Ab)stillen bis Zeckenschutz – Offene Fragerunde mit der Familienhebamme\u000a16.04.2026 Kommunikation mit Kindern unter 3 Jahren\u000a07.05.2026 Trageberatung\u000a11.06.2026 Umgang mit Medien Frau Bock\u000a02.07.2026 Sicher im Auto\u000a\u000aDie Teilnahme ist kostenlos.\u000aEine Anmeldung ist erwünscht.\u000aFlyer Eltern-Kind-Treff Frühe Hilfen 2026'),'https://stutenseekinderkalender.de/event/eltern-kind-treff-fruehe-hilfen/2026-03-12/','https://stutenseekinderkalender.de','Essen,Kinder,Politik,Treff,Wohltätigkeit',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13123,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-03-12','2026-03-12','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-03-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13124,'Korallengarde (10–14 Jahre)',NULL,'2026-03-12','2026-03-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13125,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-03-12','2026-03-12','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-03-12/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13126,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-12','2026-03-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13127,'Seesternchengarde (3–6 Jahre)',NULL,'2026-03-12','2026-03-12','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-03-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13128,'Tee- und Spielstube',NULL,'2026-03-12','2026-03-12','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-03-12/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13129,'Teen Girls im GrauBau',NULL,'2026-03-12','2026-03-12','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-03-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13130,'Eltern-Baby-Treff',NULL,'2026-03-13','2026-03-13','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-03-13/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13131,'Kreativfreitag im GrauBau',NULL,'2026-03-13','2026-03-13','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-03-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13132,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-03-13','2026-03-13','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-03-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13133,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-13','2026-03-13','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-03-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13134,'Themenvormittage für Eltern von den Frühen Hilfen',NULL,'2026-03-13','2026-03-13','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Mit Kindern von 0 – 3 Jahren, freitags 9:30 Uhr, 1 montl.\u000aTermine 2026:\u000a16.01., 13.03., 08.05., 10.07.26\u000aKostenfrei und ohne Anmeldung!'),'https://stutenseekinderkalender.de/event/themenvormittage-fuer-eltern-von-den-fruehen-hilfen/2026-03-13/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Politik,Sport,Treff,Wohltätigkeit',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13135,'Flohmarkt in Friedrichstal',NULL,'2026-03-14','2026-03-14','13:00','Friedrich-Magnus-Grundschule Friedrichstal, Straße der Picardie 1, Stutensee-Friedrichstal, 76297','Förderverein Friedrich-Magnus Schule',unistr('Am 14. März 2026 ab 13:00 Uhr findet auf dem Schulgelände der Friedrich-Magnus-Schule in Friedrichstal ein Flohmarkt statt. Hier könnt ihr nach Herzenslust stöbern, verkaufen und vielleicht den ein oder anderen Schatz entdecken.\u000a'),'https://stutenseekinderkalender.de/event/flohmarkt-in-friedrichstal/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Markt,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13136,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-03-14','2026-03-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-03-14/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13137,'Briefmarkentauschtage',NULL,'2026-03-16','2026-03-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Alle Kinder, Jugendlichen, Erwachsenen und Senioren, die sich für Briefmarken interessieren, mit dem Sammeln anfangen oder tauschen möchten, können gerne unverbindlich reinschauen.\u000a\u000aMontag 16 – 17 Uhr (einmal im Monat)\u000a16. März, 20. April, 11. Mai, 15. Juni, 13. Juli, 21. September, 12. Oktober, 16. November, 14. Dezember 2026\u000a\u000a '),'https://stutenseekinderkalender.de/event/briefmarkentauschtage/2026-03-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Senioren,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13138,'Eltern-Baby-Café',NULL,'2026-03-16','2026-03-16','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-03-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13139,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-03-16','2026-03-16','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-03-16/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13140,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-16','2026-03-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13141,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-03-16','2026-03-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-03-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13142,'Elterninfoabend: Bewusst am Bildschirm – Wieviel Bildschirmzeit ist denn gut für mein Kind?',NULL,'2026-03-17','2026-03-17','18:30','Mensa Schulzentrum Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Stadt Stutensee',unistr('Digitale Medien gehören heute selbstverständlich zum Alltag von Kindern und Jugendlichen. Sie bieten große Chancen, stellen Eltern aber auch vor vielfältige Herausforderungen, vor allem bei der Frage nach den Bildschirmzeiten. Wie viel ist eigentlich okay? Wo muss ich ein Limit setzen? Und wo muss ich mir Sorgen machen?\u000aDie Referentin Inga Klas vom Medienkompetenz Team Karlsruhe wird an diesem Abend die wichtigsten und neuesten Erkenntnisse zu dem Thema mitbringen. Zudem  werden Einblicke in Tools und Einstellungen vermittelt, die den Umgang erleichtern. Im Anschluss bleibt  genug Zeit für Fragen und offenen Austausch.\u000aReferentin: Inga Klas, Medienkompetenz Team Karlsruhe\u000aAnmeldung bitte bis 13.3.2026.\u000aKostenfrei\u000aIn Kooperation mit der Schulsozialarbeit Stutensee und dem Medienkompetenz Team Karlsruhe e.V.'),'https://stutenseekinderkalender.de/event/elterninfoabend-bewusst-am-bildschirm-wieviel-bildschirmzeit-ist-denn-gut-fuer-mein-kind/','https://stutenseekinderkalender.de','Digital,Kinder,Politik,Verein,Wohltätigkeit',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13143,'Erzähltheater zu den Internationalen Wochen gegen Rassismus in Blankenloch',NULL,'2026-03-17','2026-03-17','15:15','Stadtbibliothek Blankenloch, Gymnasiumstr. 2 b, Stutensee, 76297','Stadtbibliothek Blankenloch',unistr('\u000aIm Erzähltheater wird dieses Mal die Geschichte „Als die Raben noch bunt waren“ gezeigt. In der Geschichte geht es um wunderbar kunterbunte Raben, die sich eines Tages streiten, wer der schönste von ihnen sei. Und dann passiert etwas Unerwartetes…\u000aEine Geschichte über Toleranz, Vielfalt und Gemeinschaft für Kinder ab 5 Jahren.\u000aUm Anmeldung wird gebeten per Mail an maria.toth@stutensee.de oder telefonisch unter 07244/969-4270.\u000a\u000a'),'https://stutenseekinderkalender.de/event/erzaehltheater-zu-den-internationalen-wochen-gegen-rassismus-in-blankenloch/','https://stutenseekinderkalender.de','Kinder,Kirche,Kultur,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13144,'Kamishibai: Als die Raben noch bunt waren',NULL,'2026-03-17',NULL,NULL,'Stadtbibliothek Blankenloch','Stadtbibliothek Blankenloch','Kamishibai Erzähltheater ''Als die Raben noch bunt waren''','https://bibliotheken.komm.one/stutensee/R%C3%BCckblicke/Veranstaltungen-2026/Kamishibai-Als-die-Raben-noch-bunt-waren-am-170326','https://bibliotheken.komm.one/stutensee','Kultur',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13145,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-17','2026-03-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13146,'Krabbelgruppe in Spöck',NULL,'2026-03-17','2026-03-17','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-03-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13147,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-03-17','2026-03-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-03-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13148,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-03-17','2026-03-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-03-17/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13149,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-03-17','2026-03-17','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-03-17/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13151,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-03-17','2026-03-17','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-03-17/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13152,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-03-18','2026-03-18','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-03-18/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13153,'Erzähltheater zu den Internationalen Wochen gegen Rassismus in Spöck',NULL,'2026-03-18','2026-03-18','14:30','Stadtbibliothek Spöck, Heinrich-Heine-Straße 1, Stutensee-Spöck, 76297','Stadtbibliothek Spöck',unistr('\u000aIm Erzähltheater wird dieses Mal die Geschichte „Als die Raben noch bunt waren“ gezeigt. In der Geschichte geht es um wunderbar kunterbunte Raben, die sich eines Tages streiten, wer der schönste von ihnen sei. Und dann passiert etwas Unerwartetes…\u000aEine Geschichte über Toleranz, Vielfalt und Gemeinschaft für Kinder ab 5 Jahren.\u000aUm Anmeldung wird gebeten per Mail an maria.toth@stutensee.de oder telefonisch unter 07244/969-4270.\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/erzaehltheater-zu-den-internationalen-wochen-gegen-rassismus-in-spoeck/','https://stutenseekinderkalender.de','Kinder,Kirche,Kultur,Sport,Spöck',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13154,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-03-18','2026-03-18','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-03-18/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13155,'Spielzeit im GrauBau',NULL,'2026-03-18','2026-03-18','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-03-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13156,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-03-19','2026-03-19','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-03-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13157,'Korallengarde (10–14 Jahre)',NULL,'2026-03-19','2026-03-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13158,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-03-19','2026-03-19','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-03-19/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13159,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-19','2026-03-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13160,'Seesternchengarde (3–6 Jahre)',NULL,'2026-03-19','2026-03-19','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-03-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13161,'Tee- und Spielstube',NULL,'2026-03-19','2026-03-19','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-03-19/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13162,'Teen Girls im GrauBau',NULL,'2026-03-19','2026-03-19','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-03-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13163,'Eltern-Baby-Treff',NULL,'2026-03-20','2026-03-20','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-03-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13164,'Kreativfreitag im GrauBau',NULL,'2026-03-20','2026-03-20','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-03-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13165,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-03-20','2026-03-20','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-03-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13166,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-20','2026-03-20','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-03-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13167,'19. Stutenseer Stadtlauf – Aufbau',NULL,'2026-03-21',NULL,'','TSG Gelände, Blankenloch','TSG Blankenloch','Aufbau für den 19. Stutenseer Stadtlauf. Arbeitseinsatz.','https://www.tsg-blankenloch.de/Veranstaltungen/StutenseerStadtlauf/','https://www.tsg-blankenloch.de/','Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13168,'Familiendisco International',NULL,'2026-03-21','2026-03-21','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Gemeinsam tanzen, lachen und feiern! Bei der Familien-Disco sind Kinder und Eltern herzlich eingeladen, zusammen die Tanzfläche zu erobern.\u000aDas erwartet euch:\u000a\u000aInternationale Musik & Disco-Hits\u000aTanzspaß für Groß & Klein\u000aBunte Party-Atmosphäre\u000aEltern tanzen mit ihren Kindern\u000a\u000a'),'https://stutenseekinderkalender.de/event/familiendisco-international/','https://stutenseekinderkalender.de','Fest,Kinder,Kirche,Musik,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13169,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-03-21','2026-03-21','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-03-21/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13170,'19. Stutenseer Stadtlauf',NULL,'2026-03-22',NULL,'','TSG Gelände, Blankenloch','TSG Blankenloch','19. Stutenseer Stadtlauf 2026 — 10 km Volkslauf, 5 km Einsteigerlauf, 5 km Walking, Bambinilauf.','https://www.tsg-blankenloch.de/Veranstaltungen/StutenseerStadtlauf/','https://www.tsg-blankenloch.de/','Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13171,'Eltern-Baby-Café',NULL,'2026-03-23','2026-03-23','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-03-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13172,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-03-23','2026-03-23','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-03-23/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13173,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-23','2026-03-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13174,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-03-23','2026-03-23','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-03-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13175,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-24','2026-03-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13176,'Krabbelgruppe in Spöck',NULL,'2026-03-24','2026-03-24','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-03-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13177,'Oster-Werkstatt ',NULL,'2026-03-24','2026-03-24','15:30','Blankenloch-Stutensee, 76297','Melanie Nagel',unistr('*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" tabindex="-1" data-turn-id="request-68c3e531-65d0-832d-8b53-53c50aae7a7c-1" data-testid="conversation-turn-464" data-scroll-anchor="true" data-turn="assistant">\u000a\u000a\u000a\u000a\u000a\u000a\u000aOstergeschenke für Klein & Groß\u000a6 Stationen rund um das Thema Ostern und Frühling erwarten euch hier.\u000aKosten: 30€; Geschwisterkinder: 20€ (bei gleicher Begleitperson!)\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/oster-werkstatt/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13178,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-03-24','2026-03-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-03-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13179,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-03-24','2026-03-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-03-24/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13180,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-03-24','2026-03-24','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-03-24/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13182,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-03-24','2026-03-24','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-03-24/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13183,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-03-25','2026-03-25','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-03-25/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13184,'Elterncafé mit Erzähltheater „Elmar“ – Kita Zauberwald',NULL,'2026-03-25','2026-03-25','14:00','Kindergarten Zauberwald, Hauptstraße 100, Stutensee-Blankenloch','Kindergarten &#8222;Zauberwald&#8220;',unistr('Ein besonderes Elterncafé mit einem liebevoll gestalteten Erzähltheater für Kinder und Familien. Im Mittelpunkt steht die Geschichte von Elmar, dem bunt karierten Elefanten – kindgerecht erzählt mit Bildkarten und viel Raum für Austausch.\u000aDie Veranstaltung findet im Rahmen der „Wochen gegen Rassismus“ statt und setzt ein Zeichen für Toleranz und Respekt.\u000aEin wertvoller Nachmittag für Kinder und Eltern – zum Zuhören, Nachdenken und Austauschen.\u000a'),'https://stutenseekinderkalender.de/event/elterncafe-mit-erzaehltheater-elmar-kita-zauberwald/','https://stutenseekinderkalender.de','Kinder,Kultur,Natur,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13185,'Erzähltheater zu den Internationalen Wochen gegen Rassismus in Staffort',NULL,'2026-03-25','2026-03-25','15:30','Stadtbibliothek Staffort, Draisstraße 2, Stutensee-Staffort, 76297','Stadtbibliothek Staffort',unistr('\u000aIm Erzähltheater wird dieses Mal die Geschichte „Als die Raben noch bunt waren“ gezeigt. In der Geschichte geht es um wunderbar kunterbunte Raben, die sich eines Tages streiten, wer der schönste von ihnen sei. Und dann passiert etwas Unerwartetes…\u000aEine Geschichte über Toleranz, Vielfalt und Gemeinschaft für Kinder ab 5 Jahren.\u000aUm Anmeldung wird gebeten per Mail an maria.toth@stutensee.de oder telefonisch unter 07244/969-4270.\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/erzaehltheater-zu-den-internationalen-wochen-gegen-rassismus-in-staffort/','https://stutenseekinderkalender.de','Kinder,Kirche,Kultur,Sport,Staffort',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13186,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-03-25','2026-03-25','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-03-25/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13187,'Kuchenverkauf & Osterbasteleien – Kita Lachwald',NULL,'2026-03-25','2026-03-25','13:30','Städtischer Kindergarten &#8222;Lachwald&#8220;, Lindenweg 8, Stutensee-Büchig, 76298','Städtischer Kindergarten &#8222;Lachwald&#8220;',unistr('Kommt vorbei zum gemütlichen Kuchenverkauf mit Osterbasteleien!Perfekt für einen kleinen Familienausflug – und gleichzeitig unterstützt ihr einen guten Zweck.\u000aAm Mittwoch, 25.03.2026\u000aUhrzeiten:• 13:30 – 14:30 Uhr• 15:30 – 16:30 Uhr\u000aOrt:Parkplatz vor der Kita (Buchenring)\u000aDer Erlös geht zugunsten des Kindergartens Lachwald\u000aHinweis:Wenn möglich, bitte eigene Behälter für den Kuchentransport mitbringen\u000a'),'https://stutenseekinderkalender.de/event/kuchenverkauf-osterbasteleien-kita-lachwald/2026-03-25/1/','https://stutenseekinderkalender.de','Büchig,Essen,Handwerk,Kinder,Natur,Senioren,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13188,'Spielzeit im GrauBau',NULL,'2026-03-25','2026-03-25','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-03-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13189,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-03-26','2026-03-26','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-03-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13190,'Korallengarde (10–14 Jahre)',NULL,'2026-03-26','2026-03-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13191,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-03-26','2026-03-26','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-03-26/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13192,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-26','2026-03-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13193,'Seesternchengarde (3–6 Jahre)',NULL,'2026-03-26','2026-03-26','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-03-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13194,'Tee- und Spielstube',NULL,'2026-03-26','2026-03-26','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-03-26/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13195,'Teen Girls im GrauBau',NULL,'2026-03-26','2026-03-26','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-03-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13196,'Uhren-Workshop – Kreative Ostergeschenke basteln',NULL,'2026-03-26','2026-03-26','10:30','Blankenloch-Stutensee, 76297','Melanie Nagel',unistr('Beim Uhren-Workshop der WerkelZwerge gestalten Kinder ihre eigene Uhr – individuell, kreativ und einzigartig. Mit Fuß-, Finger- oder Handabdrücken entstehen ganz besondere Erinnerungsstücke. Größere Kinder können ihre Uhr selbst bemalen und gestalten. Alternativ gibt es auch Bastelpakete für zuhause.\u000aTermine:• 26. März, 10:30 Uhr• 2. April, 10:30 Uhr\u000aKosten: 15 € pro Uhr (ohne Batterie)\u000aFür: Kindergarten- und Grundschulkinder\u000aWeitere Infos & Anmeldung:\u000a\u000awww.babyzeit-kurse.de \u000a0176 9578 1759\u000amelanie.m.nagel@gmail.com\u000a\u000a '),'https://stutenseekinderkalender.de/event/uhren-workshop-kreative-ostergeschenke-basteln/2026-03-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Kultur,Natur,Workshop',13196,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13197,'Eltern-Baby-Treff',NULL,'2026-03-27','2026-03-27','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-03-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13198,'Erzähltheater zu den Internationalen Wochen gegen Rassismus in Friedrichstal',NULL,'2026-03-27','2026-03-27','15:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIm Erzähltheater wird dieses Mal die Geschichte „Als die Raben noch bunt waren“ gezeigt. In der Geschichte geht es um wunderbar kunterbunte Raben, die sich eines Tages streiten, wer der schönste von ihnen sei. Und dann passiert etwas Unerwartetes…\u000aEine Geschichte über Toleranz, Vielfalt und Gemeinschaft für Kinder ab 5 Jahren.\u000aUm Anmeldung wird gebeten per Mail an maria.toth@stutensee.de oder telefonisch unter 07244/969-4270.\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/erzaehltheater-zu-den-internationalen-wochen-gegen-rassismus-in-friedrichstal/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Kirche,Kultur,Politik,Sport,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13199,'Kreativfreitag im GrauBau',NULL,'2026-03-27','2026-03-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-03-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13200,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-03-27','2026-03-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-03-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13201,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-27','2026-03-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-03-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13202,'Stillvorbereitungsworkshop von Mamawerk',NULL,'2026-03-27','2026-03-27','16:00','Mamawerk, Kirchstraße 9, Stutensee-Spöck, 76297','Mamawerk',unistr('Ein Workshop für Schwangere (mit Partner/in), in dem ihr euch unterstützt und gut vorbereitet in die Stillzeit starten könnt. In entspannter Atmosphäre mit Snacks, Austausch und hilfreichen Tipps rund ums Stillen und die Stillbeziehung.\u000aKosten: 49 € (der Partner / die Partnerin nimmt kostenlos teil)Kontakt: 01738153171 oder E-Mail: info@mamawerk.de'),'https://stutenseekinderkalender.de/event/stillvorbereitungsworkshop-von-mamawerk/','https://stutenseekinderkalender.de','Sport,Spöck,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13203,'Osterbasteln in Spöck',NULL,'2026-03-28','2026-03-28','11:00','Alte Schule Spöck, Friedrichstraße 10, Stutensee, 76297','DLRG Ortsgruppe Spöck',unistr('Beim Osterbasteln könnt ihr gemeinsam tolle Deko und kleine Kunstwerke rund um Ostern gestalten.\u000aAnmeldung:ausbildung@spoeck.dlrg.de\u000aAnmeldeschluss: 23.03.2026\u000a'),'https://stutenseekinderkalender.de/event/osterbasteln-in-spoeck/','https://stutenseekinderkalender.de','Bildung,Handwerk,Kinder,Kultur,Spöck',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13204,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-03-28','2026-03-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-03-28/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13205,'Eltern-Baby-Café',NULL,'2026-03-30','2026-03-30','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-03-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13206,'Ferienaktion im Familienzentrum Friedrichstal',NULL,'2026-03-30',NULL,NULL,'Familienzentrum Friedrichstal','Stadtbibliothek Blankenloch','Ferienaktion im Familienzentrum Friedrichstal','https://bibliotheken.komm.one/stutensee/R%C3%BCckblicke/Veranstaltungen-2026/Ferienaktion-im-Familienzentrum-Friedrichstal-am-300326','https://bibliotheken.komm.one/stutensee','Friedrichstal,Kinder',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13207,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-03-30','2026-03-30','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-03-30/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13208,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-03-30','2026-03-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-03-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13209,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-03-30','2026-03-30','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-03-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13210,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-03-31','2026-03-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-03-31/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13211,'Krabbelgruppe in Spöck',NULL,'2026-03-31','2026-03-31','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-03-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13212,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-03-31','2026-03-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-03-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13213,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-03-31','2026-03-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-03-31/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13214,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-03-31','2026-03-31','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-03-31/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13216,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-03-31','2026-03-31','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-03-31/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13217,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-04-01','2026-04-01','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-04-01/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13218,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-04-01','2026-04-01','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-04-01/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13219,'Spielzeit im GrauBau',NULL,'2026-04-01','2026-04-01','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-04-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13220,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-04-02','2026-04-02','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-04-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13221,'Korallengarde (10–14 Jahre)',NULL,'2026-04-02','2026-04-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-04-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13222,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-04-02','2026-04-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-04-02/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13223,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-04-02','2026-04-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-04-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13224,'Seesternchengarde (3–6 Jahre)',NULL,'2026-04-02','2026-04-02','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-04-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13225,'Tee- und Spielstube',NULL,'2026-04-02','2026-04-02','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-04-02/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13226,'Teen Girls im GrauBau',NULL,'2026-04-02','2026-04-02','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-04-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13227,'Uhren-Workshop – Kreative Ostergeschenke basteln',NULL,'2026-04-02','2026-04-02','10:30','Blankenloch-Stutensee, 76297','Melanie Nagel',unistr('Beim Uhren-Workshop der WerkelZwerge gestalten Kinder ihre eigene Uhr – individuell, kreativ und einzigartig. Mit Fuß-, Finger- oder Handabdrücken entstehen ganz besondere Erinnerungsstücke. Größere Kinder können ihre Uhr selbst bemalen und gestalten. Alternativ gibt es auch Bastelpakete für zuhause.\u000aTermine:• 26. März, 10:30 Uhr• 2. April, 10:30 Uhr\u000aKosten: 15 € pro Uhr (ohne Batterie)\u000aFür: Kindergarten- und Grundschulkinder\u000aWeitere Infos & Anmeldung:\u000a\u000awww.babyzeit-kurse.de \u000a0176 9578 1759\u000amelanie.m.nagel@gmail.com\u000a\u000a '),'https://stutenseekinderkalender.de/event/uhren-workshop-kreative-ostergeschenke-basteln/2026-04-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Kultur,Natur,Workshop',13196,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13228,'Eltern-Baby-Treff',NULL,'2026-04-03','2026-04-03','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-04-03/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13229,'Kreativfreitag im GrauBau',NULL,'2026-04-03','2026-04-03','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-04-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13230,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-04-03','2026-04-03','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-04-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13231,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-04-03','2026-04-03','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-04-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13232,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-04-04','2026-04-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-04-04/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13233,'Eltern-Baby-Café',NULL,'2026-04-06','2026-04-06','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-04-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13234,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-04-06','2026-04-06','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-04-06/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13235,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-04-06','2026-04-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-04-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13236,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-04-06','2026-04-06','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-04-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13237,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-04-07','2026-04-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-04-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13238,'Krabbelgruppe in Spöck',NULL,'2026-04-07','2026-04-07','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-04-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13239,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-04-07','2026-04-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-04-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13240,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-04-07','2026-04-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-04-07/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13241,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-04-07','2026-04-07','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-04-07/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13243,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-04-07','2026-04-07','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-04-07/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13244,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-04-08','2026-04-08','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-04-08/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13245,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-04-08','2026-04-08','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-04-08/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13246,'Spielzeit im GrauBau',NULL,'2026-04-08','2026-04-08','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-04-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13247,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-04-09','2026-04-09','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-04-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13248,'Korallengarde (10–14 Jahre)',NULL,'2026-04-09','2026-04-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-04-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13249,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-04-09','2026-04-09','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-04-09/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13250,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-04-09','2026-04-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-04-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13251,'Seesternchengarde (3–6 Jahre)',NULL,'2026-04-09','2026-04-09','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-04-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13252,'Tee- und Spielstube',NULL,'2026-04-09','2026-04-09','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-04-09/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13253,'Teen Girls im GrauBau',NULL,'2026-04-09','2026-04-09','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-04-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13254,'Eltern-Baby-Treff',NULL,'2026-04-10','2026-04-10','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-04-10/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13255,'Kreativfreitag im GrauBau',NULL,'2026-04-10','2026-04-10','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-04-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13256,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-04-10','2026-04-10','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-04-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13257,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-04-10','2026-04-10','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-04-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13258,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-04-11','2026-04-11','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-04-11/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13259,'Eltern-Baby-Café',NULL,'2026-04-13','2026-04-13','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-04-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13260,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-04-13','2026-04-13','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-04-13/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13261,'Kulturentreff in Spöck',NULL,'2026-04-13','2026-04-13','16:00','Begegnungszentrum Regenbogen, Kirchstraße 22, Stutensee-Spöck, 76297','Begegnungszentrum Regenbogen',unistr('Ein offener Treffpunkt für alle – zum Ankommen, Austauschen und Kennenlernen. Hier kommen Menschen zusammen, und auch für Kinder gibt es ein kleines Programm.\u000aTermine 2026 (immer montags):13.04.202604.05.202608.06.202606.07.202614.09.202605.10.202602.11.202607.12.2026\u000aUhrzeit: jeweils 16:00 – 18:00 Uhr\u000aBesonderheit:Offen für alle – ein Ort der Begegnung, Vielfalt und Gemeinschaft'),'https://stutenseekinderkalender.de/event/kulturentreff-in-spoeck/2026-04-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Spöck,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
