INSERT INTO curated_events VALUES(13332,'Starke Eltern – Starke Kinder (Elternkurs)',NULL,'2026-04-25','2026-04-25','10:00','KarLa e. V., Hauptstraße 80, Stutensee, 76297','KarLa e. V.',unistr('Ein praxisnaher Elternkurs für Familien mit Kindern im Alter von 3-10 Jahren. Hier bekommt ihr wertvolle Impulse, stärkt eure Erziehungskompetenz und tauscht euch mit anderen Eltern aus.\u000aTermine:\u000a\u000a18.04.2026\u000a25.04.2026\u000a09.05.2026\u000a23.05.2026\u000a\u000aUhrzeit: jeweils 10:00 – 14:00 Uhr inkl. Kinderbetreuung!\u000aAnmeldung & Infos:kontakt@karla-ev.dewww.karla-ev.de\u000aKosten:Für Familien in besonderen Lebenslagen ist der Kurs kostenlos.\u000a'),'https://stutenseekinderkalender.de/event/starke-eltern-starke-kinder-elternkurs/2026-04-25/','https://stutenseekinderkalender.de','Kinder,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13333,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-04-25','2026-04-25','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-04-25/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
