INSERT INTO curated_events VALUES(13404,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-05-04','2026-05-04','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-05-04/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13405,'KulturenTreff',NULL,'2026-05-04',NULL,'16:00 - 18:00 Uhr','Begegnungszentrum Regenbogen','KulturenTreff im BZ Regenbogen',NULL,'https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2778','https://stutensee.de/Veranstaltungen','Kultur,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13406,'Kulturentreff in Spöck',NULL,'2026-05-04','2026-05-04','16:00','Begegnungszentrum Regenbogen, Kirchstraße 22, Stutensee-Spöck, 76297','Begegnungszentrum Regenbogen',unistr('Ein offener Treffpunkt für alle – zum Ankommen, Austauschen und Kennenlernen. Hier kommen Menschen zusammen, und auch für Kinder gibt es ein kleines Programm.\u000aTermine 2026 (immer montags):13.04.202604.05.202608.06.202606.07.202614.09.202605.10.202602.11.202607.12.2026\u000aUhrzeit: jeweils 16:00 – 18:00 Uhr\u000aBesonderheit:Offen für alle – ein Ort der Begegnung, Vielfalt und Gemeinschaft'),'https://stutenseekinderkalender.de/event/kulturentreff-in-spoeck/2026-05-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Spöck,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13407,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-05-04','2026-05-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-05-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13408,'Podiumsdiskussion der Bu00fcrgermeisterkandidaten',NULL,'2026-05-04',NULL,'19:30 Uhr','DRK Raum im Oskar Hornung Haus, Friedrichstal','IGV Friedrichstal','Podiumsdiskussion zur Bu00fcrgermeisterwahl mit Frank Burkard, Sven Schiebel und Tobias Walter.','https://friedrichstal.org/neues-aus-der-igv/podiumsdiskussion-der-buergermeisterkandidaten.html','https://friedrichstal.org/','Bildung,Friedrichstal,Politik',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13410,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-05-04','2026-05-04','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-05-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13411,'Steckenpferd und Drachen',NULL,'2026-05-04','2026-05-04','15:30','Blankenloch-Stutensee, 76297','Melanie Nagel',unistr('*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]" dir="auto" tabindex="-1" data-turn-id="request-68c3e531-65d0-832d-8b53-53c50aae7a7c-1" data-testid="conversation-turn-464" data-scroll-anchor="true" data-turn="assistant">\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000aKosten: 32 €; Geschwisterkinder 20€ (bei gleicher Begleitperson!)\u000a\u000a\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/steckenpferd-und-drachen/','https://stutenseekinderkalender.de','Kinder,Musik,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
