INSERT INTO curated_events VALUES(13413,'Exit Strategien - wenn alle Stricke reißen',NULL,'2026-05-05',NULL,'15:00 - 17:00 Uhr','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V. , Stadt Stutensee, Familienbildung','Workshop für Alleinerziehende','https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2777','https://stutensee.de/Veranstaltungen','Bildung,Handwerk,Kinder,Politik,Verein,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13414,'Kamishibai-Erzähltheater',NULL,'2026-05-05','2026-05-05','15:15','Stadtbibliothek Blankenloch, Gymnasiumstraße 2B, 76297 Stutensee','Stadtbibliothek Blankenloch','Im Erzähltheater geht es weiter mit „Gesucht! Henri der Bücherdieb“ von Emily MacKenzie. Die Geschichte ist für Kinder im Alter von drei bis zehn Jahren geeignet. „Henri liebt Bücher. Er muss immer mehr davon haben. Das bringt ihn leider in eine schwierige Situation. Ob Artur, der Bücher genauso sehr liebt, ihm da helfen kann?“ Der Eintritt ist frei, eine Anmeldung erforderlich und in der Regel bis zu einem Tag vor der jeweiligen Veranstaltung möglich: persönlich in der jeweiligen Stadtbibliothek / Bücherei, alternativ per Telefon 07244/969-4270 oder E-Mail an maria.toth@stutensee.de. Bitte bei Anmeldung Name, Vorname und Alter des Kindes, eine Telefonnummer und ggfs. eine Fotoerlaubnis mitteilen.','https://www.meinstutensee.de/veranstaltungen/kamishibai-erzaehltheater/','https://meinstutensee.de/termine/','Kinder,Kultur',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:14:38');
INSERT INTO curated_events VALUES(13415,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-05-05','2026-05-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-05-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13416,'Krabbelgruppe in Spöck',NULL,'2026-05-05','2026-05-05','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-05-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13417,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-05-05','2026-05-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-05-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13418,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-05-05','2026-05-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-05-05/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13419,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-05-05','2026-05-05','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-05-05/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13421,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-05-05','2026-05-05','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-05-05/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13422,'Workshop für Alleinerziehende: Exit-Strategien',NULL,'2026-05-05','2026-05-05','15:00','','Tageselternverein Bruchsal','In angespannten Situationen einen kühlen Kopf bewahren – mit welchen Methoden das geht, vermittelt ein Workshop in Stutensee für Alleinerziehende. Er wird durchgeführt von ACT-Beraterin Romina Tirolf. ACT steht für: Aktivierung, Coaching, Teilhabe. Eine Anmeldung ist erforderlich. Anmeldung unter r.tirolf@tev-bruchsal.de, Telefon 07251/981987826. Bitte Anzahl und Alter der Kinder angeben, die Sie mitbringen.','https://www.meinstutensee.de/veranstaltungen/workshop-fuer-alleinerziehende-exit-strategien/','https://meinstutensee.de/termine/','Kinder,Politik,Verein,Workshop',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(13423,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2026-05-06','2026-05-06','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2026-05-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13424,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-05-06','2026-05-06','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-05-06/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13425,'Erzähltheater "Gesucht! Henri der Bücherdieb"',NULL,'2026-05-06',NULL,'15:30 - 16:00 Uhr','Evangelische öffentliche Bücherei Friedrichstal','Stadtbibliothek','für Kinder im Alter von 3 bis 10 Jahren Anmeldung erfolderlich','https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2780','https://stutensee.de/Veranstaltungen','Friedrichstal,Kinder,Kirche,Kultur',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13426,'Kamishibai-Erzähltheater',NULL,'2026-05-06','2026-05-06','15:30','Evangelisches Gemeindehaus Friedrichstal, Hirschstraße 22, 76297 Stutensee','','Im Erzähltheater geht es weiter mit „Gesucht! Henri der Bücherdieb“ von Emily MacKenzie. Die Geschichte ist für Kinder im Alter von drei bis zehn Jahren geeignet. „Henri liebt Bücher. Er muss immer mehr davon haben. Das bringt ihn leider in eine schwierige Situation. Ob Artur, der Bücher genauso sehr liebt, ihm da helfen kann?“ Der Eintritt ist frei, eine Anmeldung erforderlich und in der Regel bis zu einem Tag vor der jeweiligen Veranstaltung möglich: persönlich in der jeweiligen Stadtbibliothek / Bücherei, alternativ per Telefon 07244/969-4270 oder E-Mail an maria.toth@stutensee.de. Bitte bei Anmeldung Name, Vorname und Alter des Kindes, eine Telefonnummer und ggfs. eine Fotoerlaubnis mitteilen.','https://www.meinstutensee.de/veranstaltungen/kamishibai-erzaehltheater-2/','https://meinstutensee.de/termine/','Friedrichstal,Kinder,Kirche,Kultur',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:14:38');
INSERT INTO curated_events VALUES(13427,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-05-06','2026-05-06','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-05-06/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13428,'Spielzeit im GrauBau',NULL,'2026-05-06','2026-05-06','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-05-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13429,'Babys in Bewegung (Block II): Herbst-und Winterkinder 2025',NULL,'2026-05-07','2026-05-07','09:15','TSG Blankenloch, Mühlenweg 4a, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('\u000aStart: 16.4.26, Donnerstags\u000a8×60 Minuten\u000aKursgebühr: 125€\u000aKursleitung: Melanie Nagel\u000aOrt: Kleiner Saal in der TSG Blankenloch\u000a\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com'),'https://stutenseekinderkalender.de/event/babys-in-bewegung-block-ii-herbst-und-winterkinder-2025/2026-05-07/','https://stutenseekinderkalender.de','Kinder,Sport,Workshop',13276,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13430,'Bewegung und Gesundheit und ihre Auswirkung auf Demenz',NULL,'2026-05-07','2026-05-07','19:00','Familienzentrum Friedrichstal &quot;Kult Café&quot;, Rheinstr. Ost 14, 76297 Stutensee','','Zur Anmeldung: https://www.vhs-karlsruhe-land.de/programm/gesundheit-ernaehrung/kw/bereich/kursdetails/kategorie-id/7/kurs/L300H003SL/kursname/Bewegung%20und%20Gesundheit%20und%20ihre%20Auswirkung%20auf%20Demenz%20Vortrag/warenkorb-hinzufuegen/L300H003SL/#inhalt','https://www.meinstutensee.de/veranstaltungen/bewegung-und-gesundheit-und-ihre-auswirkung-auf-demenz/','https://meinstutensee.de/termine/','Bildung,Friedrichstal,Kinder,Sport,Treff,Workshop',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:14:38');
INSERT INTO curated_events VALUES(13431,'Eltern-Kind-Treff „Frühe Hilfen“',NULL,'2026-05-07','2026-05-07','10:15','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Frühe Hilfen Landkreis Karlsruhe',unistr('Einmal im Monat treffen sich Mütter und Väter mit ihren Kindern im Alter von 0 – 2 Jahren unter der Leitung einer Sozialpädagogin.\u000aDie Treffen bieten Raum sich mit anderen Eltern auszutauschen und Fragen und Anliegen mit der pädagogischen Gruppenleitung zu besprechen. Sie erfahren Interessantes zu verschiedenen Themen rund um die Erziehung und Entwicklung und erhalten Spiel- und Beschäftigungsanregungen. Die Kinder haben währenddessen Zeit zum Spielen und Entdecken.\u000a\u000a12.03.2026 Von (Ab)stillen bis Zeckenschutz – Offene Fragerunde mit der Familienhebamme\u000a16.04.2026 Kommunikation mit Kindern unter 3 Jahren\u000a07.05.2026 Trageberatung\u000a11.06.2026 Umgang mit Medien Frau Bock\u000a02.07.2026 Sicher im Auto\u000a\u000aDie Teilnahme ist kostenlos.\u000aEine Anmeldung ist erwünscht.\u000aFlyer Eltern-Kind-Treff Frühe Hilfen 2026'),'https://stutenseekinderkalender.de/event/eltern-kind-treff-fruehe-hilfen/2026-05-07/','https://stutenseekinderkalender.de','Essen,Kinder,Politik,Treff,Wohltätigkeit',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13432,'Ganzheitliche Schwangerschaftsgymnastik',NULL,'2026-05-07','2026-05-07','17:00','Sporthalle, Heinrich-Heine-Straße 1, Stutensee-Spöck, 76297','vhs Karlsruhe Land',unistr('Eine Schwangerschaft ist immer etwas Einzigartiges und Besonderes. Der Körper stellt sich um, bereitet sich auf die kommenden Wochen und Monaten vor und verändert sich.\u000aUm die bevorstehenden Veränderungen für dich und dein Kind positiv zu unterstützen, zeige ich dir im Kurs angepasste Kraftübungen, die deinen Körper ganzheitlich kräftigen sowie fit halten. Zudem minimieren wir gemeinsam mit speziellen Entspannungseinheiten Beschwerden wie Rückenschmerzen, Beckenbodenschwäche oder auftretende Wachstumsschmerzen.\u000aIm Kurs kläre ich dich zudem auf, welche Veränderungen dein Körper in den kommenden Schwangerschaftswochen durchlaufen wird und wie du deinen Alltag optimal anpassen kannst.\u000aEin Austausch über deine Wunschthemen und Fragen sind herzlich willkommen!\u000aDu kannst den Kurs beim Wohlergehen bis zum Ende der Schwangerschaft besuchen.\u000aBitte mitbringen: Bequeme Kleidung, Turnschuhe, Getränk.\u000aKursgebühr: 33,00 €\u000aBei folgenden Punkten bitte erst deine(n) Frauenarzt/Frauenärztin konsultieren und die Kursteilnahme abklären lassen:\u000a– Risikoschwangerschaft\u000a– Bluthochdruck\u000a– Schwangerschaftsdiabetes\u000aGeschwisterkinder können mitgebracht werden. Es werden Spielmöglichkeiten bereitgestellt.\u000a'),'https://stutenseekinderkalender.de/event/ganzheitliche-schwangerschaftsgymnastik-2/2026-05-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Sport,Spöck,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13433,'Infoveranstaltung: Asiatische Hornisse',NULL,'2026-05-07','2026-05-07','18:00','Bürgersaal Rathaus Stutensee, Rathausstr. 3, 76297 Stutensee','Interessensgemeinschaft Asiatische Hornisse Hardt e.V.','Die Asiatische Hornisse („Vespa velutina“) breitet sich seit einigen Jahren zunehmend auch in Baden-Württemberg aus. Als etablierte invasive Art ist sie eine ernstzunehmende Gefahr für unsere heimische Biodiversität. Honigbienen und andere bestäubende Insekten sind besonders betroffen. Wie lässt sich die Vespa velutina, auch im Vergleich zur europäischen Hornisse, sicher erkennen? Was ist bei Fund eines Hornissen-Nests zu tun? Dazu informiert der Verein Asiatische Hornisse Hardt e.V. am 7. Mai, 18 Uhr, im Rathaus Stutensee.','https://www.meinstutensee.de/veranstaltungen/infoveranstaltung-zum-thema-asiatische-hornissegegenmassnahmen-und-schutzstrategien/','https://meinstutensee.de/termine/','Bildung,Essen,Natur,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:14:38');
INSERT INTO curated_events VALUES(13434,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-05-07','2026-05-07','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-05-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13435,'Korallengarde (10–14 Jahre)',NULL,'2026-05-07','2026-05-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-05-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13436,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-05-07','2026-05-07','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-05-07/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13437,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-05-07','2026-05-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-05-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13438,'Seesternchengarde (3–6 Jahre)',NULL,'2026-05-07','2026-05-07','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-05-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13439,'Tee- und Spielstube',NULL,'2026-05-07','2026-05-07','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-05-07/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
