INSERT INTO curated_events VALUES(13455,'Starke Eltern – Starke Kinder (Elternkurs)',NULL,'2026-05-09','2026-05-09','10:00','KarLa e. V., Hauptstraße 80, Stutensee, 76297','KarLa e. V.',unistr('Ein praxisnaher Elternkurs für Familien mit Kindern im Alter von 3-10 Jahren. Hier bekommt ihr wertvolle Impulse, stärkt eure Erziehungskompetenz und tauscht euch mit anderen Eltern aus.\u000aTermine:\u000a\u000a18.04.2026\u000a25.04.2026\u000a09.05.2026\u000a23.05.2026\u000a\u000aUhrzeit: jeweils 10:00 – 14:00 Uhr inkl. Kinderbetreuung!\u000aAnmeldung & Infos:kontakt@karla-ev.dewww.karla-ev.de\u000aKosten:Für Familien in besonderen Lebenslagen ist der Kurs kostenlos.\u000a'),'https://stutenseekinderkalender.de/event/starke-eltern-starke-kinder-elternkurs/2026-05-09/','https://stutenseekinderkalender.de','Kinder,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13456,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-05-09','2026-05-09','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-05-09/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13457,'Workshop "Stark sein - Grenzen setzen!"',NULL,'2026-05-09',NULL,'10:00 - 15:00 Uhr','Sporthalle am Schulzentrum Theorieraum','Stadt Stutensee, Familienbildung','Team-Workshop für Väter und Söhne im Alter von 8 bis 12 Jahren','https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2756','https://stutensee.de/Veranstaltungen','Bildung,Kinder,Sport,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13458,'Briefmarkentauschtage',NULL,'2026-05-11','2026-05-11','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Alle Kinder, Jugendlichen, Erwachsenen und Senioren, die sich für Briefmarken interessieren, mit dem Sammeln anfangen oder tauschen möchten, können gerne unverbindlich reinschauen.\u000a\u000aMontag 16 – 17 Uhr (einmal im Monat)\u000a16. März, 20. April, 11. Mai, 15. Juni, 13. Juli, 21. September, 12. Oktober, 16. November, 14. Dezember 2026\u000a\u000a '),'https://stutenseekinderkalender.de/event/briefmarkentauschtage/2026-05-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Senioren,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13459,'Eltern-Baby-Café',NULL,'2026-05-11','2026-05-11','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-05-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13460,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-05-11','2026-05-11','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-05-11/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13461,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-05-11','2026-05-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-05-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13462,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-05-11','2026-05-11','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-05-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
