INSERT INTO curated_events VALUES(13474,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2026-05-13','2026-05-13','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2026-05-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
