INSERT INTO curated_events VALUES(13476,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-05-13','2026-05-13','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-05-13/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13477,'Erzähltheater "Gesucht! Henri der Bücherdieb"',NULL,'2026-05-13',NULL,'15:15 - 15:45 Uhr','Stadtbibliothek Staffort','Stadtbibliothek','für Kinder im Alter von 3 bis 10 Jahren Anmeldung erfolderlich','https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2781','https://stutensee.de/Veranstaltungen','Kinder,Kultur,Staffort',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
