INSERT INTO curated_events VALUES(13483,'Offene Sprechstunde der Psychologischen Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe',NULL,'2026-05-13','2026-05-13','12:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Psychologische Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe',unistr('Für Eltern, Kinder und Jugendliche bietet die psychologischen Beratungsstelle des Landkreises Karlsruhe bei Fragen zu Erziehung, Entwicklung, familiären und persönlichen Problemen monatlich eine offene Sprechstunde im Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V. an – kostenfrei, vertraulich und ohne Anmeldung.\u000aMittwoch 12 – 15 Uhr (einmal im Monat): 11. März, 15. April, 13. Mai, 10. Juni, 8. Juli, 16. September, 14. Oktober, 11. November, 9. Dezember 2026\u000aFlyer Offene Sprechstunde'),'https://stutenseekinderkalender.de/event/offene-sprechstunde-der-psychologischen-beratungsstelle-fuer-eltern-kinder-und-jugendliche-des-landkreises-karlsruhe-2/2026-05-13/','https://stutensee.de/Veranstaltungen,https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein,Workshop',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:14:38');
