INSERT INTO curated_events VALUES(13485,'Spielzeit im GrauBau',NULL,'2026-05-13','2026-05-13','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-05-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
