INSERT INTO curated_events VALUES(13498,'Babys in Bewegung Juniors I',NULL,'2026-05-15','2026-05-15','09:15','TSG Blankenloch, Mühlenweg 4a, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('\u000aab 1,5 Jahre\u000aab Freitag, 8. Mai, 9:15 Uhr\u000a8x 75 Minuten\u000aKursgebühr: 130€\u000aOrt: Kleiner Saal in der TSG Blankenloch\u000a\u000aInfos & Anmeldung: 017695781759 oder melanie.m.nagel@gmail.com'),'https://stutenseekinderkalender.de/event/babys-in-bewegung-juniors-i/2026-05-15/','https://stutenseekinderkalender.de','Kinder,Sport,Workshop',13442,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
