INSERT INTO curated_events VALUES(13698,'Tag der offenen Tür – Waldorfkindergarten Stutensee',NULL,'2026-06-20','2026-06-20','14:00','Waldorfkindergarten Stutensee, Rheinstraße Ost 12, Stutensee, 76297','Waldorfkindergarten Stutensee','Der Waldorfkindergarten Stutensee lädt herzlich zum Tag der offenen Tür ein. Besucherinnen und Besucher haben die Gelegenheit, den Kindergarten kennenzulernen, Einblicke in den Alltag mit den Kindern zu gewinnen und die besondere Atmosphäre vor Ort zu erleben.','https://stutenseekinderkalender.de/event/tag-der-offenen-tuer-waldorfkindergarten-stutensee-2026/','https://stutenseekinderkalender.de','Bildung,Kinder,Natur,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(13699,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-06-20','2026-06-20','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-06-20/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
