INSERT INTO curated_events VALUES(13733,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-06-26','2026-06-26','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-06-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
