INSERT INTO curated_events VALUES(13776,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-07-04','2026-07-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-07-04/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
