INSERT INTO curated_events VALUES(14377,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-11-13','2026-11-13','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-11-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14378,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-11-13','2026-11-13','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-11-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14379,'Reparatur-Treff',NULL,'2026-11-14',NULL,'10:00 Uhr','Familienzentrum Friedrichstal - Kult Café im Alten Rathaus','Familienzentrum Friedrichstal - Kult Café',NULL,'https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2348','https://stutensee.de/Veranstaltungen','Friedrichstal,Handwerk,Kinder,Politik,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14380,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-11-14','2026-11-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-11-14/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14381,'Briefmarkentauschtage',NULL,'2026-11-16','2026-11-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Alle Kinder, Jugendlichen, Erwachsenen und Senioren, die sich für Briefmarken interessieren, mit dem Sammeln anfangen oder tauschen möchten, können gerne unverbindlich reinschauen.\u000a\u000aMontag 16 – 17 Uhr (einmal im Monat)\u000a16. März, 20. April, 11. Mai, 15. Juni, 13. Juli, 21. September, 12. Oktober, 16. November, 14. Dezember 2026\u000a\u000a '),'https://stutenseekinderkalender.de/event/briefmarkentauschtage/2026-11-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Senioren,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14382,'Eltern-Baby-Café',NULL,'2026-11-16','2026-11-16','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-11-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14383,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-11-16','2026-11-16','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-11-16/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14384,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-11-16','2026-11-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-11-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14385,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-11-16','2026-11-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-11-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14386,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-11-17','2026-11-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-11-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14387,'Krabbelgruppe in Spöck',NULL,'2026-11-17','2026-11-17','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-11-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14388,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-11-17','2026-11-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-11-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14389,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-11-17','2026-11-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-11-17/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14390,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-11-17','2026-11-17','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-11-17/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14392,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-11-17','2026-11-17','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-11-17/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14393,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2026-11-18','2026-11-18','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2026-11-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14394,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-11-18','2026-11-18','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-11-18/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14395,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-11-18','2026-11-18','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-11-18/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14396,'Spielzeit im GrauBau',NULL,'2026-11-18','2026-11-18','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-11-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14397,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-11-19','2026-11-19','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-11-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14398,'Korallengarde (10–14 Jahre)',NULL,'2026-11-19','2026-11-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-11-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14399,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-11-19','2026-11-19','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-11-19/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14400,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-11-19','2026-11-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-11-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14401,'Seesternchengarde (3–6 Jahre)',NULL,'2026-11-19','2026-11-19','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-11-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14402,'Tee- und Spielstube',NULL,'2026-11-19','2026-11-19','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-11-19/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14403,'Teen Girls im GrauBau',NULL,'2026-11-19','2026-11-19','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-11-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14404,'Eltern-Baby-Treff',NULL,'2026-11-20','2026-11-20','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-11-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14405,'Kreativfreitag im GrauBau',NULL,'2026-11-20','2026-11-20','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-11-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14406,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-11-20','2026-11-20','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-11-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14407,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-11-20','2026-11-20','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-11-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14408,'Spieleabend',NULL,'2026-11-20',NULL,'19:00 - 21:00 Uhr','Begegnungszentrum Regenbogen','KulturRaum Regenbogen im BZ Regenbogen',NULL,'https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2710','https://stutensee.de/Veranstaltungen','Kinder,Kultur,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14409,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-11-21','2026-11-21','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-11-21/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14410,'Eltern-Baby-Café',NULL,'2026-11-23','2026-11-23','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-11-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14411,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-11-23','2026-11-23','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-11-23/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14412,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-11-23','2026-11-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-11-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14413,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-11-23','2026-11-23','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-11-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14414,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-11-24','2026-11-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-11-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14415,'Krabbelgruppe in Spöck',NULL,'2026-11-24','2026-11-24','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-11-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14416,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-11-24','2026-11-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-11-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14417,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-11-24','2026-11-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-11-24/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14418,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-11-24','2026-11-24','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-11-24/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14420,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-11-24','2026-11-24','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-11-24/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14421,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2026-11-25','2026-11-25','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2026-11-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14422,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-11-25','2026-11-25','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-11-25/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14423,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-11-25','2026-11-25','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-11-25/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14424,'Spielzeit im GrauBau',NULL,'2026-11-25','2026-11-25','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-11-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14425,'Digitales Info-Café 50 +',NULL,'2026-11-26',NULL,'ab 09:00 - 12:00 Uhr ab 10:00 Uhr gemeinsames Thema','Zukunftshaus','Zukunftshaus Stutensee','Bei einer Tasse Kaffee gemeinsam digitale Stolpersteine meistern.','https://www.stutensee.de/de/Aktuelles/Veranstaltungskalender/Veranstaltung?view=publish&item=eventDate&id=2533','https://stutensee.de/Veranstaltungen','Digital,Essen,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14426,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-11-26','2026-11-26','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-11-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14427,'Korallengarde (10–14 Jahre)',NULL,'2026-11-26','2026-11-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-11-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14428,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-11-26','2026-11-26','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-11-26/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14429,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-11-26','2026-11-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-11-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14430,'Seesternchengarde (3–6 Jahre)',NULL,'2026-11-26','2026-11-26','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-11-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14431,'Tee- und Spielstube',NULL,'2026-11-26','2026-11-26','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-11-26/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14432,'Teen Girls im GrauBau',NULL,'2026-11-26','2026-11-26','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-11-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14433,'Eltern-Baby-Treff',NULL,'2026-11-27','2026-11-27','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-11-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14434,'Kreativfreitag im GrauBau',NULL,'2026-11-27','2026-11-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-11-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14435,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-11-27','2026-11-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-11-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14436,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-11-27','2026-11-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-11-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14437,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-11-28','2026-11-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-11-28/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14438,'Kindernikolausfeier',NULL,'2026-11-29',NULL,'','Festhalle Stutensee','TSG Blankenloch','Kinder-Nikolausfeier der Kinderturnabteilung mit Programm, Kaffee und Kuchen.','https://www.tsg-blankenloch.de/Veranstaltungen/VeranstaltungenUebersicht/','https://www.tsg-blankenloch.de/','Essen,Fest,Kinder,Kirche,Treff',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14439,'Eltern-Baby-Café',NULL,'2026-11-30','2026-11-30','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-11-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14440,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-11-30','2026-11-30','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-11-30/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14441,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-11-30','2026-11-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-11-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14442,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-11-30','2026-11-30','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-11-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14443,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-12-01','2026-12-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-12-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14444,'Krabbelgruppe in Spöck',NULL,'2026-12-01','2026-12-01','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-12-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14445,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-12-01','2026-12-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-12-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14446,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-12-01','2026-12-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-12-01/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14447,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-12-01','2026-12-01','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-12-01/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14449,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-12-01','2026-12-01','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-12-01/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14450,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2026-12-02','2026-12-02','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2026-12-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14451,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-12-02','2026-12-02','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-12-02/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14452,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-12-02','2026-12-02','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-12-02/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14453,'Spielzeit im GrauBau',NULL,'2026-12-02','2026-12-02','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-12-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14454,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-12-03','2026-12-03','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-12-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14455,'Korallengarde (10–14 Jahre)',NULL,'2026-12-03','2026-12-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-12-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14456,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-12-03','2026-12-03','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-12-03/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14457,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-12-03','2026-12-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-12-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14458,'Seesternchengarde (3–6 Jahre)',NULL,'2026-12-03','2026-12-03','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-12-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14459,'Tee- und Spielstube',NULL,'2026-12-03','2026-12-03','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-12-03/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14460,'Teen Girls im GrauBau',NULL,'2026-12-03','2026-12-03','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-12-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14461,'Eltern-Baby-Treff',NULL,'2026-12-04','2026-12-04','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-12-04/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14462,'Kreativfreitag im GrauBau',NULL,'2026-12-04','2026-12-04','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-12-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14463,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-12-04','2026-12-04','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-12-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14464,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-12-04','2026-12-04','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-12-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14465,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-12-05','2026-12-05','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-12-05/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14466,'Weihnachtsmarkt 2026',NULL,'2026-12-05','2026-12-06',NULL,'Friedrichstal','IGV Friedrichstal','Der diesju00e4hrige Weihnachtsmarkt wird am 5. und 6. Dezember 2026 stattfinden.','https://friedrichstal.org/neues-aus-der-igv/weihnachtsmarkt-2026.html','https://friedrichstal.org/','Fest,Friedrichstal,Markt',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14467,'Eltern-Baby-Café',NULL,'2026-12-07','2026-12-07','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-12-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14468,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-12-07','2026-12-07','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-12-07/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14469,'Kulturentreff in Spöck',NULL,'2026-12-07','2026-12-07','16:00','Begegnungszentrum Regenbogen, Kirchstraße 22, Stutensee-Spöck, 76297','Begegnungszentrum Regenbogen',unistr('Ein offener Treffpunkt für alle – zum Ankommen, Austauschen und Kennenlernen. Hier kommen Menschen zusammen, und auch für Kinder gibt es ein kleines Programm.\u000aTermine 2026 (immer montags):13.04.202604.05.202608.06.202606.07.202614.09.202605.10.202602.11.202607.12.2026\u000aUhrzeit: jeweils 16:00 – 18:00 Uhr\u000aBesonderheit:Offen für alle – ein Ort der Begegnung, Vielfalt und Gemeinschaft'),'https://stutenseekinderkalender.de/event/kulturentreff-in-spoeck/2026-12-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Spöck,Treff,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14470,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-12-07','2026-12-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-12-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14471,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-12-07','2026-12-07','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-12-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
