INSERT INTO curated_events VALUES(14533,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-12-21','2026-12-21','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-12-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14534,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-12-22','2026-12-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-12-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14535,'Krabbelgruppe in Spöck',NULL,'2026-12-22','2026-12-22','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-12-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14536,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-12-22','2026-12-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-12-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14537,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-12-22','2026-12-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-12-22/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14538,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-12-22','2026-12-22','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-12-22/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14540,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-12-22','2026-12-22','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-12-22/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14541,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2026-12-23','2026-12-23','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2026-12-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14542,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-12-23','2026-12-23','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-12-23/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14543,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-12-23','2026-12-23','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-12-23/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14544,'Spielzeit im GrauBau',NULL,'2026-12-23','2026-12-23','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-12-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14545,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-12-24','2026-12-24','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-12-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14546,'Korallengarde (10–14 Jahre)',NULL,'2026-12-24','2026-12-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-12-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14547,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-12-24','2026-12-24','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-12-24/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14548,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-12-24','2026-12-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-12-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14549,'Seesternchengarde (3–6 Jahre)',NULL,'2026-12-24','2026-12-24','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-12-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14550,'Tee- und Spielstube',NULL,'2026-12-24','2026-12-24','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-12-24/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14551,'Teen Girls im GrauBau',NULL,'2026-12-24','2026-12-24','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-12-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14552,'Eltern-Baby-Treff',NULL,'2026-12-25','2026-12-25','09:30','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('\u000aIn dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.\u000a\u000a\u000aJeden Freitag 9:30 – 11:00 Uhr\u000aFür Eltern mit Kindern von 0 bis 3 Jahren.\u000a\u000aKontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)\u000aBei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.\u000aHinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.'),'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-12-25/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Musik,Politik,Sport,Treff',12446,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14553,'Kreativfreitag im GrauBau',NULL,'2026-12-25','2026-12-25','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2026-12-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14554,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2026-12-25','2026-12-25','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2026-12-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14555,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-12-25','2026-12-25','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2026-12-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14556,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2026-12-26','2026-12-26','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-12-26/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14557,'Eltern-Baby-Café',NULL,'2026-12-28','2026-12-28','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2026-12-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14558,'Kinder- und Jugendtraining – Wilde 13',NULL,'2026-12-28','2026-12-28','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-12-28/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14559,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-12-28','2026-12-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-12-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14560,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2026-12-28','2026-12-28','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2026-12-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14561,'Seepferdchengarde (6–10 Jahre)',NULL,'2026-12-29','2026-12-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-12-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14562,'Krabbelgruppe in Spöck',NULL,'2026-12-29','2026-12-29','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-12-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14563,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2026-12-29','2026-12-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-12-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14564,'Pfadfinder*innengruppe Wölflinge',NULL,'2026-12-29','2026-12-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-12-29/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14565,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2026-12-29','2026-12-29','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-12-29/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14567,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2026-12-29','2026-12-29','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-12-29/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14568,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2026-12-30','2026-12-30','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2026-12-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14569,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2026-12-30','2026-12-30','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2026-12-30/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14570,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2026-12-30','2026-12-30','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-12-30/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14571,'Spielzeit im GrauBau',NULL,'2026-12-30','2026-12-30','15:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.\u000aJeden Mittwoch, 15:00 – 17:00 Uhr\u000aDas Programm auf www.graubau-stutensee.de/open/\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a'),'https://stutenseekinderkalender.de/event/spielzeit-im-graubau-3/2026-12-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Sport',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14572,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2026-12-31','2026-12-31','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-12-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14573,'Korallengarde (10–14 Jahre)',NULL,'2026-12-31','2026-12-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2026-12-31/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14574,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2026-12-31','2026-12-31','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2026-12-31/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14575,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2026-12-31','2026-12-31','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-12-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14576,'Seesternchengarde (3–6 Jahre)',NULL,'2026-12-31','2026-12-31','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2026-12-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14577,'Tee- und Spielstube',NULL,'2026-12-31','2026-12-31','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2026-12-31/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14578,'Teen Girls im GrauBau',NULL,'2026-12-31','2026-12-31','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2026-12-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14614,'Kreativfreitag im GrauBau',NULL,'2027-01-01','2027-01-01','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-01-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14615,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-01-01','2027-01-01','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-01-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14616,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-01','2027-01-01','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-01-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14617,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-01-02','2027-01-02','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-01-02/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14618,'Eltern-Baby-Café',NULL,'2027-01-04','2027-01-04','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-01-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14619,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-01-04','2027-01-04','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-01-04/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14620,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-04','2027-01-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14621,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-01-04','2027-01-04','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-01-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14622,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-05','2027-01-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14623,'Krabbelgruppe in Spöck',NULL,'2027-01-05','2027-01-05','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-01-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14624,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-01-05','2027-01-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-01-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14625,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-01-05','2027-01-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-01-05/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14626,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-01-05','2027-01-05','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-01-05/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14628,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-01-05','2027-01-05','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-01-05/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14629,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-01-06','2027-01-06','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-01-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14630,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-01-06','2027-01-06','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-01-06/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14631,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-01-06','2027-01-06','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-01-06/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14632,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-01-07','2027-01-07','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-01-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14633,'Korallengarde (10–14 Jahre)',NULL,'2027-01-07','2027-01-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14634,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-01-07','2027-01-07','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-01-07/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14635,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-07','2027-01-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14636,'Seesternchengarde (3–6 Jahre)',NULL,'2027-01-07','2027-01-07','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-01-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14637,'Tee- und Spielstube',NULL,'2027-01-07','2027-01-07','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-01-07/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14638,'Teen Girls im GrauBau',NULL,'2027-01-07','2027-01-07','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-01-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14639,'Kreativfreitag im GrauBau',NULL,'2027-01-08','2027-01-08','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-01-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14640,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-01-08','2027-01-08','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-01-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14641,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-08','2027-01-08','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-01-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14642,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-01-09','2027-01-09','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-01-09/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14643,'Eltern-Baby-Café',NULL,'2027-01-11','2027-01-11','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-01-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14644,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-01-11','2027-01-11','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-01-11/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14645,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-11','2027-01-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14646,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-01-11','2027-01-11','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-01-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14647,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-12','2027-01-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14648,'Krabbelgruppe in Spöck',NULL,'2027-01-12','2027-01-12','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-01-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14649,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-01-12','2027-01-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-01-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14650,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-01-12','2027-01-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-01-12/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14651,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-01-12','2027-01-12','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-01-12/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14653,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-01-12','2027-01-12','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-01-12/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14654,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-01-13','2027-01-13','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-01-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14655,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-01-13','2027-01-13','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-01-13/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14656,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-01-13','2027-01-13','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-01-13/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14657,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-01-14','2027-01-14','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-01-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14658,'Korallengarde (10–14 Jahre)',NULL,'2027-01-14','2027-01-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14659,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-01-14','2027-01-14','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-01-14/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14660,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-14','2027-01-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14661,'Seesternchengarde (3–6 Jahre)',NULL,'2027-01-14','2027-01-14','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-01-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14662,'Tee- und Spielstube',NULL,'2027-01-14','2027-01-14','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-01-14/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14663,'Teen Girls im GrauBau',NULL,'2027-01-14','2027-01-14','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-01-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14664,'Kreativfreitag im GrauBau',NULL,'2027-01-15','2027-01-15','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-01-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14665,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-01-15','2027-01-15','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-01-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14666,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-15','2027-01-15','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-01-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14667,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-01-16','2027-01-16','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-01-16/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14668,'Eltern-Baby-Café',NULL,'2027-01-18','2027-01-18','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-01-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14669,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-01-18','2027-01-18','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-01-18/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14670,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-18','2027-01-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14671,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-01-18','2027-01-18','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-01-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14672,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-19','2027-01-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14673,'Krabbelgruppe in Spöck',NULL,'2027-01-19','2027-01-19','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-01-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14674,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-01-19','2027-01-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-01-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14675,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-01-19','2027-01-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-01-19/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14676,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-01-19','2027-01-19','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-01-19/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14678,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-01-19','2027-01-19','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-01-19/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14679,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-01-20','2027-01-20','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-01-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14680,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-01-20','2027-01-20','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-01-20/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14681,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-01-20','2027-01-20','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-01-20/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14682,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-01-21','2027-01-21','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-01-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14683,'Korallengarde (10–14 Jahre)',NULL,'2027-01-21','2027-01-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14684,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-01-21','2027-01-21','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-01-21/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14685,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-21','2027-01-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14686,'Seesternchengarde (3–6 Jahre)',NULL,'2027-01-21','2027-01-21','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-01-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14687,'Tee- und Spielstube',NULL,'2027-01-21','2027-01-21','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-01-21/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14688,'Teen Girls im GrauBau',NULL,'2027-01-21','2027-01-21','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-01-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14689,'Kreativfreitag im GrauBau',NULL,'2027-01-22','2027-01-22','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-01-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14690,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-01-22','2027-01-22','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-01-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14691,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-22','2027-01-22','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-01-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14692,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-01-23','2027-01-23','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-01-23/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14693,'Eltern-Baby-Café',NULL,'2027-01-25','2027-01-25','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-01-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14694,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-01-25','2027-01-25','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-01-25/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14695,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-25','2027-01-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14696,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-01-25','2027-01-25','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-01-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14697,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-26','2027-01-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14698,'Krabbelgruppe in Spöck',NULL,'2027-01-26','2027-01-26','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-01-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14699,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-01-26','2027-01-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-01-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14700,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-01-26','2027-01-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-01-26/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14701,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-01-26','2027-01-26','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-01-26/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14703,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-01-26','2027-01-26','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-01-26/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14704,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-01-27','2027-01-27','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-01-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14705,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-01-27','2027-01-27','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-01-27/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14706,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-01-27','2027-01-27','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-01-27/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14707,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-01-28','2027-01-28','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-01-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14708,'Korallengarde (10–14 Jahre)',NULL,'2027-01-28','2027-01-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-01-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14709,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-01-28','2027-01-28','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-01-28/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14710,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-01-28','2027-01-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-01-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14711,'Seesternchengarde (3–6 Jahre)',NULL,'2027-01-28','2027-01-28','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-01-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14712,'Tee- und Spielstube',NULL,'2027-01-28','2027-01-28','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-01-28/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14713,'Teen Girls im GrauBau',NULL,'2027-01-28','2027-01-28','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-01-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14714,'Kreativfreitag im GrauBau',NULL,'2027-01-29','2027-01-29','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-01-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14715,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-01-29','2027-01-29','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-01-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14716,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-01-29','2027-01-29','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-01-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14717,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-01-30','2027-01-30','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-01-30/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14718,'Eltern-Baby-Café',NULL,'2027-02-01','2027-02-01','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-02-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14719,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-02-01','2027-02-01','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-02-01/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14720,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-01','2027-02-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14721,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-02-01','2027-02-01','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-02-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14722,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-02','2027-02-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14723,'Krabbelgruppe in Spöck',NULL,'2027-02-02','2027-02-02','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-02-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14724,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-02-02','2027-02-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-02-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14725,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-02-02','2027-02-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-02-02/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14726,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-02-02','2027-02-02','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-02-02/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14728,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-02-02','2027-02-02','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-02-02/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14729,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-02-03','2027-02-03','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-02-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14730,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-02-03','2027-02-03','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-02-03/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14731,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-02-03','2027-02-03','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-02-03/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14732,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-02-04','2027-02-04','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-02-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14733,'Korallengarde (10–14 Jahre)',NULL,'2027-02-04','2027-02-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14734,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-02-04','2027-02-04','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-02-04/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14735,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-04','2027-02-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14736,'Seesternchengarde (3–6 Jahre)',NULL,'2027-02-04','2027-02-04','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-02-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14737,'Tee- und Spielstube',NULL,'2027-02-04','2027-02-04','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-02-04/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14738,'Teen Girls im GrauBau',NULL,'2027-02-04','2027-02-04','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-02-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14739,'Kreativfreitag im GrauBau',NULL,'2027-02-05','2027-02-05','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-02-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14740,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-02-05','2027-02-05','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-02-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14741,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-05','2027-02-05','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-02-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14742,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-02-06','2027-02-06','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-02-06/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14743,'Eltern-Baby-Café',NULL,'2027-02-08','2027-02-08','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-02-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14744,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-02-08','2027-02-08','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-02-08/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14745,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-08','2027-02-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14746,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-02-08','2027-02-08','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-02-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14747,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-09','2027-02-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14748,'Krabbelgruppe in Spöck',NULL,'2027-02-09','2027-02-09','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-02-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14749,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-02-09','2027-02-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-02-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14750,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-02-09','2027-02-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-02-09/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14751,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-02-09','2027-02-09','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-02-09/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14753,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-02-09','2027-02-09','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-02-09/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14754,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-02-10','2027-02-10','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-02-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14755,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-02-10','2027-02-10','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-02-10/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14756,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-02-10','2027-02-10','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-02-10/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14757,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-02-11','2027-02-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-02-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14758,'Korallengarde (10–14 Jahre)',NULL,'2027-02-11','2027-02-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14759,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-02-11','2027-02-11','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-02-11/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14760,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-11','2027-02-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14761,'Seesternchengarde (3–6 Jahre)',NULL,'2027-02-11','2027-02-11','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-02-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14762,'Tee- und Spielstube',NULL,'2027-02-11','2027-02-11','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-02-11/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14763,'Teen Girls im GrauBau',NULL,'2027-02-11','2027-02-11','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-02-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14764,'Kreativfreitag im GrauBau',NULL,'2027-02-12','2027-02-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-02-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14765,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-02-12','2027-02-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-02-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14766,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-12','2027-02-12','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-02-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14767,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-02-13','2027-02-13','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-02-13/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14768,'Eltern-Baby-Café',NULL,'2027-02-15','2027-02-15','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-02-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14769,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-02-15','2027-02-15','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-02-15/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14770,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-15','2027-02-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14771,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-02-15','2027-02-15','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-02-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14772,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-16','2027-02-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14773,'Krabbelgruppe in Spöck',NULL,'2027-02-16','2027-02-16','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-02-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14774,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-02-16','2027-02-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-02-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14775,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-02-16','2027-02-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-02-16/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14776,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-02-16','2027-02-16','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-02-16/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14778,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-02-16','2027-02-16','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-02-16/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14779,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-02-17','2027-02-17','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-02-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14780,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-02-17','2027-02-17','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-02-17/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14781,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-02-17','2027-02-17','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-02-17/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14782,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-02-18','2027-02-18','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-02-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14783,'Korallengarde (10–14 Jahre)',NULL,'2027-02-18','2027-02-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14784,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-02-18','2027-02-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-02-18/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14785,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-18','2027-02-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14786,'Seesternchengarde (3–6 Jahre)',NULL,'2027-02-18','2027-02-18','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-02-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14787,'Tee- und Spielstube',NULL,'2027-02-18','2027-02-18','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-02-18/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14788,'Teen Girls im GrauBau',NULL,'2027-02-18','2027-02-18','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-02-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14789,'Kreativfreitag im GrauBau',NULL,'2027-02-19','2027-02-19','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-02-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14790,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-02-19','2027-02-19','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-02-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14791,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-19','2027-02-19','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-02-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14792,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-02-20','2027-02-20','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-02-20/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14793,'Eltern-Baby-Café',NULL,'2027-02-22','2027-02-22','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-02-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14794,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-02-22','2027-02-22','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-02-22/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14795,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-22','2027-02-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14796,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-02-22','2027-02-22','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-02-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14797,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-23','2027-02-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14798,'Krabbelgruppe in Spöck',NULL,'2027-02-23','2027-02-23','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-02-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14799,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-02-23','2027-02-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-02-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14800,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-02-23','2027-02-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-02-23/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14801,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-02-23','2027-02-23','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-02-23/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14803,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-02-23','2027-02-23','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-02-23/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14804,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-02-24','2027-02-24','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-02-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14805,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-02-24','2027-02-24','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-02-24/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14806,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-02-24','2027-02-24','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-02-24/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14807,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-02-25','2027-02-25','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-02-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14808,'Korallengarde (10–14 Jahre)',NULL,'2027-02-25','2027-02-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-02-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14809,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-02-25','2027-02-25','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-02-25/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14810,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-02-25','2027-02-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-02-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14811,'Seesternchengarde (3–6 Jahre)',NULL,'2027-02-25','2027-02-25','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-02-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14812,'Tee- und Spielstube',NULL,'2027-02-25','2027-02-25','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-02-25/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14813,'Teen Girls im GrauBau',NULL,'2027-02-25','2027-02-25','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-02-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14814,'Kreativfreitag im GrauBau',NULL,'2027-02-26','2027-02-26','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-02-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14815,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-02-26','2027-02-26','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-02-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14816,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-02-26','2027-02-26','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-02-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14817,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-02-27','2027-02-27','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-02-27/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14818,'Eltern-Baby-Café',NULL,'2027-03-01','2027-03-01','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-03-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14819,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-03-01','2027-03-01','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-03-01/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14820,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-01','2027-03-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14821,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-03-01','2027-03-01','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-03-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14822,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-02','2027-03-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14823,'Krabbelgruppe in Spöck',NULL,'2027-03-02','2027-03-02','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-03-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14824,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-03-02','2027-03-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-03-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14825,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-03-02','2027-03-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-03-02/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14826,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-03-02','2027-03-02','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-03-02/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14828,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-03-02','2027-03-02','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-03-02/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14829,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-03-03','2027-03-03','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-03-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14830,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-03-03','2027-03-03','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-03-03/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14831,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-03-03','2027-03-03','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-03-03/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14832,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-03-04','2027-03-04','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-03-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14833,'Korallengarde (10–14 Jahre)',NULL,'2027-03-04','2027-03-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14834,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-03-04','2027-03-04','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-03-04/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14835,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-04','2027-03-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14836,'Seesternchengarde (3–6 Jahre)',NULL,'2027-03-04','2027-03-04','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-03-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14837,'Tee- und Spielstube',NULL,'2027-03-04','2027-03-04','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-03-04/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14838,'Teen Girls im GrauBau',NULL,'2027-03-04','2027-03-04','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-03-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14839,'Kreativfreitag im GrauBau',NULL,'2027-03-05','2027-03-05','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-03-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14840,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-03-05','2027-03-05','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-03-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14841,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-05','2027-03-05','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-03-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14842,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-03-06','2027-03-06','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-03-06/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14843,'Eltern-Baby-Café',NULL,'2027-03-08','2027-03-08','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-03-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14844,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-03-08','2027-03-08','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-03-08/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14845,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-08','2027-03-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14846,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-03-08','2027-03-08','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-03-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14847,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-09','2027-03-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14848,'Krabbelgruppe in Spöck',NULL,'2027-03-09','2027-03-09','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-03-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14849,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-03-09','2027-03-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-03-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14850,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-03-09','2027-03-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-03-09/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14851,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-03-09','2027-03-09','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-03-09/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14853,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-03-09','2027-03-09','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-03-09/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14854,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-03-10','2027-03-10','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-03-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14855,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-03-10','2027-03-10','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-03-10/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14856,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-03-10','2027-03-10','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-03-10/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14857,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-03-11','2027-03-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-03-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14858,'Korallengarde (10–14 Jahre)',NULL,'2027-03-11','2027-03-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14859,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-03-11','2027-03-11','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-03-11/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14860,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-11','2027-03-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14861,'Seesternchengarde (3–6 Jahre)',NULL,'2027-03-11','2027-03-11','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-03-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14862,'Tee- und Spielstube',NULL,'2027-03-11','2027-03-11','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-03-11/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14863,'Teen Girls im GrauBau',NULL,'2027-03-11','2027-03-11','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-03-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14864,'Kreativfreitag im GrauBau',NULL,'2027-03-12','2027-03-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-03-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14865,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-03-12','2027-03-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-03-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14866,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-12','2027-03-12','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-03-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14867,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-03-13','2027-03-13','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-03-13/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14868,'Eltern-Baby-Café',NULL,'2027-03-15','2027-03-15','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-03-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14869,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-03-15','2027-03-15','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-03-15/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14870,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-15','2027-03-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14871,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-03-15','2027-03-15','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-03-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14872,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-16','2027-03-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14873,'Krabbelgruppe in Spöck',NULL,'2027-03-16','2027-03-16','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-03-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14874,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-03-16','2027-03-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-03-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14875,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-03-16','2027-03-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-03-16/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14876,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-03-16','2027-03-16','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-03-16/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14878,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-03-16','2027-03-16','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-03-16/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14879,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-03-17','2027-03-17','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-03-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14880,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-03-17','2027-03-17','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-03-17/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14881,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-03-17','2027-03-17','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-03-17/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14882,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-03-18','2027-03-18','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-03-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14883,'Korallengarde (10–14 Jahre)',NULL,'2027-03-18','2027-03-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14884,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-03-18','2027-03-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-03-18/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14885,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-18','2027-03-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14886,'Seesternchengarde (3–6 Jahre)',NULL,'2027-03-18','2027-03-18','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-03-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14887,'Tee- und Spielstube',NULL,'2027-03-18','2027-03-18','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-03-18/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14888,'Teen Girls im GrauBau',NULL,'2027-03-18','2027-03-18','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-03-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14889,'Kreativfreitag im GrauBau',NULL,'2027-03-19','2027-03-19','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-03-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14890,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-03-19','2027-03-19','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-03-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14891,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-19','2027-03-19','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-03-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14892,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-03-20','2027-03-20','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-03-20/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14893,'Eltern-Baby-Café',NULL,'2027-03-22','2027-03-22','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-03-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14894,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-03-22','2027-03-22','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-03-22/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14895,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-22','2027-03-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14896,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-03-22','2027-03-22','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-03-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14897,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-23','2027-03-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14898,'Krabbelgruppe in Spöck',NULL,'2027-03-23','2027-03-23','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-03-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14899,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-03-23','2027-03-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-03-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14900,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-03-23','2027-03-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-03-23/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14901,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-03-23','2027-03-23','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-03-23/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14903,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-03-23','2027-03-23','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-03-23/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14904,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-03-24','2027-03-24','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-03-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14905,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-03-24','2027-03-24','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-03-24/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14906,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-03-24','2027-03-24','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-03-24/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14907,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-03-25','2027-03-25','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-03-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14908,'Korallengarde (10–14 Jahre)',NULL,'2027-03-25','2027-03-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14909,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-03-25','2027-03-25','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-03-25/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14910,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-25','2027-03-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14911,'Seesternchengarde (3–6 Jahre)',NULL,'2027-03-25','2027-03-25','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-03-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14912,'Tee- und Spielstube',NULL,'2027-03-25','2027-03-25','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-03-25/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14913,'Teen Girls im GrauBau',NULL,'2027-03-25','2027-03-25','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-03-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14914,'Kreativfreitag im GrauBau',NULL,'2027-03-26','2027-03-26','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-03-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14915,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-03-26','2027-03-26','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-03-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14916,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-26','2027-03-26','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-03-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14917,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-03-27','2027-03-27','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-03-27/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14918,'Eltern-Baby-Café',NULL,'2027-03-29','2027-03-29','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-03-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14919,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-03-29','2027-03-29','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-03-29/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14920,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-03-29','2027-03-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-03-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14921,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-03-29','2027-03-29','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-03-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14922,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-03-30','2027-03-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-03-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14923,'Krabbelgruppe in Spöck',NULL,'2027-03-30','2027-03-30','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-03-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14924,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-03-30','2027-03-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-03-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14925,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-03-30','2027-03-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-03-30/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14926,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-03-30','2027-03-30','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-03-30/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14928,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-03-30','2027-03-30','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-03-30/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14929,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-03-31','2027-03-31','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-03-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14930,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-03-31','2027-03-31','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-03-31/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14931,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-03-31','2027-03-31','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-03-31/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14932,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-04-01','2027-04-01','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-04-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14933,'Korallengarde (10–14 Jahre)',NULL,'2027-04-01','2027-04-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14934,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-04-01','2027-04-01','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-04-01/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14935,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-01','2027-04-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14936,'Seesternchengarde (3–6 Jahre)',NULL,'2027-04-01','2027-04-01','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-04-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14937,'Tee- und Spielstube',NULL,'2027-04-01','2027-04-01','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-04-01/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14938,'Teen Girls im GrauBau',NULL,'2027-04-01','2027-04-01','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-04-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14939,'Kreativfreitag im GrauBau',NULL,'2027-04-02','2027-04-02','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-04-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14940,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-04-02','2027-04-02','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-04-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14941,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-02','2027-04-02','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-04-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14942,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-04-03','2027-04-03','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-04-03/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14943,'Eltern-Baby-Café',NULL,'2027-04-05','2027-04-05','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-04-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14944,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-04-05','2027-04-05','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-04-05/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14945,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-05','2027-04-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14946,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-04-05','2027-04-05','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-04-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14947,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-06','2027-04-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14948,'Krabbelgruppe in Spöck',NULL,'2027-04-06','2027-04-06','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-04-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14949,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-04-06','2027-04-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-04-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14950,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-04-06','2027-04-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-04-06/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14951,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-04-06','2027-04-06','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-04-06/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14953,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-04-06','2027-04-06','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-04-06/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14954,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-04-07','2027-04-07','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-04-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14955,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-04-07','2027-04-07','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-04-07/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14956,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-04-07','2027-04-07','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-04-07/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14957,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-04-08','2027-04-08','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-04-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14958,'Korallengarde (10–14 Jahre)',NULL,'2027-04-08','2027-04-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14959,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-04-08','2027-04-08','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-04-08/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14960,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-08','2027-04-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14961,'Seesternchengarde (3–6 Jahre)',NULL,'2027-04-08','2027-04-08','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-04-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14962,'Tee- und Spielstube',NULL,'2027-04-08','2027-04-08','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-04-08/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14963,'Teen Girls im GrauBau',NULL,'2027-04-08','2027-04-08','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-04-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14964,'Kreativfreitag im GrauBau',NULL,'2027-04-09','2027-04-09','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-04-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14965,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-04-09','2027-04-09','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-04-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14966,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-09','2027-04-09','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-04-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14967,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-04-10','2027-04-10','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-04-10/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14968,'Eltern-Baby-Café',NULL,'2027-04-12','2027-04-12','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-04-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14969,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-04-12','2027-04-12','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-04-12/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14970,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-12','2027-04-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14971,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-04-12','2027-04-12','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-04-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14972,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-13','2027-04-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14973,'Krabbelgruppe in Spöck',NULL,'2027-04-13','2027-04-13','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-04-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14974,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-04-13','2027-04-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-04-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14975,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-04-13','2027-04-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-04-13/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14976,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-04-13','2027-04-13','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-04-13/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14978,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-04-13','2027-04-13','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-04-13/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14979,'Abenteuer-Zwerge (4-6 Jahre)',NULL,'2027-04-14','2027-04-14','16:15','Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297','Melanie Nagel',unistr('Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.\u000a\u000aStart: 15.04.2026\u000aTermin: mittwochs\u000aUhrzeit: 16:15 – 17:15 Uhr\u000aTreffpunkt: Gymnasiumstraße 16, Blankenloch\u000aAlter: 4-6 Jahre\u000a\u000aInhalte:\u000a\u000aSpielen & Basteln\u000aBewegung & Sport\u000aSingen & Kreativität\u000aNeues entdecken & erforschen\u000a\u000aInfos & Anmeldung:Melanie Nagelmelanie.m.nagel@gmail.com\u000a'),'https://stutenseekinderkalender.de/event/abenteuer-zwerge-4-6-jahre/2027-04-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Sport,Treff,Workshop',13271,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14980,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-04-14','2027-04-14','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-04-14/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14981,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-04-14','2027-04-14','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-04-14/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14982,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-04-15','2027-04-15','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-04-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14983,'Korallengarde (10–14 Jahre)',NULL,'2027-04-15','2027-04-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14984,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-04-15','2027-04-15','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-04-15/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14985,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-15','2027-04-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14986,'Seesternchengarde (3–6 Jahre)',NULL,'2027-04-15','2027-04-15','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-04-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14987,'Tee- und Spielstube',NULL,'2027-04-15','2027-04-15','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-04-15/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14988,'Teen Girls im GrauBau',NULL,'2027-04-15','2027-04-15','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-04-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14989,'Kreativfreitag im GrauBau',NULL,'2027-04-16','2027-04-16','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-04-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14990,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-04-16','2027-04-16','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-04-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14991,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-16','2027-04-16','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-04-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14992,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-04-17','2027-04-17','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-04-17/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14993,'Eltern-Baby-Café',NULL,'2027-04-19','2027-04-19','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-04-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14994,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-04-19','2027-04-19','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-04-19/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14995,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-19','2027-04-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14996,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-04-19','2027-04-19','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-04-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14997,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-20','2027-04-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(14998,'Krabbelgruppe in Spöck',NULL,'2027-04-20','2027-04-20','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-04-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(14999,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-04-20','2027-04-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-04-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15000,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-04-20','2027-04-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-04-20/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15001,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-04-20','2027-04-20','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-04-20/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15003,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-04-20','2027-04-20','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-04-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15004,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-04-21','2027-04-21','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-04-21/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15005,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-04-21','2027-04-21','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-04-21/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15006,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-04-22','2027-04-22','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-04-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15007,'Korallengarde (10–14 Jahre)',NULL,'2027-04-22','2027-04-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15008,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-04-22','2027-04-22','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-04-22/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15009,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-22','2027-04-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15010,'Seesternchengarde (3–6 Jahre)',NULL,'2027-04-22','2027-04-22','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-04-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15011,'Tee- und Spielstube',NULL,'2027-04-22','2027-04-22','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-04-22/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15012,'Teen Girls im GrauBau',NULL,'2027-04-22','2027-04-22','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-04-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15013,'Kreativfreitag im GrauBau',NULL,'2027-04-23','2027-04-23','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-04-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15014,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-04-23','2027-04-23','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-04-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15015,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-23','2027-04-23','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-04-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15016,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-04-24','2027-04-24','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-04-24/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15017,'Eltern-Baby-Café',NULL,'2027-04-26','2027-04-26','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-04-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15018,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-04-26','2027-04-26','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-04-26/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15019,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-26','2027-04-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15020,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-04-26','2027-04-26','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-04-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15021,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-27','2027-04-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15022,'Krabbelgruppe in Spöck',NULL,'2027-04-27','2027-04-27','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-04-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15023,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-04-27','2027-04-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-04-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15024,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-04-27','2027-04-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-04-27/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15025,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-04-27','2027-04-27','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-04-27/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15027,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-04-27','2027-04-27','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-04-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15028,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-04-28','2027-04-28','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-04-28/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15029,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-04-28','2027-04-28','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-04-28/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15030,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-04-29','2027-04-29','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-04-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15031,'Korallengarde (10–14 Jahre)',NULL,'2027-04-29','2027-04-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-04-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15032,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-04-29','2027-04-29','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-04-29/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15033,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-04-29','2027-04-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-04-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15034,'Seesternchengarde (3–6 Jahre)',NULL,'2027-04-29','2027-04-29','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-04-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15035,'Tee- und Spielstube',NULL,'2027-04-29','2027-04-29','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-04-29/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15036,'Teen Girls im GrauBau',NULL,'2027-04-29','2027-04-29','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-04-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15037,'Kreativfreitag im GrauBau',NULL,'2027-04-30','2027-04-30','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-04-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15038,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-04-30','2027-04-30','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-04-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15039,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-04-30','2027-04-30','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-04-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15040,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-05-01','2027-05-01','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-05-01/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15041,'Eltern-Baby-Café',NULL,'2027-05-03','2027-05-03','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-05-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15042,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-05-03','2027-05-03','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-05-03/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15043,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-03','2027-05-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15044,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-05-03','2027-05-03','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-05-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15045,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-04','2027-05-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15046,'Krabbelgruppe in Spöck',NULL,'2027-05-04','2027-05-04','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-05-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15047,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-05-04','2027-05-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-05-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15048,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-05-04','2027-05-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-05-04/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15049,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-05-04','2027-05-04','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-05-04/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15051,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-05-04','2027-05-04','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-05-04/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15052,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-05-05','2027-05-05','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-05-05/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15053,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-05-05','2027-05-05','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-05-05/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15054,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-05-06','2027-05-06','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-05-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15055,'Korallengarde (10–14 Jahre)',NULL,'2027-05-06','2027-05-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15056,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-05-06','2027-05-06','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-05-06/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15057,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-06','2027-05-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15058,'Seesternchengarde (3–6 Jahre)',NULL,'2027-05-06','2027-05-06','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-05-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15059,'Tee- und Spielstube',NULL,'2027-05-06','2027-05-06','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-05-06/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15060,'Teen Girls im GrauBau',NULL,'2027-05-06','2027-05-06','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-05-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15061,'Kreativfreitag im GrauBau',NULL,'2027-05-07','2027-05-07','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-05-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15062,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-05-07','2027-05-07','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-05-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15063,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-07','2027-05-07','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-05-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15064,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-05-08','2027-05-08','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-05-08/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15065,'Eltern-Baby-Café',NULL,'2027-05-10','2027-05-10','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-05-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15066,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-05-10','2027-05-10','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-05-10/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15067,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-10','2027-05-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15068,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-05-10','2027-05-10','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-05-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15069,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-11','2027-05-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15070,'Krabbelgruppe in Spöck',NULL,'2027-05-11','2027-05-11','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-05-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15071,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-05-11','2027-05-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-05-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15072,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-05-11','2027-05-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-05-11/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15073,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-05-11','2027-05-11','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-05-11/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15075,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-05-11','2027-05-11','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-05-11/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15076,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-05-12','2027-05-12','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-05-12/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15077,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-05-12','2027-05-12','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-05-12/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15078,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-05-13','2027-05-13','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-05-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15079,'Korallengarde (10–14 Jahre)',NULL,'2027-05-13','2027-05-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15080,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-05-13','2027-05-13','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-05-13/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15081,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-13','2027-05-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15082,'Seesternchengarde (3–6 Jahre)',NULL,'2027-05-13','2027-05-13','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-05-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15083,'Tee- und Spielstube',NULL,'2027-05-13','2027-05-13','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-05-13/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15084,'Teen Girls im GrauBau',NULL,'2027-05-13','2027-05-13','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-05-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15085,'Kreativfreitag im GrauBau',NULL,'2027-05-14','2027-05-14','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-05-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15086,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-05-14','2027-05-14','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-05-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15087,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-14','2027-05-14','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-05-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15088,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-05-15','2027-05-15','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-05-15/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15089,'Eltern-Baby-Café',NULL,'2027-05-17','2027-05-17','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-05-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15090,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-05-17','2027-05-17','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-05-17/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15091,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-17','2027-05-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15092,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-05-17','2027-05-17','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-05-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15093,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-18','2027-05-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15094,'Krabbelgruppe in Spöck',NULL,'2027-05-18','2027-05-18','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-05-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15095,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-05-18','2027-05-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-05-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15096,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-05-18','2027-05-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-05-18/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15097,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-05-18','2027-05-18','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-05-18/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15099,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-05-18','2027-05-18','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-05-18/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15100,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-05-19','2027-05-19','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-05-19/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15101,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-05-19','2027-05-19','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-05-19/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15102,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-05-20','2027-05-20','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-05-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15103,'Korallengarde (10–14 Jahre)',NULL,'2027-05-20','2027-05-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15104,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-05-20','2027-05-20','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-05-20/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15105,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-20','2027-05-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15106,'Seesternchengarde (3–6 Jahre)',NULL,'2027-05-20','2027-05-20','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-05-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15107,'Tee- und Spielstube',NULL,'2027-05-20','2027-05-20','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-05-20/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15108,'Teen Girls im GrauBau',NULL,'2027-05-20','2027-05-20','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-05-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15109,'Kreativfreitag im GrauBau',NULL,'2027-05-21','2027-05-21','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-05-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15110,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-05-21','2027-05-21','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-05-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15111,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-21','2027-05-21','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-05-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15112,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-05-22','2027-05-22','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-05-22/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15113,'Eltern-Baby-Café',NULL,'2027-05-24','2027-05-24','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-05-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15114,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-05-24','2027-05-24','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-05-24/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15115,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-24','2027-05-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15116,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-05-24','2027-05-24','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-05-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15117,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-25','2027-05-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15118,'Krabbelgruppe in Spöck',NULL,'2027-05-25','2027-05-25','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-05-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15119,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-05-25','2027-05-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-05-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15120,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-05-25','2027-05-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-05-25/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15121,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-05-25','2027-05-25','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-05-25/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15123,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-05-25','2027-05-25','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-05-25/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15124,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-05-26','2027-05-26','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-05-26/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15125,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-05-26','2027-05-26','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-05-26/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15126,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-05-27','2027-05-27','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-05-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15127,'Korallengarde (10–14 Jahre)',NULL,'2027-05-27','2027-05-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-05-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15128,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-05-27','2027-05-27','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-05-27/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15129,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-27','2027-05-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15130,'Seesternchengarde (3–6 Jahre)',NULL,'2027-05-27','2027-05-27','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-05-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15131,'Tee- und Spielstube',NULL,'2027-05-27','2027-05-27','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-05-27/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15132,'Teen Girls im GrauBau',NULL,'2027-05-27','2027-05-27','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-05-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15133,'Kreativfreitag im GrauBau',NULL,'2027-05-28','2027-05-28','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-05-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15134,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-05-28','2027-05-28','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-05-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15135,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-05-28','2027-05-28','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-05-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15136,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-05-29','2027-05-29','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-05-29/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15137,'Eltern-Baby-Café',NULL,'2027-05-31','2027-05-31','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-05-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15138,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-05-31','2027-05-31','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-05-31/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15139,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-05-31','2027-05-31','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-05-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15140,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-05-31','2027-05-31','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-05-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15141,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-01','2027-06-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15142,'Krabbelgruppe in Spöck',NULL,'2027-06-01','2027-06-01','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-06-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15143,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-06-01','2027-06-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-06-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15144,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-06-01','2027-06-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-06-01/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15145,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-06-01','2027-06-01','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-06-01/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15147,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-06-01','2027-06-01','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-06-01/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15148,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-06-02','2027-06-02','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-06-02/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15149,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-06-02','2027-06-02','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-06-02/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15150,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-06-03','2027-06-03','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-06-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15151,'Korallengarde (10–14 Jahre)',NULL,'2027-06-03','2027-06-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15152,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-06-03','2027-06-03','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-06-03/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15153,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-03','2027-06-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15154,'Seesternchengarde (3–6 Jahre)',NULL,'2027-06-03','2027-06-03','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-06-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15155,'Tee- und Spielstube',NULL,'2027-06-03','2027-06-03','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-06-03/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15156,'Teen Girls im GrauBau',NULL,'2027-06-03','2027-06-03','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-06-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15157,'Kreativfreitag im GrauBau',NULL,'2027-06-04','2027-06-04','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-06-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15158,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-06-04','2027-06-04','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-06-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15159,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-04','2027-06-04','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-06-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15160,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-06-05','2027-06-05','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-06-05/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15161,'Eltern-Baby-Café',NULL,'2027-06-07','2027-06-07','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-06-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15162,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-06-07','2027-06-07','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-06-07/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15163,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-07','2027-06-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15164,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-06-07','2027-06-07','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-06-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15165,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-08','2027-06-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15166,'Krabbelgruppe in Spöck',NULL,'2027-06-08','2027-06-08','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-06-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15167,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-06-08','2027-06-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-06-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15168,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-06-08','2027-06-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-06-08/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15169,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-06-08','2027-06-08','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-06-08/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15171,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-06-08','2027-06-08','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-06-08/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15172,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-06-09','2027-06-09','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-06-09/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15173,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-06-09','2027-06-09','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-06-09/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15174,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-06-10','2027-06-10','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-06-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15175,'Korallengarde (10–14 Jahre)',NULL,'2027-06-10','2027-06-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15176,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-06-10','2027-06-10','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-06-10/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15177,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-10','2027-06-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15178,'Seesternchengarde (3–6 Jahre)',NULL,'2027-06-10','2027-06-10','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-06-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15179,'Tee- und Spielstube',NULL,'2027-06-10','2027-06-10','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-06-10/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15180,'Teen Girls im GrauBau',NULL,'2027-06-10','2027-06-10','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-06-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15181,'Kreativfreitag im GrauBau',NULL,'2027-06-11','2027-06-11','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-06-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15182,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-06-11','2027-06-11','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-06-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15183,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-11','2027-06-11','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-06-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15184,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-06-12','2027-06-12','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-06-12/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15185,'Eltern-Baby-Café',NULL,'2027-06-14','2027-06-14','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-06-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15186,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-06-14','2027-06-14','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-06-14/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15187,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-14','2027-06-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15188,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-06-14','2027-06-14','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-06-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15189,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-15','2027-06-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15190,'Krabbelgruppe in Spöck',NULL,'2027-06-15','2027-06-15','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-06-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15191,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-06-15','2027-06-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-06-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15192,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-06-15','2027-06-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-06-15/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15193,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-06-15','2027-06-15','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-06-15/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15195,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-06-15','2027-06-15','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-06-15/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15196,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-06-16','2027-06-16','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-06-16/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15197,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-06-16','2027-06-16','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-06-16/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15198,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-06-17','2027-06-17','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-06-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15199,'Korallengarde (10–14 Jahre)',NULL,'2027-06-17','2027-06-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15200,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-06-17','2027-06-17','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-06-17/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15201,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-17','2027-06-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15202,'Seesternchengarde (3–6 Jahre)',NULL,'2027-06-17','2027-06-17','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-06-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15203,'Tee- und Spielstube',NULL,'2027-06-17','2027-06-17','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-06-17/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15204,'Teen Girls im GrauBau',NULL,'2027-06-17','2027-06-17','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-06-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15205,'Kreativfreitag im GrauBau',NULL,'2027-06-18','2027-06-18','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-06-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15206,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-06-18','2027-06-18','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-06-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15207,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-18','2027-06-18','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-06-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15208,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-06-19','2027-06-19','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-06-19/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15209,'Eltern-Baby-Café',NULL,'2027-06-21','2027-06-21','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-06-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15210,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-06-21','2027-06-21','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-06-21/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15211,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-21','2027-06-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15212,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-06-21','2027-06-21','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-06-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15213,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-22','2027-06-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15214,'Krabbelgruppe in Spöck',NULL,'2027-06-22','2027-06-22','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-06-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15215,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-06-22','2027-06-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-06-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15216,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-06-22','2027-06-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-06-22/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15217,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-06-22','2027-06-22','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-06-22/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15219,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-06-22','2027-06-22','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-06-22/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15220,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-06-23','2027-06-23','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-06-23/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15221,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-06-23','2027-06-23','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-06-23/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15222,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-06-24','2027-06-24','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-06-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15223,'Korallengarde (10–14 Jahre)',NULL,'2027-06-24','2027-06-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15224,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-06-24','2027-06-24','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-06-24/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15225,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-24','2027-06-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15226,'Seesternchengarde (3–6 Jahre)',NULL,'2027-06-24','2027-06-24','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-06-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15227,'Tee- und Spielstube',NULL,'2027-06-24','2027-06-24','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-06-24/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15228,'Teen Girls im GrauBau',NULL,'2027-06-24','2027-06-24','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-06-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15229,'Kreativfreitag im GrauBau',NULL,'2027-06-25','2027-06-25','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-06-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15230,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-06-25','2027-06-25','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-06-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15231,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-25','2027-06-25','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-06-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15232,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-06-26','2027-06-26','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-06-26/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15233,'Eltern-Baby-Café',NULL,'2027-06-28','2027-06-28','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-06-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15234,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-06-28','2027-06-28','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-06-28/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15235,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-06-28','2027-06-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-06-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15236,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-06-28','2027-06-28','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-06-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15237,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-06-29','2027-06-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-06-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15238,'Krabbelgruppe in Spöck',NULL,'2027-06-29','2027-06-29','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-06-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15239,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-06-29','2027-06-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-06-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15240,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-06-29','2027-06-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-06-29/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15241,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-06-29','2027-06-29','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-06-29/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15243,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-06-29','2027-06-29','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-06-29/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15244,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-06-30','2027-06-30','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-06-30/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15245,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-06-30','2027-06-30','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-06-30/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15246,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-07-01','2027-07-01','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-07-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15247,'Korallengarde (10–14 Jahre)',NULL,'2027-07-01','2027-07-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15248,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-07-01','2027-07-01','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-07-01/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15249,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-01','2027-07-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15250,'Seesternchengarde (3–6 Jahre)',NULL,'2027-07-01','2027-07-01','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-07-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15251,'Tee- und Spielstube',NULL,'2027-07-01','2027-07-01','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-07-01/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15252,'Teen Girls im GrauBau',NULL,'2027-07-01','2027-07-01','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-07-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15253,'Kreativfreitag im GrauBau',NULL,'2027-07-02','2027-07-02','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-07-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15254,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-07-02','2027-07-02','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-07-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15255,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-02','2027-07-02','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-07-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15256,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-07-03','2027-07-03','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-07-03/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15257,'Eltern-Baby-Café',NULL,'2027-07-05','2027-07-05','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-07-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15258,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-07-05','2027-07-05','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-07-05/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15259,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-05','2027-07-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15260,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-07-05','2027-07-05','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-07-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15261,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-06','2027-07-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15262,'Krabbelgruppe in Spöck',NULL,'2027-07-06','2027-07-06','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-07-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15263,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-07-06','2027-07-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-07-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15264,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-07-06','2027-07-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-07-06/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15265,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-07-06','2027-07-06','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-07-06/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15267,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-07-06','2027-07-06','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-07-06/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15268,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-07-07','2027-07-07','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-07-07/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15269,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-07-07','2027-07-07','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-07-07/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15270,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-07-08','2027-07-08','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-07-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15271,'Korallengarde (10–14 Jahre)',NULL,'2027-07-08','2027-07-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15272,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-07-08','2027-07-08','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-07-08/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15273,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-08','2027-07-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15274,'Seesternchengarde (3–6 Jahre)',NULL,'2027-07-08','2027-07-08','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-07-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15275,'Tee- und Spielstube',NULL,'2027-07-08','2027-07-08','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-07-08/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15276,'Teen Girls im GrauBau',NULL,'2027-07-08','2027-07-08','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-07-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15277,'Kreativfreitag im GrauBau',NULL,'2027-07-09','2027-07-09','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-07-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15278,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-07-09','2027-07-09','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-07-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15279,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-09','2027-07-09','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-07-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15280,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-07-10','2027-07-10','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-07-10/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15281,'Eltern-Baby-Café',NULL,'2027-07-12','2027-07-12','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-07-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15282,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-07-12','2027-07-12','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-07-12/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15283,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-12','2027-07-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15284,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-07-12','2027-07-12','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-07-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15285,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-13','2027-07-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15286,'Krabbelgruppe in Spöck',NULL,'2027-07-13','2027-07-13','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-07-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15287,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-07-13','2027-07-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-07-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15288,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-07-13','2027-07-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-07-13/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15289,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-07-13','2027-07-13','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-07-13/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15291,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-07-13','2027-07-13','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-07-13/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15292,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-07-14','2027-07-14','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-07-14/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15293,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-07-14','2027-07-14','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-07-14/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15294,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-07-15','2027-07-15','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-07-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15295,'Korallengarde (10–14 Jahre)',NULL,'2027-07-15','2027-07-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15296,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-07-15','2027-07-15','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-07-15/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15297,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-15','2027-07-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15298,'Seesternchengarde (3–6 Jahre)',NULL,'2027-07-15','2027-07-15','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-07-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15299,'Tee- und Spielstube',NULL,'2027-07-15','2027-07-15','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-07-15/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15300,'Teen Girls im GrauBau',NULL,'2027-07-15','2027-07-15','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-07-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15301,'Kreativfreitag im GrauBau',NULL,'2027-07-16','2027-07-16','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-07-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15302,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-07-16','2027-07-16','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-07-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15303,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-16','2027-07-16','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-07-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15304,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-07-17','2027-07-17','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-07-17/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15305,'Eltern-Baby-Café',NULL,'2027-07-19','2027-07-19','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-07-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15306,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-07-19','2027-07-19','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-07-19/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15307,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-19','2027-07-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15308,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-07-19','2027-07-19','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-07-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15309,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-20','2027-07-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15310,'Krabbelgruppe in Spöck',NULL,'2027-07-20','2027-07-20','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-07-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15311,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-07-20','2027-07-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-07-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15312,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-07-20','2027-07-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-07-20/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15313,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-07-20','2027-07-20','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-07-20/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15315,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-07-20','2027-07-20','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-07-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15316,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-07-21','2027-07-21','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-07-21/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15317,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-07-21','2027-07-21','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-07-21/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15318,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-07-22','2027-07-22','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-07-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15319,'Korallengarde (10–14 Jahre)',NULL,'2027-07-22','2027-07-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15320,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-07-22','2027-07-22','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-07-22/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15321,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-22','2027-07-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15322,'Seesternchengarde (3–6 Jahre)',NULL,'2027-07-22','2027-07-22','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-07-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15323,'Tee- und Spielstube',NULL,'2027-07-22','2027-07-22','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-07-22/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15324,'Teen Girls im GrauBau',NULL,'2027-07-22','2027-07-22','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-07-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15325,'Kreativfreitag im GrauBau',NULL,'2027-07-23','2027-07-23','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-07-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15326,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-07-23','2027-07-23','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-07-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15327,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-23','2027-07-23','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-07-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15328,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-07-24','2027-07-24','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-07-24/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15329,'Eltern-Baby-Café',NULL,'2027-07-26','2027-07-26','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-07-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15330,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-07-26','2027-07-26','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-07-26/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15331,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-26','2027-07-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15332,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-07-26','2027-07-26','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-07-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15333,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-27','2027-07-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15334,'Krabbelgruppe in Spöck',NULL,'2027-07-27','2027-07-27','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-07-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15335,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-07-27','2027-07-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-07-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15336,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-07-27','2027-07-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-07-27/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15337,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-07-27','2027-07-27','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-07-27/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15339,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-07-27','2027-07-27','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-07-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15340,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-07-28','2027-07-28','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-07-28/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15341,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-07-28','2027-07-28','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-07-28/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15342,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-07-29','2027-07-29','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-07-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15343,'Korallengarde (10–14 Jahre)',NULL,'2027-07-29','2027-07-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-07-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15344,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-07-29','2027-07-29','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-07-29/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15345,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-07-29','2027-07-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-07-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15346,'Seesternchengarde (3–6 Jahre)',NULL,'2027-07-29','2027-07-29','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-07-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15347,'Tee- und Spielstube',NULL,'2027-07-29','2027-07-29','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-07-29/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15348,'Teen Girls im GrauBau',NULL,'2027-07-29','2027-07-29','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-07-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15349,'Kreativfreitag im GrauBau',NULL,'2027-07-30','2027-07-30','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-07-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15350,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-07-30','2027-07-30','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-07-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15351,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-07-30','2027-07-30','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-07-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15352,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-07-31','2027-07-31','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-07-31/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15353,'Eltern-Baby-Café',NULL,'2027-08-02','2027-08-02','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-08-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15354,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-08-02','2027-08-02','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-08-02/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15355,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-02','2027-08-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15356,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-08-02','2027-08-02','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-08-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15357,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-03','2027-08-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15358,'Krabbelgruppe in Spöck',NULL,'2027-08-03','2027-08-03','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-08-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15359,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-08-03','2027-08-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-08-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15360,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-08-03','2027-08-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-08-03/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15361,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-08-03','2027-08-03','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-08-03/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15363,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-08-03','2027-08-03','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-08-03/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15364,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-08-04','2027-08-04','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-08-04/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15365,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-08-04','2027-08-04','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-08-04/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15366,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-08-05','2027-08-05','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-08-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15367,'Korallengarde (10–14 Jahre)',NULL,'2027-08-05','2027-08-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15368,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-08-05','2027-08-05','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-08-05/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15369,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-05','2027-08-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15370,'Seesternchengarde (3–6 Jahre)',NULL,'2027-08-05','2027-08-05','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-08-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15371,'Tee- und Spielstube',NULL,'2027-08-05','2027-08-05','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-08-05/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15372,'Teen Girls im GrauBau',NULL,'2027-08-05','2027-08-05','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-08-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15373,'Kreativfreitag im GrauBau',NULL,'2027-08-06','2027-08-06','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-08-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15374,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-08-06','2027-08-06','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-08-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15375,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-06','2027-08-06','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-08-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15376,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-08-07','2027-08-07','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-08-07/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15377,'Eltern-Baby-Café',NULL,'2027-08-09','2027-08-09','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-08-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15378,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-08-09','2027-08-09','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-08-09/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15379,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-09','2027-08-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15380,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-08-09','2027-08-09','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-08-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15381,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-10','2027-08-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15382,'Krabbelgruppe in Spöck',NULL,'2027-08-10','2027-08-10','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-08-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15383,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-08-10','2027-08-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-08-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15384,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-08-10','2027-08-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-08-10/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15385,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-08-10','2027-08-10','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-08-10/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15387,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-08-10','2027-08-10','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-08-10/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15388,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-08-11','2027-08-11','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-08-11/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15389,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-08-11','2027-08-11','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-08-11/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15390,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-08-12','2027-08-12','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-08-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15391,'Korallengarde (10–14 Jahre)',NULL,'2027-08-12','2027-08-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15392,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-08-12','2027-08-12','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-08-12/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15393,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-12','2027-08-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15394,'Seesternchengarde (3–6 Jahre)',NULL,'2027-08-12','2027-08-12','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-08-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15395,'Tee- und Spielstube',NULL,'2027-08-12','2027-08-12','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-08-12/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15396,'Teen Girls im GrauBau',NULL,'2027-08-12','2027-08-12','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-08-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15397,'Kreativfreitag im GrauBau',NULL,'2027-08-13','2027-08-13','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-08-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15398,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-08-13','2027-08-13','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-08-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15399,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-13','2027-08-13','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-08-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15400,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-08-14','2027-08-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-08-14/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15401,'Eltern-Baby-Café',NULL,'2027-08-16','2027-08-16','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-08-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15402,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-08-16','2027-08-16','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-08-16/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15403,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-16','2027-08-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15404,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-08-16','2027-08-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-08-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15405,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-17','2027-08-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15406,'Krabbelgruppe in Spöck',NULL,'2027-08-17','2027-08-17','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-08-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15407,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-08-17','2027-08-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-08-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15408,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-08-17','2027-08-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-08-17/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15409,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-08-17','2027-08-17','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-08-17/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15411,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-08-17','2027-08-17','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-08-17/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15412,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-08-18','2027-08-18','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-08-18/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15413,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-08-18','2027-08-18','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-08-18/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15414,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-08-19','2027-08-19','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-08-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15415,'Korallengarde (10–14 Jahre)',NULL,'2027-08-19','2027-08-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15416,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-08-19','2027-08-19','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-08-19/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15417,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-19','2027-08-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15418,'Seesternchengarde (3–6 Jahre)',NULL,'2027-08-19','2027-08-19','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-08-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15419,'Tee- und Spielstube',NULL,'2027-08-19','2027-08-19','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-08-19/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15420,'Teen Girls im GrauBau',NULL,'2027-08-19','2027-08-19','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-08-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15421,'Kreativfreitag im GrauBau',NULL,'2027-08-20','2027-08-20','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-08-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15422,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-08-20','2027-08-20','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-08-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15423,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-20','2027-08-20','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-08-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15424,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-08-21','2027-08-21','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-08-21/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15425,'Eltern-Baby-Café',NULL,'2027-08-23','2027-08-23','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-08-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15426,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-08-23','2027-08-23','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-08-23/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15427,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-23','2027-08-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15428,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-08-23','2027-08-23','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-08-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15429,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-24','2027-08-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15430,'Krabbelgruppe in Spöck',NULL,'2027-08-24','2027-08-24','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-08-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15431,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-08-24','2027-08-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-08-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15432,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-08-24','2027-08-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-08-24/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15433,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-08-24','2027-08-24','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-08-24/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15435,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-08-24','2027-08-24','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-08-24/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15436,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-08-25','2027-08-25','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-08-25/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15437,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-08-25','2027-08-25','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-08-25/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15438,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-08-26','2027-08-26','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-08-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15439,'Korallengarde (10–14 Jahre)',NULL,'2027-08-26','2027-08-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15440,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-08-26','2027-08-26','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-08-26/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15441,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-26','2027-08-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15442,'Seesternchengarde (3–6 Jahre)',NULL,'2027-08-26','2027-08-26','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-08-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15443,'Tee- und Spielstube',NULL,'2027-08-26','2027-08-26','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-08-26/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15444,'Teen Girls im GrauBau',NULL,'2027-08-26','2027-08-26','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-08-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15445,'Kreativfreitag im GrauBau',NULL,'2027-08-27','2027-08-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-08-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15446,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-08-27','2027-08-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-08-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15447,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-27','2027-08-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-08-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15448,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-08-28','2027-08-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-08-28/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15449,'Eltern-Baby-Café',NULL,'2027-08-30','2027-08-30','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-08-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15450,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-08-30','2027-08-30','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-08-30/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15451,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-08-30','2027-08-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-08-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15452,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-08-30','2027-08-30','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-08-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15453,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-08-31','2027-08-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-08-31/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15454,'Krabbelgruppe in Spöck',NULL,'2027-08-31','2027-08-31','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-08-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15455,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-08-31','2027-08-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-08-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15456,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-08-31','2027-08-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-08-31/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15457,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-08-31','2027-08-31','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-08-31/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15459,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-08-31','2027-08-31','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-08-31/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15460,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-09-01','2027-09-01','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-09-01/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15461,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-09-01','2027-09-01','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-09-01/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15462,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-09-02','2027-09-02','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-09-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15463,'Korallengarde (10–14 Jahre)',NULL,'2027-09-02','2027-09-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15464,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-09-02','2027-09-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-09-02/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15465,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-02','2027-09-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15466,'Seesternchengarde (3–6 Jahre)',NULL,'2027-09-02','2027-09-02','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-09-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15467,'Tee- und Spielstube',NULL,'2027-09-02','2027-09-02','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-09-02/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15468,'Teen Girls im GrauBau',NULL,'2027-09-02','2027-09-02','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-09-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15469,'Kreativfreitag im GrauBau',NULL,'2027-09-03','2027-09-03','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-09-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15470,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-09-03','2027-09-03','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-09-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15471,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-03','2027-09-03','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-09-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15472,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-09-04','2027-09-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-09-04/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15473,'Eltern-Baby-Café',NULL,'2027-09-06','2027-09-06','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-09-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15474,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-09-06','2027-09-06','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-09-06/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15475,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-06','2027-09-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15476,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-09-06','2027-09-06','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-09-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15477,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-07','2027-09-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15478,'Krabbelgruppe in Spöck',NULL,'2027-09-07','2027-09-07','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-09-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15479,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-09-07','2027-09-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-09-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15480,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-09-07','2027-09-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-09-07/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15481,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-09-07','2027-09-07','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-09-07/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15483,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-09-07','2027-09-07','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-09-07/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15484,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-09-08','2027-09-08','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-09-08/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15485,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-09-08','2027-09-08','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-09-08/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15486,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-09-09','2027-09-09','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-09-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15487,'Korallengarde (10–14 Jahre)',NULL,'2027-09-09','2027-09-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15488,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-09-09','2027-09-09','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-09-09/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15489,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-09','2027-09-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15490,'Seesternchengarde (3–6 Jahre)',NULL,'2027-09-09','2027-09-09','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-09-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15491,'Tee- und Spielstube',NULL,'2027-09-09','2027-09-09','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-09-09/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15492,'Teen Girls im GrauBau',NULL,'2027-09-09','2027-09-09','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-09-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15493,'Kreativfreitag im GrauBau',NULL,'2027-09-10','2027-09-10','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-09-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15494,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-09-10','2027-09-10','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-09-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15495,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-10','2027-09-10','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-09-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15496,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-09-11','2027-09-11','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-09-11/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15497,'Eltern-Baby-Café',NULL,'2027-09-13','2027-09-13','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-09-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15498,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-09-13','2027-09-13','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-09-13/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15499,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-13','2027-09-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15500,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-09-13','2027-09-13','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-09-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15501,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-14','2027-09-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15502,'Krabbelgruppe in Spöck',NULL,'2027-09-14','2027-09-14','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-09-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15503,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-09-14','2027-09-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-09-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15504,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-09-14','2027-09-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-09-14/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15505,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-09-14','2027-09-14','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-09-14/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15507,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-09-14','2027-09-14','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-09-14/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15508,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-09-15','2027-09-15','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-09-15/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15509,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-09-15','2027-09-15','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-09-15/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15510,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-09-16','2027-09-16','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-09-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15511,'Korallengarde (10–14 Jahre)',NULL,'2027-09-16','2027-09-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15512,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-09-16','2027-09-16','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-09-16/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15513,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-16','2027-09-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15514,'Seesternchengarde (3–6 Jahre)',NULL,'2027-09-16','2027-09-16','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-09-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15515,'Tee- und Spielstube',NULL,'2027-09-16','2027-09-16','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-09-16/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15516,'Teen Girls im GrauBau',NULL,'2027-09-16','2027-09-16','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-09-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15517,'Kreativfreitag im GrauBau',NULL,'2027-09-17','2027-09-17','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-09-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15518,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-09-17','2027-09-17','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-09-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15519,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-17','2027-09-17','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-09-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15520,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-09-18','2027-09-18','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-09-18/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15521,'Eltern-Baby-Café',NULL,'2027-09-20','2027-09-20','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-09-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15522,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-09-20','2027-09-20','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-09-20/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15523,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-20','2027-09-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15524,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-09-20','2027-09-20','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-09-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15525,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-21','2027-09-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15526,'Krabbelgruppe in Spöck',NULL,'2027-09-21','2027-09-21','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-09-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15527,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-09-21','2027-09-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-09-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15528,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-09-21','2027-09-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-09-21/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15529,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-09-21','2027-09-21','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-09-21/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15531,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-09-21','2027-09-21','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-09-21/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15532,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-09-22','2027-09-22','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-09-22/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15533,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-09-22','2027-09-22','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-09-22/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15534,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-09-23','2027-09-23','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-09-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15535,'Korallengarde (10–14 Jahre)',NULL,'2027-09-23','2027-09-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15536,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-09-23','2027-09-23','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-09-23/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15537,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-23','2027-09-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15538,'Seesternchengarde (3–6 Jahre)',NULL,'2027-09-23','2027-09-23','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-09-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15539,'Tee- und Spielstube',NULL,'2027-09-23','2027-09-23','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-09-23/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15540,'Teen Girls im GrauBau',NULL,'2027-09-23','2027-09-23','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-09-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15541,'Kreativfreitag im GrauBau',NULL,'2027-09-24','2027-09-24','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-09-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15542,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-09-24','2027-09-24','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-09-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15543,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-24','2027-09-24','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-09-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15544,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-09-25','2027-09-25','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-09-25/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15545,'Eltern-Baby-Café',NULL,'2027-09-27','2027-09-27','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-09-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15546,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-09-27','2027-09-27','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-09-27/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15547,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-27','2027-09-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15548,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-09-27','2027-09-27','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-09-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15549,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-09-28','2027-09-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15550,'Krabbelgruppe in Spöck',NULL,'2027-09-28','2027-09-28','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-09-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15551,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-09-28','2027-09-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-09-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15552,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-09-28','2027-09-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-09-28/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15553,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-09-28','2027-09-28','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-09-28/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15555,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-09-28','2027-09-28','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-09-28/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15556,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-09-29','2027-09-29','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-09-29/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15557,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-09-29','2027-09-29','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-09-29/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15558,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-09-30','2027-09-30','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-09-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15559,'Korallengarde (10–14 Jahre)',NULL,'2027-09-30','2027-09-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-09-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15560,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-09-30','2027-09-30','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-09-30/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15561,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-09-30','2027-09-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-09-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15562,'Seesternchengarde (3–6 Jahre)',NULL,'2027-09-30','2027-09-30','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-09-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15563,'Tee- und Spielstube',NULL,'2027-09-30','2027-09-30','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-09-30/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15564,'Teen Girls im GrauBau',NULL,'2027-09-30','2027-09-30','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-09-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15565,'Kreativfreitag im GrauBau',NULL,'2027-10-01','2027-10-01','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-10-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15566,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-10-01','2027-10-01','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-10-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15567,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-01','2027-10-01','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-10-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15568,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-10-02','2027-10-02','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-10-02/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15569,'Eltern-Baby-Café',NULL,'2027-10-04','2027-10-04','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-10-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15570,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-10-04','2027-10-04','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-10-04/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15571,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-04','2027-10-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15572,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-10-04','2027-10-04','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-10-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15573,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-05','2027-10-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15574,'Krabbelgruppe in Spöck',NULL,'2027-10-05','2027-10-05','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-10-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15575,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-10-05','2027-10-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-10-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15576,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-10-05','2027-10-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-10-05/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15577,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-10-05','2027-10-05','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-10-05/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15579,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-10-05','2027-10-05','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-10-05/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15580,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-10-06','2027-10-06','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-10-06/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15581,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-10-06','2027-10-06','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-10-06/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15582,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-10-07','2027-10-07','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-10-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15583,'Korallengarde (10–14 Jahre)',NULL,'2027-10-07','2027-10-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15584,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-10-07','2027-10-07','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-10-07/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15585,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-07','2027-10-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15586,'Seesternchengarde (3–6 Jahre)',NULL,'2027-10-07','2027-10-07','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-10-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15587,'Tee- und Spielstube',NULL,'2027-10-07','2027-10-07','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-10-07/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15588,'Teen Girls im GrauBau',NULL,'2027-10-07','2027-10-07','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-10-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15589,'Kreativfreitag im GrauBau',NULL,'2027-10-08','2027-10-08','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-10-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15590,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-10-08','2027-10-08','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-10-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15591,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-08','2027-10-08','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-10-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15592,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-10-09','2027-10-09','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-10-09/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15593,'Eltern-Baby-Café',NULL,'2027-10-11','2027-10-11','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-10-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15594,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-10-11','2027-10-11','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-10-11/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15595,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-11','2027-10-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15596,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-10-11','2027-10-11','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-10-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15597,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-12','2027-10-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15598,'Krabbelgruppe in Spöck',NULL,'2027-10-12','2027-10-12','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-10-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15599,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-10-12','2027-10-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-10-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15600,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-10-12','2027-10-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-10-12/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15601,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-10-12','2027-10-12','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-10-12/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15603,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-10-12','2027-10-12','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-10-12/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15604,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-10-13','2027-10-13','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-10-13/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15605,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-10-13','2027-10-13','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-10-13/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15606,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-10-14','2027-10-14','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-10-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15607,'Korallengarde (10–14 Jahre)',NULL,'2027-10-14','2027-10-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15608,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-10-14','2027-10-14','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-10-14/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15609,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-14','2027-10-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15610,'Seesternchengarde (3–6 Jahre)',NULL,'2027-10-14','2027-10-14','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-10-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15611,'Tee- und Spielstube',NULL,'2027-10-14','2027-10-14','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-10-14/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15612,'Teen Girls im GrauBau',NULL,'2027-10-14','2027-10-14','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-10-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15613,'Kreativfreitag im GrauBau',NULL,'2027-10-15','2027-10-15','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-10-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15614,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-10-15','2027-10-15','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-10-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15615,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-15','2027-10-15','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-10-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15616,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-10-16','2027-10-16','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-10-16/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15617,'Eltern-Baby-Café',NULL,'2027-10-18','2027-10-18','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-10-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15618,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-10-18','2027-10-18','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-10-18/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15619,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-18','2027-10-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15620,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-10-18','2027-10-18','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-10-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15621,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-19','2027-10-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15622,'Krabbelgruppe in Spöck',NULL,'2027-10-19','2027-10-19','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-10-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15623,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-10-19','2027-10-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-10-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15624,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-10-19','2027-10-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-10-19/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15625,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-10-19','2027-10-19','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-10-19/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15627,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-10-19','2027-10-19','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-10-19/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15628,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-10-20','2027-10-20','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-10-20/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15629,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-10-20','2027-10-20','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-10-20/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15630,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-10-21','2027-10-21','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-10-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15631,'Korallengarde (10–14 Jahre)',NULL,'2027-10-21','2027-10-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15632,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-10-21','2027-10-21','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-10-21/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15633,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-21','2027-10-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15634,'Seesternchengarde (3–6 Jahre)',NULL,'2027-10-21','2027-10-21','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-10-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15635,'Tee- und Spielstube',NULL,'2027-10-21','2027-10-21','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-10-21/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15636,'Teen Girls im GrauBau',NULL,'2027-10-21','2027-10-21','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-10-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15637,'Kreativfreitag im GrauBau',NULL,'2027-10-22','2027-10-22','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-10-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15638,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-10-22','2027-10-22','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-10-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15639,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-22','2027-10-22','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-10-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15640,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-10-23','2027-10-23','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-10-23/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15641,'Eltern-Baby-Café',NULL,'2027-10-25','2027-10-25','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-10-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15642,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-10-25','2027-10-25','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-10-25/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15643,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-25','2027-10-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15644,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-10-25','2027-10-25','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-10-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15645,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-26','2027-10-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15646,'Krabbelgruppe in Spöck',NULL,'2027-10-26','2027-10-26','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-10-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15647,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-10-26','2027-10-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-10-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15648,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-10-26','2027-10-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-10-26/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15649,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-10-26','2027-10-26','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-10-26/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15651,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-10-26','2027-10-26','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-10-26/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15652,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-10-27','2027-10-27','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-10-27/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15653,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-10-27','2027-10-27','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-10-27/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15654,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-10-28','2027-10-28','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-10-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15655,'Korallengarde (10–14 Jahre)',NULL,'2027-10-28','2027-10-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-10-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15656,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-10-28','2027-10-28','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-10-28/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15657,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-10-28','2027-10-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-10-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15658,'Seesternchengarde (3–6 Jahre)',NULL,'2027-10-28','2027-10-28','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-10-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15659,'Tee- und Spielstube',NULL,'2027-10-28','2027-10-28','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-10-28/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15660,'Teen Girls im GrauBau',NULL,'2027-10-28','2027-10-28','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-10-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15661,'Kreativfreitag im GrauBau',NULL,'2027-10-29','2027-10-29','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-10-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15662,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-10-29','2027-10-29','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-10-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15663,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-10-29','2027-10-29','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-10-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15664,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-10-30','2027-10-30','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-10-30/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15665,'Eltern-Baby-Café',NULL,'2027-11-01','2027-11-01','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-11-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15666,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-11-01','2027-11-01','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-11-01/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15667,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-01','2027-11-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15668,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-11-01','2027-11-01','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-11-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15669,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-02','2027-11-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15670,'Krabbelgruppe in Spöck',NULL,'2027-11-02','2027-11-02','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-11-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15671,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-11-02','2027-11-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-11-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15672,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-11-02','2027-11-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-11-02/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15673,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-11-02','2027-11-02','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-11-02/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15675,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-11-02','2027-11-02','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-11-02/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15676,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-11-03','2027-11-03','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-11-03/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15677,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-11-03','2027-11-03','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-11-03/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15678,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-11-04','2027-11-04','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-11-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15679,'Korallengarde (10–14 Jahre)',NULL,'2027-11-04','2027-11-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15680,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-11-04','2027-11-04','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-11-04/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15681,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-04','2027-11-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15682,'Seesternchengarde (3–6 Jahre)',NULL,'2027-11-04','2027-11-04','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-11-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15683,'Tee- und Spielstube',NULL,'2027-11-04','2027-11-04','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-11-04/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15684,'Teen Girls im GrauBau',NULL,'2027-11-04','2027-11-04','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-11-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15685,'Kreativfreitag im GrauBau',NULL,'2027-11-05','2027-11-05','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-11-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15686,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-11-05','2027-11-05','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-11-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15687,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-05','2027-11-05','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-11-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15688,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-11-06','2027-11-06','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-11-06/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15689,'Eltern-Baby-Café',NULL,'2027-11-08','2027-11-08','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-11-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15690,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-11-08','2027-11-08','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-11-08/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15691,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-08','2027-11-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15692,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-11-08','2027-11-08','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-11-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15693,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-09','2027-11-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15694,'Krabbelgruppe in Spöck',NULL,'2027-11-09','2027-11-09','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-11-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15695,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-11-09','2027-11-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-11-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15696,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-11-09','2027-11-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-11-09/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15697,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-11-09','2027-11-09','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-11-09/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15699,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-11-09','2027-11-09','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-11-09/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15700,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-11-10','2027-11-10','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-11-10/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15701,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-11-10','2027-11-10','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-11-10/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15702,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-11-11','2027-11-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-11-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15703,'Korallengarde (10–14 Jahre)',NULL,'2027-11-11','2027-11-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15704,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-11-11','2027-11-11','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-11-11/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15705,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-11','2027-11-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15706,'Seesternchengarde (3–6 Jahre)',NULL,'2027-11-11','2027-11-11','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-11-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15707,'Tee- und Spielstube',NULL,'2027-11-11','2027-11-11','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-11-11/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15708,'Teen Girls im GrauBau',NULL,'2027-11-11','2027-11-11','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-11-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15709,'Kreativfreitag im GrauBau',NULL,'2027-11-12','2027-11-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-11-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15710,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-11-12','2027-11-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-11-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15711,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-12','2027-11-12','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-11-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15712,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-11-13','2027-11-13','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-11-13/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15713,'Eltern-Baby-Café',NULL,'2027-11-15','2027-11-15','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-11-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15714,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-11-15','2027-11-15','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-11-15/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15715,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-15','2027-11-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15716,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-11-15','2027-11-15','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-11-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15717,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-16','2027-11-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15718,'Krabbelgruppe in Spöck',NULL,'2027-11-16','2027-11-16','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-11-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15719,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-11-16','2027-11-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-11-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15720,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-11-16','2027-11-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-11-16/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15721,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-11-16','2027-11-16','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-11-16/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15723,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-11-16','2027-11-16','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-11-16/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15724,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-11-17','2027-11-17','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-11-17/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15725,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-11-17','2027-11-17','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-11-17/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15726,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-11-18','2027-11-18','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-11-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15727,'Korallengarde (10–14 Jahre)',NULL,'2027-11-18','2027-11-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15728,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-11-18','2027-11-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-11-18/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15729,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-18','2027-11-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15730,'Seesternchengarde (3–6 Jahre)',NULL,'2027-11-18','2027-11-18','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-11-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15731,'Tee- und Spielstube',NULL,'2027-11-18','2027-11-18','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-11-18/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15732,'Teen Girls im GrauBau',NULL,'2027-11-18','2027-11-18','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-11-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15733,'Kreativfreitag im GrauBau',NULL,'2027-11-19','2027-11-19','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-11-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15734,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-11-19','2027-11-19','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-11-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15735,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-19','2027-11-19','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-11-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15736,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-11-20','2027-11-20','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-11-20/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15737,'Eltern-Baby-Café',NULL,'2027-11-22','2027-11-22','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-11-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15738,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-11-22','2027-11-22','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-11-22/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15739,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-22','2027-11-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15740,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-11-22','2027-11-22','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-11-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15741,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-23','2027-11-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15742,'Krabbelgruppe in Spöck',NULL,'2027-11-23','2027-11-23','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-11-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15743,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-11-23','2027-11-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-11-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15744,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-11-23','2027-11-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-11-23/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15745,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-11-23','2027-11-23','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-11-23/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15747,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-11-23','2027-11-23','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-11-23/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15748,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-11-24','2027-11-24','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-11-24/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15749,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-11-24','2027-11-24','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-11-24/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15750,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-11-25','2027-11-25','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-11-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15751,'Korallengarde (10–14 Jahre)',NULL,'2027-11-25','2027-11-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15752,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-11-25','2027-11-25','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-11-25/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15753,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-25','2027-11-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15754,'Seesternchengarde (3–6 Jahre)',NULL,'2027-11-25','2027-11-25','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-11-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15755,'Tee- und Spielstube',NULL,'2027-11-25','2027-11-25','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-11-25/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15756,'Teen Girls im GrauBau',NULL,'2027-11-25','2027-11-25','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-11-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15757,'Kreativfreitag im GrauBau',NULL,'2027-11-26','2027-11-26','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-11-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15758,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-11-26','2027-11-26','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-11-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15759,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-26','2027-11-26','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-11-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15760,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-11-27','2027-11-27','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-11-27/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15761,'Eltern-Baby-Café',NULL,'2027-11-29','2027-11-29','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-11-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15762,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-11-29','2027-11-29','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-11-29/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15763,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-11-29','2027-11-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-11-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15764,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-11-29','2027-11-29','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-11-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15765,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-11-30','2027-11-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-11-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15766,'Krabbelgruppe in Spöck',NULL,'2027-11-30','2027-11-30','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-11-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15767,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-11-30','2027-11-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-11-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15768,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-11-30','2027-11-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-11-30/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15769,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-11-30','2027-11-30','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-11-30/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15771,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-11-30','2027-11-30','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-11-30/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15772,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-12-01','2027-12-01','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-12-01/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15773,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-12-01','2027-12-01','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-12-01/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15774,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-12-02','2027-12-02','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-12-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15775,'Korallengarde (10–14 Jahre)',NULL,'2027-12-02','2027-12-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15776,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-12-02','2027-12-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-12-02/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15777,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-02','2027-12-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15778,'Seesternchengarde (3–6 Jahre)',NULL,'2027-12-02','2027-12-02','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-12-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15779,'Tee- und Spielstube',NULL,'2027-12-02','2027-12-02','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-12-02/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15780,'Teen Girls im GrauBau',NULL,'2027-12-02','2027-12-02','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-12-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15781,'Kreativfreitag im GrauBau',NULL,'2027-12-03','2027-12-03','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-12-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15782,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-12-03','2027-12-03','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-12-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15783,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-03','2027-12-03','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-12-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15784,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-12-04','2027-12-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-12-04/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15785,'Eltern-Baby-Café',NULL,'2027-12-06','2027-12-06','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-12-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15786,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-12-06','2027-12-06','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-12-06/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15787,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-06','2027-12-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15788,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-12-06','2027-12-06','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-12-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15789,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-07','2027-12-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15790,'Krabbelgruppe in Spöck',NULL,'2027-12-07','2027-12-07','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-12-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15791,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-12-07','2027-12-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-12-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15792,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-12-07','2027-12-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-12-07/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15793,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-12-07','2027-12-07','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-12-07/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15795,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-12-07','2027-12-07','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-12-07/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15796,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-12-08','2027-12-08','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-12-08/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15797,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-12-08','2027-12-08','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-12-08/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15798,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-12-09','2027-12-09','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-12-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15799,'Korallengarde (10–14 Jahre)',NULL,'2027-12-09','2027-12-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15800,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-12-09','2027-12-09','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-12-09/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15801,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-09','2027-12-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15802,'Seesternchengarde (3–6 Jahre)',NULL,'2027-12-09','2027-12-09','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-12-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15803,'Tee- und Spielstube',NULL,'2027-12-09','2027-12-09','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-12-09/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15804,'Teen Girls im GrauBau',NULL,'2027-12-09','2027-12-09','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-12-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15805,'Kreativfreitag im GrauBau',NULL,'2027-12-10','2027-12-10','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-12-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15806,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-12-10','2027-12-10','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-12-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15807,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-10','2027-12-10','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-12-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15808,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-12-11','2027-12-11','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-12-11/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15809,'Eltern-Baby-Café',NULL,'2027-12-13','2027-12-13','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-12-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15810,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-12-13','2027-12-13','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-12-13/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15811,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-13','2027-12-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15812,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-12-13','2027-12-13','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-12-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15813,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-14','2027-12-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15814,'Krabbelgruppe in Spöck',NULL,'2027-12-14','2027-12-14','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-12-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15815,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-12-14','2027-12-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-12-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15816,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-12-14','2027-12-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-12-14/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15817,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-12-14','2027-12-14','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-12-14/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15819,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-12-14','2027-12-14','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-12-14/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15820,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-12-15','2027-12-15','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-12-15/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15821,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-12-15','2027-12-15','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-12-15/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15822,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-12-16','2027-12-16','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-12-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15823,'Korallengarde (10–14 Jahre)',NULL,'2027-12-16','2027-12-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15824,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-12-16','2027-12-16','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-12-16/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15825,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-16','2027-12-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15826,'Seesternchengarde (3–6 Jahre)',NULL,'2027-12-16','2027-12-16','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-12-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15827,'Tee- und Spielstube',NULL,'2027-12-16','2027-12-16','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-12-16/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15828,'Teen Girls im GrauBau',NULL,'2027-12-16','2027-12-16','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-12-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15829,'Kreativfreitag im GrauBau',NULL,'2027-12-17','2027-12-17','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-12-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15830,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-12-17','2027-12-17','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-12-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15831,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-17','2027-12-17','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-12-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15832,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-12-18','2027-12-18','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-12-18/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15833,'Eltern-Baby-Café',NULL,'2027-12-20','2027-12-20','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-12-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15834,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-12-20','2027-12-20','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-12-20/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15835,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-20','2027-12-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15836,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-12-20','2027-12-20','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-12-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15837,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-21','2027-12-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15838,'Krabbelgruppe in Spöck',NULL,'2027-12-21','2027-12-21','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-12-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15839,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-12-21','2027-12-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-12-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15840,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-12-21','2027-12-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-12-21/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15841,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-12-21','2027-12-21','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-12-21/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15843,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-12-21','2027-12-21','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-12-21/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15844,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-12-22','2027-12-22','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-12-22/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15845,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-12-22','2027-12-22','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-12-22/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15846,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-12-23','2027-12-23','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-12-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15847,'Korallengarde (10–14 Jahre)',NULL,'2027-12-23','2027-12-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15848,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-12-23','2027-12-23','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-12-23/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15849,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-23','2027-12-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15850,'Seesternchengarde (3–6 Jahre)',NULL,'2027-12-23','2027-12-23','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-12-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15851,'Tee- und Spielstube',NULL,'2027-12-23','2027-12-23','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-12-23/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15852,'Teen Girls im GrauBau',NULL,'2027-12-23','2027-12-23','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-12-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15853,'Kreativfreitag im GrauBau',NULL,'2027-12-24','2027-12-24','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-12-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15854,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-12-24','2027-12-24','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-12-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15855,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-24','2027-12-24','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-12-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15856,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2027-12-25','2027-12-25','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2027-12-25/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15857,'Eltern-Baby-Café',NULL,'2027-12-27','2027-12-27','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2027-12-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15858,'Kinder- und Jugendtraining – Wilde 13',NULL,'2027-12-27','2027-12-27','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2027-12-27/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15859,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-27','2027-12-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15860,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2027-12-27','2027-12-27','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2027-12-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15861,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-28','2027-12-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15862,'Krabbelgruppe in Spöck',NULL,'2027-12-28','2027-12-28','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2027-12-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15863,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2027-12-28','2027-12-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-12-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15864,'Pfadfinder*innengruppe Wölflinge',NULL,'2027-12-28','2027-12-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-12-28/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15865,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2027-12-28','2027-12-28','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2027-12-28/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15867,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2027-12-28','2027-12-28','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2027-12-28/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15868,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2027-12-29','2027-12-29','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-12-29/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15869,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2027-12-29','2027-12-29','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2027-12-29/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15870,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2027-12-30','2027-12-30','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2027-12-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15871,'Korallengarde (10–14 Jahre)',NULL,'2027-12-30','2027-12-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2027-12-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15872,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2027-12-30','2027-12-30','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2027-12-30/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15873,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2027-12-30','2027-12-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2027-12-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15874,'Seesternchengarde (3–6 Jahre)',NULL,'2027-12-30','2027-12-30','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2027-12-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15875,'Tee- und Spielstube',NULL,'2027-12-30','2027-12-30','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-12-30/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15876,'Teen Girls im GrauBau',NULL,'2027-12-30','2027-12-30','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2027-12-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15877,'Kreativfreitag im GrauBau',NULL,'2027-12-31','2027-12-31','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2027-12-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15878,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2027-12-31','2027-12-31','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-12-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15879,'Seepferdchengarde (6–10 Jahre)',NULL,'2027-12-31','2027-12-31','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2027-12-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15880,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-01-01','2028-01-01','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-01-01/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15881,'Eltern-Baby-Café',NULL,'2028-01-03','2028-01-03','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-01-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15882,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-01-03','2028-01-03','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-01-03/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15883,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-03','2028-01-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15884,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-01-03','2028-01-03','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-01-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15885,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-04','2028-01-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15886,'Krabbelgruppe in Spöck',NULL,'2028-01-04','2028-01-04','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-01-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15887,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-01-04','2028-01-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-01-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15888,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-01-04','2028-01-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-01-04/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15889,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-01-04','2028-01-04','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-01-04/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15891,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-01-04','2028-01-04','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-01-04/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15892,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-01-05','2028-01-05','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-01-05/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15893,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-01-05','2028-01-05','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-01-05/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15894,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-01-06','2028-01-06','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-01-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15895,'Korallengarde (10–14 Jahre)',NULL,'2028-01-06','2028-01-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15896,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-01-06','2028-01-06','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-01-06/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15897,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-06','2028-01-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15898,'Seesternchengarde (3–6 Jahre)',NULL,'2028-01-06','2028-01-06','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-01-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15899,'Tee- und Spielstube',NULL,'2028-01-06','2028-01-06','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-01-06/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15900,'Teen Girls im GrauBau',NULL,'2028-01-06','2028-01-06','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-01-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15901,'Kreativfreitag im GrauBau',NULL,'2028-01-07','2028-01-07','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-01-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15902,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-01-07','2028-01-07','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-01-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15903,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-07','2028-01-07','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-01-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15904,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-01-08','2028-01-08','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-01-08/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15905,'Eltern-Baby-Café',NULL,'2028-01-10','2028-01-10','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-01-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15906,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-01-10','2028-01-10','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-01-10/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15907,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-10','2028-01-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15908,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-01-10','2028-01-10','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-01-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15909,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-11','2028-01-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15910,'Krabbelgruppe in Spöck',NULL,'2028-01-11','2028-01-11','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-01-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15911,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-01-11','2028-01-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-01-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15912,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-01-11','2028-01-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-01-11/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15913,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-01-11','2028-01-11','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-01-11/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15915,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-01-11','2028-01-11','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-01-11/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15916,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-01-12','2028-01-12','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-01-12/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15917,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-01-12','2028-01-12','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-01-12/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15918,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-01-13','2028-01-13','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-01-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15919,'Korallengarde (10–14 Jahre)',NULL,'2028-01-13','2028-01-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15920,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-01-13','2028-01-13','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-01-13/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15921,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-13','2028-01-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15922,'Seesternchengarde (3–6 Jahre)',NULL,'2028-01-13','2028-01-13','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-01-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15923,'Tee- und Spielstube',NULL,'2028-01-13','2028-01-13','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-01-13/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15924,'Teen Girls im GrauBau',NULL,'2028-01-13','2028-01-13','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-01-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15925,'Kreativfreitag im GrauBau',NULL,'2028-01-14','2028-01-14','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-01-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15926,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-01-14','2028-01-14','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-01-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15927,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-14','2028-01-14','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-01-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15928,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-01-15','2028-01-15','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-01-15/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15929,'Eltern-Baby-Café',NULL,'2028-01-17','2028-01-17','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-01-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15930,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-01-17','2028-01-17','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-01-17/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15931,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-17','2028-01-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15932,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-01-17','2028-01-17','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-01-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15933,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-18','2028-01-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15934,'Krabbelgruppe in Spöck',NULL,'2028-01-18','2028-01-18','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-01-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15935,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-01-18','2028-01-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-01-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15936,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-01-18','2028-01-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-01-18/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15937,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-01-18','2028-01-18','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-01-18/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15939,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-01-18','2028-01-18','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-01-18/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15940,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-01-19','2028-01-19','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-01-19/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15941,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-01-19','2028-01-19','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-01-19/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15942,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-01-20','2028-01-20','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-01-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15943,'Korallengarde (10–14 Jahre)',NULL,'2028-01-20','2028-01-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15944,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-01-20','2028-01-20','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-01-20/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15945,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-20','2028-01-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15946,'Seesternchengarde (3–6 Jahre)',NULL,'2028-01-20','2028-01-20','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-01-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15947,'Tee- und Spielstube',NULL,'2028-01-20','2028-01-20','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-01-20/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15948,'Teen Girls im GrauBau',NULL,'2028-01-20','2028-01-20','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-01-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15949,'Kreativfreitag im GrauBau',NULL,'2028-01-21','2028-01-21','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-01-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15950,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-01-21','2028-01-21','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-01-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15951,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-21','2028-01-21','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-01-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15952,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-01-22','2028-01-22','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-01-22/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15953,'Eltern-Baby-Café',NULL,'2028-01-24','2028-01-24','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-01-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15954,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-01-24','2028-01-24','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-01-24/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15955,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-24','2028-01-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15956,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-01-24','2028-01-24','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-01-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15957,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-25','2028-01-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15958,'Krabbelgruppe in Spöck',NULL,'2028-01-25','2028-01-25','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-01-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15959,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-01-25','2028-01-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-01-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15960,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-01-25','2028-01-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-01-25/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15961,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-01-25','2028-01-25','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-01-25/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15963,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-01-25','2028-01-25','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-01-25/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15964,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-01-26','2028-01-26','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-01-26/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15965,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-01-26','2028-01-26','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-01-26/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15966,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-01-27','2028-01-27','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-01-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15967,'Korallengarde (10–14 Jahre)',NULL,'2028-01-27','2028-01-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-01-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15968,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-01-27','2028-01-27','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-01-27/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15969,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-27','2028-01-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15970,'Seesternchengarde (3–6 Jahre)',NULL,'2028-01-27','2028-01-27','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-01-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15971,'Tee- und Spielstube',NULL,'2028-01-27','2028-01-27','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-01-27/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15972,'Teen Girls im GrauBau',NULL,'2028-01-27','2028-01-27','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-01-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15973,'Kreativfreitag im GrauBau',NULL,'2028-01-28','2028-01-28','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-01-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15974,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-01-28','2028-01-28','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-01-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15975,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-01-28','2028-01-28','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-01-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15976,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-01-29','2028-01-29','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-01-29/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15977,'Eltern-Baby-Café',NULL,'2028-01-31','2028-01-31','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-01-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15978,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-01-31','2028-01-31','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-01-31/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15979,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-01-31','2028-01-31','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-01-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15980,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-01-31','2028-01-31','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-01-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15981,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-01','2028-02-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(15982,'Krabbelgruppe in Spöck',NULL,'2028-02-01','2028-02-01','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-02-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15983,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-02-01','2028-02-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-02-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15984,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-02-01','2028-02-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-02-01/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15985,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-02-01','2028-02-01','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-02-01/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15987,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-02-01','2028-02-01','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-02-01/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15988,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-02-02','2028-02-02','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-02-02/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15989,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-02-02','2028-02-02','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-02-02/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15990,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-02-03','2028-02-03','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-02-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15991,'Korallengarde (10–14 Jahre)',NULL,'2028-02-03','2028-02-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15992,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-02-03','2028-02-03','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-02-03/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15993,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-03','2028-02-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15994,'Seesternchengarde (3–6 Jahre)',NULL,'2028-02-03','2028-02-03','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-02-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15995,'Tee- und Spielstube',NULL,'2028-02-03','2028-02-03','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-02-03/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15996,'Teen Girls im GrauBau',NULL,'2028-02-03','2028-02-03','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-02-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15997,'Kreativfreitag im GrauBau',NULL,'2028-02-04','2028-02-04','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-02-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15998,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-02-04','2028-02-04','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-02-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(15999,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-04','2028-02-04','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-02-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16000,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-02-05','2028-02-05','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-02-05/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16001,'Eltern-Baby-Café',NULL,'2028-02-07','2028-02-07','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-02-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16002,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-02-07','2028-02-07','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-02-07/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16003,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-07','2028-02-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16004,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-02-07','2028-02-07','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-02-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16005,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-08','2028-02-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16006,'Krabbelgruppe in Spöck',NULL,'2028-02-08','2028-02-08','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-02-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16007,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-02-08','2028-02-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-02-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16008,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-02-08','2028-02-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-02-08/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16009,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-02-08','2028-02-08','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-02-08/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16011,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-02-08','2028-02-08','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-02-08/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16012,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-02-09','2028-02-09','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-02-09/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16013,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-02-09','2028-02-09','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-02-09/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16014,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-02-10','2028-02-10','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-02-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16015,'Korallengarde (10–14 Jahre)',NULL,'2028-02-10','2028-02-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16016,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-02-10','2028-02-10','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-02-10/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16017,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-10','2028-02-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16018,'Seesternchengarde (3–6 Jahre)',NULL,'2028-02-10','2028-02-10','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-02-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16019,'Tee- und Spielstube',NULL,'2028-02-10','2028-02-10','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-02-10/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16020,'Teen Girls im GrauBau',NULL,'2028-02-10','2028-02-10','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-02-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16021,'Kreativfreitag im GrauBau',NULL,'2028-02-11','2028-02-11','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-02-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16022,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-02-11','2028-02-11','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-02-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16023,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-11','2028-02-11','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-02-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16024,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-02-12','2028-02-12','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-02-12/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16025,'Eltern-Baby-Café',NULL,'2028-02-14','2028-02-14','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-02-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16026,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-02-14','2028-02-14','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-02-14/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16027,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-14','2028-02-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16028,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-02-14','2028-02-14','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-02-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16029,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-15','2028-02-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16030,'Krabbelgruppe in Spöck',NULL,'2028-02-15','2028-02-15','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-02-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16031,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-02-15','2028-02-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-02-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16032,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-02-15','2028-02-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-02-15/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16033,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-02-15','2028-02-15','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-02-15/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16035,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-02-15','2028-02-15','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-02-15/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16036,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-02-16','2028-02-16','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-02-16/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16037,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-02-16','2028-02-16','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-02-16/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16038,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-02-17','2028-02-17','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-02-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16039,'Korallengarde (10–14 Jahre)',NULL,'2028-02-17','2028-02-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16040,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-02-17','2028-02-17','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-02-17/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16041,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-17','2028-02-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16042,'Seesternchengarde (3–6 Jahre)',NULL,'2028-02-17','2028-02-17','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-02-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16043,'Tee- und Spielstube',NULL,'2028-02-17','2028-02-17','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-02-17/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16044,'Teen Girls im GrauBau',NULL,'2028-02-17','2028-02-17','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-02-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16045,'Kreativfreitag im GrauBau',NULL,'2028-02-18','2028-02-18','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-02-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16046,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-02-18','2028-02-18','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-02-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16047,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-18','2028-02-18','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-02-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16048,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-02-19','2028-02-19','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-02-19/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16049,'Eltern-Baby-Café',NULL,'2028-02-21','2028-02-21','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-02-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16050,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-02-21','2028-02-21','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-02-21/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16051,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-21','2028-02-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16052,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-02-21','2028-02-21','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-02-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16053,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-22','2028-02-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16054,'Krabbelgruppe in Spöck',NULL,'2028-02-22','2028-02-22','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-02-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16055,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-02-22','2028-02-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-02-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16056,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-02-22','2028-02-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-02-22/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16057,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-02-22','2028-02-22','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-02-22/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16059,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-02-22','2028-02-22','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-02-22/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16060,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-02-23','2028-02-23','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-02-23/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16061,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-02-23','2028-02-23','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-02-23/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16062,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-02-24','2028-02-24','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-02-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16063,'Korallengarde (10–14 Jahre)',NULL,'2028-02-24','2028-02-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16064,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-02-24','2028-02-24','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-02-24/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16065,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-24','2028-02-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16066,'Seesternchengarde (3–6 Jahre)',NULL,'2028-02-24','2028-02-24','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-02-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16067,'Tee- und Spielstube',NULL,'2028-02-24','2028-02-24','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-02-24/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16068,'Teen Girls im GrauBau',NULL,'2028-02-24','2028-02-24','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-02-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16069,'Kreativfreitag im GrauBau',NULL,'2028-02-25','2028-02-25','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-02-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16070,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-02-25','2028-02-25','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-02-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16071,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-25','2028-02-25','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-02-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16072,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-02-26','2028-02-26','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-02-26/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16073,'Eltern-Baby-Café',NULL,'2028-02-28','2028-02-28','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-02-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16074,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-02-28','2028-02-28','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-02-28/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16075,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-02-28','2028-02-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16076,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-02-28','2028-02-28','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-02-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16077,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-02-29','2028-02-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-02-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16078,'Krabbelgruppe in Spöck',NULL,'2028-02-29','2028-02-29','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-02-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16079,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-02-29','2028-02-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-02-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16080,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-02-29','2028-02-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-02-29/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16081,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-02-29','2028-02-29','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-02-29/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16083,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-02-29','2028-02-29','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-02-29/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16084,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-03-01','2028-03-01','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-03-01/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16085,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-03-01','2028-03-01','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-03-01/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16086,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-03-02','2028-03-02','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-03-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16087,'Korallengarde (10–14 Jahre)',NULL,'2028-03-02','2028-03-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16088,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-03-02','2028-03-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-03-02/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16089,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-02','2028-03-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16090,'Seesternchengarde (3–6 Jahre)',NULL,'2028-03-02','2028-03-02','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-03-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16091,'Tee- und Spielstube',NULL,'2028-03-02','2028-03-02','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-03-02/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16092,'Teen Girls im GrauBau',NULL,'2028-03-02','2028-03-02','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-03-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16093,'Kreativfreitag im GrauBau',NULL,'2028-03-03','2028-03-03','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-03-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16094,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-03-03','2028-03-03','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-03-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16095,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-03','2028-03-03','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-03-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16096,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-03-04','2028-03-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-03-04/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16097,'Eltern-Baby-Café',NULL,'2028-03-06','2028-03-06','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-03-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16098,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-03-06','2028-03-06','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-03-06/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16099,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-06','2028-03-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16100,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-03-06','2028-03-06','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-03-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16101,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-07','2028-03-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16102,'Krabbelgruppe in Spöck',NULL,'2028-03-07','2028-03-07','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-03-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16103,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-03-07','2028-03-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-03-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16104,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-03-07','2028-03-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-03-07/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16105,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-03-07','2028-03-07','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-03-07/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16107,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-03-07','2028-03-07','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-03-07/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16108,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-03-08','2028-03-08','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-03-08/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16109,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-03-08','2028-03-08','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-03-08/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16110,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-03-09','2028-03-09','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-03-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16111,'Korallengarde (10–14 Jahre)',NULL,'2028-03-09','2028-03-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16112,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-03-09','2028-03-09','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-03-09/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16113,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-09','2028-03-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16114,'Seesternchengarde (3–6 Jahre)',NULL,'2028-03-09','2028-03-09','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-03-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16115,'Tee- und Spielstube',NULL,'2028-03-09','2028-03-09','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-03-09/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16116,'Teen Girls im GrauBau',NULL,'2028-03-09','2028-03-09','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-03-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16117,'Kreativfreitag im GrauBau',NULL,'2028-03-10','2028-03-10','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-03-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16118,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-03-10','2028-03-10','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-03-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16119,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-10','2028-03-10','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-03-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16120,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-03-11','2028-03-11','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-03-11/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16121,'Eltern-Baby-Café',NULL,'2028-03-13','2028-03-13','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-03-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16122,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-03-13','2028-03-13','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-03-13/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16123,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-13','2028-03-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16124,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-03-13','2028-03-13','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-03-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16125,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-14','2028-03-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16126,'Krabbelgruppe in Spöck',NULL,'2028-03-14','2028-03-14','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-03-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16127,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-03-14','2028-03-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-03-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16128,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-03-14','2028-03-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-03-14/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16129,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-03-14','2028-03-14','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-03-14/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16131,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-03-14','2028-03-14','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-03-14/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16132,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-03-15','2028-03-15','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-03-15/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16133,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-03-15','2028-03-15','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-03-15/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16134,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-03-16','2028-03-16','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-03-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16135,'Korallengarde (10–14 Jahre)',NULL,'2028-03-16','2028-03-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16136,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-03-16','2028-03-16','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-03-16/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16137,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-16','2028-03-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16138,'Seesternchengarde (3–6 Jahre)',NULL,'2028-03-16','2028-03-16','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-03-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16139,'Tee- und Spielstube',NULL,'2028-03-16','2028-03-16','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-03-16/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16140,'Teen Girls im GrauBau',NULL,'2028-03-16','2028-03-16','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-03-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16141,'Kreativfreitag im GrauBau',NULL,'2028-03-17','2028-03-17','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-03-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16142,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-03-17','2028-03-17','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-03-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16143,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-17','2028-03-17','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-03-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16144,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-03-18','2028-03-18','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-03-18/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16145,'Eltern-Baby-Café',NULL,'2028-03-20','2028-03-20','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-03-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16146,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-03-20','2028-03-20','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-03-20/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16147,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-20','2028-03-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16148,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-03-20','2028-03-20','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-03-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16149,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-21','2028-03-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16150,'Krabbelgruppe in Spöck',NULL,'2028-03-21','2028-03-21','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-03-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16151,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-03-21','2028-03-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-03-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16152,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-03-21','2028-03-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-03-21/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16153,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-03-21','2028-03-21','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-03-21/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16155,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-03-21','2028-03-21','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-03-21/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16156,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-03-22','2028-03-22','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-03-22/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16157,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-03-22','2028-03-22','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-03-22/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16158,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-03-23','2028-03-23','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-03-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16159,'Korallengarde (10–14 Jahre)',NULL,'2028-03-23','2028-03-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16160,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-03-23','2028-03-23','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-03-23/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16161,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-23','2028-03-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16162,'Seesternchengarde (3–6 Jahre)',NULL,'2028-03-23','2028-03-23','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-03-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16163,'Tee- und Spielstube',NULL,'2028-03-23','2028-03-23','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-03-23/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16164,'Teen Girls im GrauBau',NULL,'2028-03-23','2028-03-23','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-03-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16165,'Kreativfreitag im GrauBau',NULL,'2028-03-24','2028-03-24','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-03-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16166,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-03-24','2028-03-24','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-03-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16167,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-24','2028-03-24','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-03-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16168,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-03-25','2028-03-25','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-03-25/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16169,'Eltern-Baby-Café',NULL,'2028-03-27','2028-03-27','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-03-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16170,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-03-27','2028-03-27','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-03-27/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16171,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-27','2028-03-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16172,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-03-27','2028-03-27','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-03-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16173,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-28','2028-03-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16174,'Krabbelgruppe in Spöck',NULL,'2028-03-28','2028-03-28','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-03-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16175,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-03-28','2028-03-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-03-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16176,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-03-28','2028-03-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-03-28/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16177,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-03-28','2028-03-28','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-03-28/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16179,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-03-28','2028-03-28','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-03-28/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16180,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-03-29','2028-03-29','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-03-29/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16181,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-03-29','2028-03-29','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-03-29/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16182,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-03-30','2028-03-30','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-03-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16183,'Korallengarde (10–14 Jahre)',NULL,'2028-03-30','2028-03-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-03-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16184,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-03-30','2028-03-30','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-03-30/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16185,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-03-30','2028-03-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-03-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16186,'Seesternchengarde (3–6 Jahre)',NULL,'2028-03-30','2028-03-30','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-03-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16187,'Tee- und Spielstube',NULL,'2028-03-30','2028-03-30','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-03-30/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16188,'Teen Girls im GrauBau',NULL,'2028-03-30','2028-03-30','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-03-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16189,'Kreativfreitag im GrauBau',NULL,'2028-03-31','2028-03-31','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-03-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16190,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-03-31','2028-03-31','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-03-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16191,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-03-31','2028-03-31','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-03-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16192,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-04-01','2028-04-01','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-04-01/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16193,'Eltern-Baby-Café',NULL,'2028-04-03','2028-04-03','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-04-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16194,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-04-03','2028-04-03','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-04-03/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16195,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-03','2028-04-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16196,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-04-03','2028-04-03','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-04-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16197,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-04','2028-04-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16198,'Krabbelgruppe in Spöck',NULL,'2028-04-04','2028-04-04','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-04-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16199,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-04-04','2028-04-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-04-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16200,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-04-04','2028-04-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-04-04/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16201,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-04-04','2028-04-04','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-04-04/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16203,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-04-04','2028-04-04','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-04-04/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16204,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-04-05','2028-04-05','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-04-05/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16205,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-04-05','2028-04-05','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-04-05/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16206,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-04-06','2028-04-06','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-04-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16207,'Korallengarde (10–14 Jahre)',NULL,'2028-04-06','2028-04-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16208,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-04-06','2028-04-06','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-04-06/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16209,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-06','2028-04-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16210,'Seesternchengarde (3–6 Jahre)',NULL,'2028-04-06','2028-04-06','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-04-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16211,'Tee- und Spielstube',NULL,'2028-04-06','2028-04-06','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-04-06/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16212,'Teen Girls im GrauBau',NULL,'2028-04-06','2028-04-06','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-04-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16213,'Kreativfreitag im GrauBau',NULL,'2028-04-07','2028-04-07','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-04-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16214,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-04-07','2028-04-07','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-04-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16215,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-07','2028-04-07','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-04-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16216,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-04-08','2028-04-08','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-04-08/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16217,'Eltern-Baby-Café',NULL,'2028-04-10','2028-04-10','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-04-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16218,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-04-10','2028-04-10','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-04-10/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16219,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-10','2028-04-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16220,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-04-10','2028-04-10','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-04-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16221,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-11','2028-04-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16222,'Krabbelgruppe in Spöck',NULL,'2028-04-11','2028-04-11','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-04-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16223,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-04-11','2028-04-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-04-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16224,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-04-11','2028-04-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-04-11/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16225,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-04-11','2028-04-11','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-04-11/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16227,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-04-11','2028-04-11','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-04-11/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16228,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-04-12','2028-04-12','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-04-12/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16229,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-04-12','2028-04-12','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-04-12/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16230,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-04-13','2028-04-13','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-04-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16231,'Korallengarde (10–14 Jahre)',NULL,'2028-04-13','2028-04-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16232,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-04-13','2028-04-13','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-04-13/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16233,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-13','2028-04-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16234,'Seesternchengarde (3–6 Jahre)',NULL,'2028-04-13','2028-04-13','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-04-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16235,'Tee- und Spielstube',NULL,'2028-04-13','2028-04-13','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-04-13/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16236,'Teen Girls im GrauBau',NULL,'2028-04-13','2028-04-13','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-04-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16237,'Kreativfreitag im GrauBau',NULL,'2028-04-14','2028-04-14','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-04-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16238,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-04-14','2028-04-14','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-04-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16239,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-14','2028-04-14','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-04-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16240,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-04-15','2028-04-15','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-04-15/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16241,'Eltern-Baby-Café',NULL,'2028-04-17','2028-04-17','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-04-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16242,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-04-17','2028-04-17','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-04-17/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16243,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-17','2028-04-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16244,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-04-17','2028-04-17','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-04-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16245,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-18','2028-04-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16246,'Krabbelgruppe in Spöck',NULL,'2028-04-18','2028-04-18','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-04-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16247,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-04-18','2028-04-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-04-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16248,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-04-18','2028-04-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-04-18/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16249,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-04-18','2028-04-18','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-04-18/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16251,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-04-18','2028-04-18','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-04-18/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16252,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-04-19','2028-04-19','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-04-19/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16253,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-04-19','2028-04-19','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-04-19/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16254,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-04-20','2028-04-20','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-04-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16255,'Korallengarde (10–14 Jahre)',NULL,'2028-04-20','2028-04-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16256,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-04-20','2028-04-20','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-04-20/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16257,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-20','2028-04-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16258,'Seesternchengarde (3–6 Jahre)',NULL,'2028-04-20','2028-04-20','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-04-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16259,'Tee- und Spielstube',NULL,'2028-04-20','2028-04-20','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-04-20/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16260,'Teen Girls im GrauBau',NULL,'2028-04-20','2028-04-20','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-04-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16261,'Kreativfreitag im GrauBau',NULL,'2028-04-21','2028-04-21','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-04-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16262,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-04-21','2028-04-21','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-04-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16263,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-21','2028-04-21','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-04-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16264,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-04-22','2028-04-22','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-04-22/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16265,'Eltern-Baby-Café',NULL,'2028-04-24','2028-04-24','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-04-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16266,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-04-24','2028-04-24','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-04-24/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16267,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-24','2028-04-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16268,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-04-24','2028-04-24','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-04-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16269,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-25','2028-04-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16270,'Krabbelgruppe in Spöck',NULL,'2028-04-25','2028-04-25','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-04-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16271,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-04-25','2028-04-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-04-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16272,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-04-25','2028-04-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-04-25/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16273,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-04-25','2028-04-25','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-04-25/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16275,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-04-25','2028-04-25','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-04-25/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16276,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-04-26','2028-04-26','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-04-26/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16277,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-04-26','2028-04-26','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-04-26/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16278,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-04-27','2028-04-27','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-04-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16279,'Korallengarde (10–14 Jahre)',NULL,'2028-04-27','2028-04-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-04-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16280,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-04-27','2028-04-27','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-04-27/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16281,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-04-27','2028-04-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-04-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16282,'Seesternchengarde (3–6 Jahre)',NULL,'2028-04-27','2028-04-27','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-04-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16283,'Tee- und Spielstube',NULL,'2028-04-27','2028-04-27','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-04-27/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16284,'Teen Girls im GrauBau',NULL,'2028-04-27','2028-04-27','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-04-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16285,'Kreativfreitag im GrauBau',NULL,'2028-04-28','2028-04-28','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-04-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16286,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-04-28','2028-04-28','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-04-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16287,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-04-28','2028-04-28','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-04-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16288,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-04-29','2028-04-29','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-04-29/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16289,'Eltern-Baby-Café',NULL,'2028-05-01','2028-05-01','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-05-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16290,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-05-01','2028-05-01','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-05-01/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16291,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-01','2028-05-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16292,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-05-01','2028-05-01','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-05-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16293,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-02','2028-05-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16294,'Krabbelgruppe in Spöck',NULL,'2028-05-02','2028-05-02','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-05-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16295,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-05-02','2028-05-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-05-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16296,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-05-02','2028-05-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-05-02/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16297,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-05-02','2028-05-02','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-05-02/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16299,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-05-02','2028-05-02','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-05-02/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16300,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-05-03','2028-05-03','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-05-03/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16301,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-05-03','2028-05-03','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-05-03/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16302,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-05-04','2028-05-04','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-05-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16303,'Korallengarde (10–14 Jahre)',NULL,'2028-05-04','2028-05-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16304,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-05-04','2028-05-04','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-05-04/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16305,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-04','2028-05-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16306,'Seesternchengarde (3–6 Jahre)',NULL,'2028-05-04','2028-05-04','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-05-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16307,'Tee- und Spielstube',NULL,'2028-05-04','2028-05-04','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-05-04/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16308,'Teen Girls im GrauBau',NULL,'2028-05-04','2028-05-04','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-05-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16309,'Kreativfreitag im GrauBau',NULL,'2028-05-05','2028-05-05','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-05-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16310,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-05-05','2028-05-05','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-05-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16311,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-05','2028-05-05','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-05-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16312,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-05-06','2028-05-06','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-05-06/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16313,'Eltern-Baby-Café',NULL,'2028-05-08','2028-05-08','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-05-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16314,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-05-08','2028-05-08','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-05-08/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16315,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-08','2028-05-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16316,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-05-08','2028-05-08','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-05-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16317,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-09','2028-05-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16318,'Krabbelgruppe in Spöck',NULL,'2028-05-09','2028-05-09','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-05-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16319,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-05-09','2028-05-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-05-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16320,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-05-09','2028-05-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-05-09/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16321,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-05-09','2028-05-09','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-05-09/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16323,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-05-09','2028-05-09','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-05-09/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16324,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-05-10','2028-05-10','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-05-10/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16325,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-05-10','2028-05-10','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-05-10/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16326,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-05-11','2028-05-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-05-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16327,'Korallengarde (10–14 Jahre)',NULL,'2028-05-11','2028-05-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16328,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-05-11','2028-05-11','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-05-11/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16329,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-11','2028-05-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16330,'Seesternchengarde (3–6 Jahre)',NULL,'2028-05-11','2028-05-11','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-05-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16331,'Tee- und Spielstube',NULL,'2028-05-11','2028-05-11','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-05-11/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16332,'Teen Girls im GrauBau',NULL,'2028-05-11','2028-05-11','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-05-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16333,'Kreativfreitag im GrauBau',NULL,'2028-05-12','2028-05-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-05-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16334,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-05-12','2028-05-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-05-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16335,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-12','2028-05-12','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-05-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16336,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-05-13','2028-05-13','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-05-13/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16337,'Eltern-Baby-Café',NULL,'2028-05-15','2028-05-15','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-05-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16338,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-05-15','2028-05-15','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-05-15/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16339,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-15','2028-05-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16340,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-05-15','2028-05-15','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-05-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16341,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-16','2028-05-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16342,'Krabbelgruppe in Spöck',NULL,'2028-05-16','2028-05-16','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-05-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16343,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-05-16','2028-05-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-05-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16344,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-05-16','2028-05-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-05-16/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16345,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-05-16','2028-05-16','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-05-16/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16347,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-05-16','2028-05-16','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-05-16/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16348,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-05-17','2028-05-17','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-05-17/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16349,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-05-17','2028-05-17','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-05-17/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16350,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-05-18','2028-05-18','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-05-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16351,'Korallengarde (10–14 Jahre)',NULL,'2028-05-18','2028-05-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16352,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-05-18','2028-05-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-05-18/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16353,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-18','2028-05-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16354,'Seesternchengarde (3–6 Jahre)',NULL,'2028-05-18','2028-05-18','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-05-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16355,'Tee- und Spielstube',NULL,'2028-05-18','2028-05-18','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-05-18/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16356,'Teen Girls im GrauBau',NULL,'2028-05-18','2028-05-18','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-05-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16357,'Kreativfreitag im GrauBau',NULL,'2028-05-19','2028-05-19','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-05-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16358,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-05-19','2028-05-19','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-05-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16359,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-19','2028-05-19','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-05-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16360,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-05-20','2028-05-20','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-05-20/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16361,'Eltern-Baby-Café',NULL,'2028-05-22','2028-05-22','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-05-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16362,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-05-22','2028-05-22','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-05-22/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16363,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-22','2028-05-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16364,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-05-22','2028-05-22','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-05-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16365,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-23','2028-05-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16366,'Krabbelgruppe in Spöck',NULL,'2028-05-23','2028-05-23','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-05-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16367,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-05-23','2028-05-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-05-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16368,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-05-23','2028-05-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-05-23/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16369,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-05-23','2028-05-23','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-05-23/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16371,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-05-23','2028-05-23','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-05-23/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16372,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-05-24','2028-05-24','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-05-24/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16373,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-05-24','2028-05-24','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-05-24/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16374,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-05-25','2028-05-25','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-05-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16375,'Korallengarde (10–14 Jahre)',NULL,'2028-05-25','2028-05-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16376,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-05-25','2028-05-25','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-05-25/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16377,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-25','2028-05-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16378,'Seesternchengarde (3–6 Jahre)',NULL,'2028-05-25','2028-05-25','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-05-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16379,'Tee- und Spielstube',NULL,'2028-05-25','2028-05-25','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-05-25/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16380,'Teen Girls im GrauBau',NULL,'2028-05-25','2028-05-25','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-05-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16381,'Kreativfreitag im GrauBau',NULL,'2028-05-26','2028-05-26','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-05-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16382,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-05-26','2028-05-26','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-05-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16383,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-26','2028-05-26','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-05-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16384,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-05-27','2028-05-27','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-05-27/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16385,'Eltern-Baby-Café',NULL,'2028-05-29','2028-05-29','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-05-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16386,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-05-29','2028-05-29','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-05-29/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16387,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-05-29','2028-05-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-05-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16388,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-05-29','2028-05-29','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-05-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16389,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-05-30','2028-05-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-05-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16390,'Krabbelgruppe in Spöck',NULL,'2028-05-30','2028-05-30','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-05-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16391,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-05-30','2028-05-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-05-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16392,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-05-30','2028-05-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-05-30/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16393,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-05-30','2028-05-30','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-05-30/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16395,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-05-30','2028-05-30','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-05-30/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16396,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-05-31','2028-05-31','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-05-31/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16397,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-05-31','2028-05-31','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-05-31/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16398,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-06-01','2028-06-01','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-06-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16399,'Korallengarde (10–14 Jahre)',NULL,'2028-06-01','2028-06-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16400,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-06-01','2028-06-01','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-06-01/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16401,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-01','2028-06-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16402,'Seesternchengarde (3–6 Jahre)',NULL,'2028-06-01','2028-06-01','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-06-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16403,'Tee- und Spielstube',NULL,'2028-06-01','2028-06-01','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-06-01/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16404,'Teen Girls im GrauBau',NULL,'2028-06-01','2028-06-01','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-06-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16405,'Kreativfreitag im GrauBau',NULL,'2028-06-02','2028-06-02','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-06-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16406,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-06-02','2028-06-02','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-06-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16407,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-02','2028-06-02','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-06-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16408,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-06-03','2028-06-03','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-06-03/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16409,'Eltern-Baby-Café',NULL,'2028-06-05','2028-06-05','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-06-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16410,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-06-05','2028-06-05','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-06-05/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16411,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-05','2028-06-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16412,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-06-05','2028-06-05','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-06-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16413,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-06','2028-06-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16414,'Krabbelgruppe in Spöck',NULL,'2028-06-06','2028-06-06','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-06-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16415,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-06-06','2028-06-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-06-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16416,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-06-06','2028-06-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-06-06/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16417,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-06-06','2028-06-06','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-06-06/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16419,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-06-06','2028-06-06','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-06-06/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16420,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-06-07','2028-06-07','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-06-07/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16421,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-06-07','2028-06-07','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-06-07/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16422,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-06-08','2028-06-08','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-06-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16423,'Korallengarde (10–14 Jahre)',NULL,'2028-06-08','2028-06-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16424,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-06-08','2028-06-08','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-06-08/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16425,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-08','2028-06-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16426,'Seesternchengarde (3–6 Jahre)',NULL,'2028-06-08','2028-06-08','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-06-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16427,'Tee- und Spielstube',NULL,'2028-06-08','2028-06-08','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-06-08/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16428,'Teen Girls im GrauBau',NULL,'2028-06-08','2028-06-08','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-06-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16429,'Kreativfreitag im GrauBau',NULL,'2028-06-09','2028-06-09','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-06-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16430,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-06-09','2028-06-09','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-06-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16431,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-09','2028-06-09','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-06-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16432,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-06-10','2028-06-10','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-06-10/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16433,'Eltern-Baby-Café',NULL,'2028-06-12','2028-06-12','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-06-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16434,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-06-12','2028-06-12','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-06-12/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16435,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-12','2028-06-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16436,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-06-12','2028-06-12','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-06-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16437,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-13','2028-06-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16438,'Krabbelgruppe in Spöck',NULL,'2028-06-13','2028-06-13','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-06-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16439,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-06-13','2028-06-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-06-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16440,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-06-13','2028-06-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-06-13/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16441,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-06-13','2028-06-13','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-06-13/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16443,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-06-13','2028-06-13','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-06-13/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16444,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-06-14','2028-06-14','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-06-14/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16445,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-06-14','2028-06-14','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-06-14/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16446,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-06-15','2028-06-15','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-06-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16447,'Korallengarde (10–14 Jahre)',NULL,'2028-06-15','2028-06-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16448,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-06-15','2028-06-15','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-06-15/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16449,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-15','2028-06-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16450,'Seesternchengarde (3–6 Jahre)',NULL,'2028-06-15','2028-06-15','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-06-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16451,'Tee- und Spielstube',NULL,'2028-06-15','2028-06-15','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-06-15/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16452,'Teen Girls im GrauBau',NULL,'2028-06-15','2028-06-15','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-06-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16453,'Kreativfreitag im GrauBau',NULL,'2028-06-16','2028-06-16','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-06-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16454,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-06-16','2028-06-16','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-06-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16455,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-16','2028-06-16','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-06-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16456,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-06-17','2028-06-17','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-06-17/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16457,'Eltern-Baby-Café',NULL,'2028-06-19','2028-06-19','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-06-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16458,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-06-19','2028-06-19','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-06-19/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16459,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-19','2028-06-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16460,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-06-19','2028-06-19','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-06-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16461,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-20','2028-06-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16462,'Krabbelgruppe in Spöck',NULL,'2028-06-20','2028-06-20','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-06-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16463,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-06-20','2028-06-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-06-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16464,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-06-20','2028-06-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-06-20/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16465,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-06-20','2028-06-20','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-06-20/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16467,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-06-20','2028-06-20','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-06-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16468,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-06-21','2028-06-21','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-06-21/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16469,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-06-21','2028-06-21','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-06-21/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16470,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-06-22','2028-06-22','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-06-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16471,'Korallengarde (10–14 Jahre)',NULL,'2028-06-22','2028-06-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16472,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-06-22','2028-06-22','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-06-22/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16473,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-22','2028-06-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16474,'Seesternchengarde (3–6 Jahre)',NULL,'2028-06-22','2028-06-22','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-06-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16475,'Tee- und Spielstube',NULL,'2028-06-22','2028-06-22','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-06-22/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16476,'Teen Girls im GrauBau',NULL,'2028-06-22','2028-06-22','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-06-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16477,'Kreativfreitag im GrauBau',NULL,'2028-06-23','2028-06-23','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-06-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16478,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-06-23','2028-06-23','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-06-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16479,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-23','2028-06-23','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-06-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16480,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-06-24','2028-06-24','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-06-24/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16481,'Eltern-Baby-Café',NULL,'2028-06-26','2028-06-26','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-06-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16482,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-06-26','2028-06-26','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-06-26/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16483,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-26','2028-06-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16484,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-06-26','2028-06-26','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-06-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16485,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-27','2028-06-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16486,'Krabbelgruppe in Spöck',NULL,'2028-06-27','2028-06-27','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-06-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16487,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-06-27','2028-06-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-06-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16488,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-06-27','2028-06-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-06-27/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16489,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-06-27','2028-06-27','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-06-27/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16491,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-06-27','2028-06-27','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-06-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16492,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-06-28','2028-06-28','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-06-28/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16493,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-06-28','2028-06-28','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-06-28/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16494,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-06-29','2028-06-29','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-06-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16495,'Korallengarde (10–14 Jahre)',NULL,'2028-06-29','2028-06-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-06-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16496,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-06-29','2028-06-29','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-06-29/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16497,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-06-29','2028-06-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-06-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16498,'Seesternchengarde (3–6 Jahre)',NULL,'2028-06-29','2028-06-29','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-06-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16499,'Tee- und Spielstube',NULL,'2028-06-29','2028-06-29','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-06-29/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16500,'Teen Girls im GrauBau',NULL,'2028-06-29','2028-06-29','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-06-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16501,'Kreativfreitag im GrauBau',NULL,'2028-06-30','2028-06-30','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-06-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16502,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-06-30','2028-06-30','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-06-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16503,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-06-30','2028-06-30','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-06-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16504,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-07-01','2028-07-01','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-07-01/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16505,'Eltern-Baby-Café',NULL,'2028-07-03','2028-07-03','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-07-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16506,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-07-03','2028-07-03','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-07-03/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16507,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-03','2028-07-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16508,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-07-03','2028-07-03','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-07-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16509,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-04','2028-07-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16510,'Krabbelgruppe in Spöck',NULL,'2028-07-04','2028-07-04','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-07-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16511,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-07-04','2028-07-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-07-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16512,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-07-04','2028-07-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-07-04/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16513,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-07-04','2028-07-04','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-07-04/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16515,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-07-04','2028-07-04','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-07-04/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16516,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-07-05','2028-07-05','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-07-05/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16517,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-07-05','2028-07-05','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-07-05/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16518,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-07-06','2028-07-06','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-07-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16519,'Korallengarde (10–14 Jahre)',NULL,'2028-07-06','2028-07-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16520,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-07-06','2028-07-06','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-07-06/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16521,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-06','2028-07-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16522,'Seesternchengarde (3–6 Jahre)',NULL,'2028-07-06','2028-07-06','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-07-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16523,'Tee- und Spielstube',NULL,'2028-07-06','2028-07-06','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-07-06/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16524,'Teen Girls im GrauBau',NULL,'2028-07-06','2028-07-06','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-07-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16525,'Kreativfreitag im GrauBau',NULL,'2028-07-07','2028-07-07','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-07-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16526,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-07-07','2028-07-07','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-07-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16527,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-07','2028-07-07','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-07-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16528,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-07-08','2028-07-08','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-07-08/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16529,'Eltern-Baby-Café',NULL,'2028-07-10','2028-07-10','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-07-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16530,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-07-10','2028-07-10','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-07-10/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16531,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-10','2028-07-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16532,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-07-10','2028-07-10','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-07-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16533,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-11','2028-07-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16534,'Krabbelgruppe in Spöck',NULL,'2028-07-11','2028-07-11','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-07-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16535,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-07-11','2028-07-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-07-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16536,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-07-11','2028-07-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-07-11/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16537,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-07-11','2028-07-11','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-07-11/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16539,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-07-11','2028-07-11','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-07-11/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16540,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-07-12','2028-07-12','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-07-12/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16541,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-07-12','2028-07-12','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-07-12/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16542,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-07-13','2028-07-13','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-07-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16543,'Korallengarde (10–14 Jahre)',NULL,'2028-07-13','2028-07-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16544,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-07-13','2028-07-13','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-07-13/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16545,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-13','2028-07-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16546,'Seesternchengarde (3–6 Jahre)',NULL,'2028-07-13','2028-07-13','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-07-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16547,'Tee- und Spielstube',NULL,'2028-07-13','2028-07-13','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-07-13/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16548,'Teen Girls im GrauBau',NULL,'2028-07-13','2028-07-13','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-07-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16549,'Kreativfreitag im GrauBau',NULL,'2028-07-14','2028-07-14','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-07-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16550,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-07-14','2028-07-14','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-07-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16551,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-14','2028-07-14','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-07-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16552,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-07-15','2028-07-15','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-07-15/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16553,'Eltern-Baby-Café',NULL,'2028-07-17','2028-07-17','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-07-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16554,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-07-17','2028-07-17','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-07-17/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16555,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-17','2028-07-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16556,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-07-17','2028-07-17','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-07-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16557,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-18','2028-07-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16558,'Krabbelgruppe in Spöck',NULL,'2028-07-18','2028-07-18','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-07-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16559,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-07-18','2028-07-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-07-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16560,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-07-18','2028-07-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-07-18/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16561,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-07-18','2028-07-18','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-07-18/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16563,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-07-18','2028-07-18','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-07-18/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16564,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-07-19','2028-07-19','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-07-19/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16565,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-07-19','2028-07-19','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-07-19/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16566,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-07-20','2028-07-20','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-07-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16567,'Korallengarde (10–14 Jahre)',NULL,'2028-07-20','2028-07-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16568,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-07-20','2028-07-20','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-07-20/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16569,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-20','2028-07-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16570,'Seesternchengarde (3–6 Jahre)',NULL,'2028-07-20','2028-07-20','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-07-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16571,'Tee- und Spielstube',NULL,'2028-07-20','2028-07-20','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-07-20/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16572,'Teen Girls im GrauBau',NULL,'2028-07-20','2028-07-20','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-07-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16573,'Kreativfreitag im GrauBau',NULL,'2028-07-21','2028-07-21','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-07-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16574,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-07-21','2028-07-21','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-07-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16575,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-21','2028-07-21','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-07-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16576,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-07-22','2028-07-22','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-07-22/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16577,'Eltern-Baby-Café',NULL,'2028-07-24','2028-07-24','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-07-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16578,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-07-24','2028-07-24','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-07-24/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16579,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-24','2028-07-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16580,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-07-24','2028-07-24','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-07-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16581,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-25','2028-07-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16582,'Krabbelgruppe in Spöck',NULL,'2028-07-25','2028-07-25','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-07-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16583,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-07-25','2028-07-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-07-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16584,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-07-25','2028-07-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-07-25/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16585,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-07-25','2028-07-25','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-07-25/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16587,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-07-25','2028-07-25','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-07-25/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16588,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-07-26','2028-07-26','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-07-26/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16589,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-07-26','2028-07-26','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-07-26/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16590,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-07-27','2028-07-27','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-07-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16591,'Korallengarde (10–14 Jahre)',NULL,'2028-07-27','2028-07-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-07-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16592,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-07-27','2028-07-27','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-07-27/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16593,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-27','2028-07-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16594,'Seesternchengarde (3–6 Jahre)',NULL,'2028-07-27','2028-07-27','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-07-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16595,'Tee- und Spielstube',NULL,'2028-07-27','2028-07-27','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-07-27/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16596,'Teen Girls im GrauBau',NULL,'2028-07-27','2028-07-27','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-07-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16597,'Kreativfreitag im GrauBau',NULL,'2028-07-28','2028-07-28','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-07-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16598,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-07-28','2028-07-28','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-07-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16599,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-07-28','2028-07-28','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-07-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16600,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-07-29','2028-07-29','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-07-29/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16601,'Eltern-Baby-Café',NULL,'2028-07-31','2028-07-31','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-07-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16602,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-07-31','2028-07-31','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-07-31/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16603,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-07-31','2028-07-31','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-07-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16604,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-07-31','2028-07-31','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-07-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16605,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-01','2028-08-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16606,'Krabbelgruppe in Spöck',NULL,'2028-08-01','2028-08-01','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-08-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16607,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-08-01','2028-08-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-08-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16608,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-08-01','2028-08-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-08-01/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16609,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-08-01','2028-08-01','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-08-01/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16611,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-08-01','2028-08-01','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-08-01/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16612,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-08-02','2028-08-02','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-08-02/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16613,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-08-02','2028-08-02','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-08-02/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16614,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-08-03','2028-08-03','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-08-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16615,'Korallengarde (10–14 Jahre)',NULL,'2028-08-03','2028-08-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16616,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-08-03','2028-08-03','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-08-03/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16617,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-03','2028-08-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16618,'Seesternchengarde (3–6 Jahre)',NULL,'2028-08-03','2028-08-03','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-08-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16619,'Tee- und Spielstube',NULL,'2028-08-03','2028-08-03','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-08-03/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16620,'Teen Girls im GrauBau',NULL,'2028-08-03','2028-08-03','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-08-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16621,'Kreativfreitag im GrauBau',NULL,'2028-08-04','2028-08-04','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-08-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16622,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-08-04','2028-08-04','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-08-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16623,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-04','2028-08-04','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-08-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16624,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-08-05','2028-08-05','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-08-05/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16625,'Eltern-Baby-Café',NULL,'2028-08-07','2028-08-07','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-08-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16626,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-08-07','2028-08-07','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-08-07/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16627,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-07','2028-08-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16628,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-08-07','2028-08-07','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-08-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16629,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-08','2028-08-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16630,'Krabbelgruppe in Spöck',NULL,'2028-08-08','2028-08-08','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-08-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16631,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-08-08','2028-08-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-08-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16632,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-08-08','2028-08-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-08-08/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16633,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-08-08','2028-08-08','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-08-08/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16635,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-08-08','2028-08-08','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-08-08/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16636,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-08-09','2028-08-09','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-08-09/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16637,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-08-09','2028-08-09','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-08-09/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16638,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-08-10','2028-08-10','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-08-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16639,'Korallengarde (10–14 Jahre)',NULL,'2028-08-10','2028-08-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16640,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-08-10','2028-08-10','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-08-10/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16641,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-10','2028-08-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16642,'Seesternchengarde (3–6 Jahre)',NULL,'2028-08-10','2028-08-10','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-08-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16643,'Tee- und Spielstube',NULL,'2028-08-10','2028-08-10','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-08-10/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16644,'Teen Girls im GrauBau',NULL,'2028-08-10','2028-08-10','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-08-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16645,'Kreativfreitag im GrauBau',NULL,'2028-08-11','2028-08-11','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-08-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16646,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-08-11','2028-08-11','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-08-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16647,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-11','2028-08-11','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-08-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16648,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-08-12','2028-08-12','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-08-12/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16649,'Eltern-Baby-Café',NULL,'2028-08-14','2028-08-14','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-08-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16650,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-08-14','2028-08-14','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-08-14/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16651,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-14','2028-08-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16652,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-08-14','2028-08-14','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-08-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16653,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-15','2028-08-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16654,'Krabbelgruppe in Spöck',NULL,'2028-08-15','2028-08-15','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-08-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16655,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-08-15','2028-08-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-08-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16656,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-08-15','2028-08-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-08-15/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16657,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-08-15','2028-08-15','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-08-15/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16659,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-08-15','2028-08-15','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-08-15/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16660,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-08-16','2028-08-16','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-08-16/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16661,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-08-16','2028-08-16','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-08-16/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16662,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-08-17','2028-08-17','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-08-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16663,'Korallengarde (10–14 Jahre)',NULL,'2028-08-17','2028-08-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16664,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-08-17','2028-08-17','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-08-17/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16665,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-17','2028-08-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16666,'Seesternchengarde (3–6 Jahre)',NULL,'2028-08-17','2028-08-17','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-08-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16667,'Tee- und Spielstube',NULL,'2028-08-17','2028-08-17','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-08-17/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16668,'Teen Girls im GrauBau',NULL,'2028-08-17','2028-08-17','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-08-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16669,'Kreativfreitag im GrauBau',NULL,'2028-08-18','2028-08-18','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-08-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16670,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-08-18','2028-08-18','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-08-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16671,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-18','2028-08-18','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-08-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16672,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-08-19','2028-08-19','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-08-19/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16673,'Eltern-Baby-Café',NULL,'2028-08-21','2028-08-21','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-08-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16674,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-08-21','2028-08-21','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-08-21/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16675,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-21','2028-08-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16676,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-08-21','2028-08-21','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-08-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16677,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-22','2028-08-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16678,'Krabbelgruppe in Spöck',NULL,'2028-08-22','2028-08-22','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-08-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16679,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-08-22','2028-08-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-08-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16680,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-08-22','2028-08-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-08-22/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16681,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-08-22','2028-08-22','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-08-22/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16683,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-08-22','2028-08-22','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-08-22/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16684,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-08-23','2028-08-23','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-08-23/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16685,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-08-23','2028-08-23','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-08-23/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16686,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-08-24','2028-08-24','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-08-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16687,'Korallengarde (10–14 Jahre)',NULL,'2028-08-24','2028-08-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16688,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-08-24','2028-08-24','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-08-24/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16689,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-24','2028-08-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16690,'Seesternchengarde (3–6 Jahre)',NULL,'2028-08-24','2028-08-24','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-08-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16691,'Tee- und Spielstube',NULL,'2028-08-24','2028-08-24','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-08-24/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16692,'Teen Girls im GrauBau',NULL,'2028-08-24','2028-08-24','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-08-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16693,'Kreativfreitag im GrauBau',NULL,'2028-08-25','2028-08-25','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-08-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16694,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-08-25','2028-08-25','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-08-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16695,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-25','2028-08-25','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-08-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16696,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-08-26','2028-08-26','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-08-26/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16697,'Eltern-Baby-Café',NULL,'2028-08-28','2028-08-28','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-08-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16698,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-08-28','2028-08-28','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-08-28/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16699,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-28','2028-08-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16700,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-08-28','2028-08-28','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-08-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16701,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-08-29','2028-08-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16702,'Krabbelgruppe in Spöck',NULL,'2028-08-29','2028-08-29','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-08-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16703,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-08-29','2028-08-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-08-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16704,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-08-29','2028-08-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-08-29/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16705,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-08-29','2028-08-29','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-08-29/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16707,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-08-29','2028-08-29','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-08-29/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16708,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-08-30','2028-08-30','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-08-30/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16709,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-08-30','2028-08-30','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-08-30/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16710,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-08-31','2028-08-31','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-08-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16711,'Korallengarde (10–14 Jahre)',NULL,'2028-08-31','2028-08-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-08-31/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16712,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-08-31','2028-08-31','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-08-31/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16713,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-08-31','2028-08-31','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-08-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16714,'Seesternchengarde (3–6 Jahre)',NULL,'2028-08-31','2028-08-31','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-08-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16715,'Tee- und Spielstube',NULL,'2028-08-31','2028-08-31','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-08-31/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16716,'Teen Girls im GrauBau',NULL,'2028-08-31','2028-08-31','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-08-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16717,'Kreativfreitag im GrauBau',NULL,'2028-09-01','2028-09-01','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16718,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-09-01','2028-09-01','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16719,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-01','2028-09-01','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16720,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-09-02','2028-09-02','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-02/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16721,'Eltern-Baby-Café',NULL,'2028-09-04','2028-09-04','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-09-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16722,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-09-04','2028-09-04','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-09-04/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16723,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-04','2028-09-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16724,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-09-04','2028-09-04','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-09-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16725,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-05','2028-09-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16726,'Krabbelgruppe in Spöck',NULL,'2028-09-05','2028-09-05','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-09-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16727,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-09-05','2028-09-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-09-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16728,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-09-05','2028-09-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-09-05/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16729,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-09-05','2028-09-05','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-09-05/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16731,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-09-05','2028-09-05','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-09-05/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16732,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-09-06','2028-09-06','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-09-06/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16733,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-09-06','2028-09-06','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-09-06/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16734,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-09-07','2028-09-07','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-09-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16735,'Korallengarde (10–14 Jahre)',NULL,'2028-09-07','2028-09-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16736,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-09-07','2028-09-07','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-09-07/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16737,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-07','2028-09-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16738,'Seesternchengarde (3–6 Jahre)',NULL,'2028-09-07','2028-09-07','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-09-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16739,'Tee- und Spielstube',NULL,'2028-09-07','2028-09-07','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-09-07/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16740,'Teen Girls im GrauBau',NULL,'2028-09-07','2028-09-07','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-09-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16741,'Kreativfreitag im GrauBau',NULL,'2028-09-08','2028-09-08','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16742,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-09-08','2028-09-08','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16743,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-08','2028-09-08','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16744,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-09-09','2028-09-09','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-09/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16745,'Eltern-Baby-Café',NULL,'2028-09-11','2028-09-11','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-09-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16746,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-09-11','2028-09-11','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-09-11/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16747,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-11','2028-09-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16748,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-09-11','2028-09-11','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-09-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16749,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-12','2028-09-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16750,'Krabbelgruppe in Spöck',NULL,'2028-09-12','2028-09-12','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-09-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16751,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-09-12','2028-09-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-09-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16752,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-09-12','2028-09-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-09-12/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16753,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-09-12','2028-09-12','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-09-12/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16755,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-09-12','2028-09-12','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-09-12/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16756,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-09-13','2028-09-13','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-09-13/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16757,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-09-13','2028-09-13','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-09-13/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16758,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-09-14','2028-09-14','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-09-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16759,'Korallengarde (10–14 Jahre)',NULL,'2028-09-14','2028-09-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16760,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-09-14','2028-09-14','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-09-14/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16761,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-14','2028-09-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16762,'Seesternchengarde (3–6 Jahre)',NULL,'2028-09-14','2028-09-14','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-09-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16763,'Tee- und Spielstube',NULL,'2028-09-14','2028-09-14','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-09-14/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16764,'Teen Girls im GrauBau',NULL,'2028-09-14','2028-09-14','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-09-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16765,'Kreativfreitag im GrauBau',NULL,'2028-09-15','2028-09-15','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16766,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-09-15','2028-09-15','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16767,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-15','2028-09-15','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16768,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-09-16','2028-09-16','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-16/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16769,'Eltern-Baby-Café',NULL,'2028-09-18','2028-09-18','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-09-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16770,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-09-18','2028-09-18','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-09-18/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16771,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-18','2028-09-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16772,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-09-18','2028-09-18','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-09-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16773,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-19','2028-09-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16774,'Krabbelgruppe in Spöck',NULL,'2028-09-19','2028-09-19','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-09-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16775,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-09-19','2028-09-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-09-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16776,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-09-19','2028-09-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-09-19/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16777,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-09-19','2028-09-19','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-09-19/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16779,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-09-19','2028-09-19','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-09-19/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16780,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-09-20','2028-09-20','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-09-20/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16781,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-09-20','2028-09-20','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-09-20/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16782,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-09-21','2028-09-21','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-09-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16783,'Korallengarde (10–14 Jahre)',NULL,'2028-09-21','2028-09-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16784,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-09-21','2028-09-21','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-09-21/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16785,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-21','2028-09-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16786,'Seesternchengarde (3–6 Jahre)',NULL,'2028-09-21','2028-09-21','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-09-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16787,'Tee- und Spielstube',NULL,'2028-09-21','2028-09-21','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-09-21/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16788,'Teen Girls im GrauBau',NULL,'2028-09-21','2028-09-21','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-09-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16789,'Kreativfreitag im GrauBau',NULL,'2028-09-22','2028-09-22','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16790,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-09-22','2028-09-22','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16791,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-22','2028-09-22','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16792,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-09-23','2028-09-23','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-23/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16793,'Eltern-Baby-Café',NULL,'2028-09-25','2028-09-25','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-09-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16794,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-09-25','2028-09-25','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-09-25/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16795,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-25','2028-09-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16796,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-09-25','2028-09-25','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-09-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16797,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-26','2028-09-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16798,'Krabbelgruppe in Spöck',NULL,'2028-09-26','2028-09-26','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-09-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16799,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-09-26','2028-09-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-09-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16800,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-09-26','2028-09-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-09-26/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16801,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-09-26','2028-09-26','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-09-26/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16803,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-09-26','2028-09-26','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-09-26/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16804,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-09-27','2028-09-27','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-09-27/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16805,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-09-27','2028-09-27','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-09-27/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16806,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-09-28','2028-09-28','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-09-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16807,'Korallengarde (10–14 Jahre)',NULL,'2028-09-28','2028-09-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-09-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16808,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-09-28','2028-09-28','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-09-28/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16809,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-09-28','2028-09-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-09-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16810,'Seesternchengarde (3–6 Jahre)',NULL,'2028-09-28','2028-09-28','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-09-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16811,'Tee- und Spielstube',NULL,'2028-09-28','2028-09-28','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-09-28/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16812,'Teen Girls im GrauBau',NULL,'2028-09-28','2028-09-28','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-09-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16813,'Kreativfreitag im GrauBau',NULL,'2028-09-29','2028-09-29','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-09-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16814,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-09-29','2028-09-29','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-09-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16815,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-09-29','2028-09-29','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-09-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16816,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-09-30','2028-09-30','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-09-30/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16817,'Eltern-Baby-Café',NULL,'2028-10-02','2028-10-02','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16818,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-10-02','2028-10-02','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-02/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16819,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-02','2028-10-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16820,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-10-02','2028-10-02','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16821,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-03','2028-10-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16822,'Krabbelgruppe in Spöck',NULL,'2028-10-03','2028-10-03','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16823,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-10-03','2028-10-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16824,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-10-03','2028-10-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-03/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16825,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-10-03','2028-10-03','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-03/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16827,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-10-03','2028-10-03','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-03/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16828,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-10-04','2028-10-04','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-04/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16829,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-10-04','2028-10-04','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-04/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16830,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-10-05','2028-10-05','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16831,'Korallengarde (10–14 Jahre)',NULL,'2028-10-05','2028-10-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16832,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-10-05','2028-10-05','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-05/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16833,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-05','2028-10-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16834,'Seesternchengarde (3–6 Jahre)',NULL,'2028-10-05','2028-10-05','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16835,'Tee- und Spielstube',NULL,'2028-10-05','2028-10-05','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-05/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16836,'Teen Girls im GrauBau',NULL,'2028-10-05','2028-10-05','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16837,'Kreativfreitag im GrauBau',NULL,'2028-10-06','2028-10-06','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16838,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-10-06','2028-10-06','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16839,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-06','2028-10-06','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16840,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-10-07','2028-10-07','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-07/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16841,'Eltern-Baby-Café',NULL,'2028-10-09','2028-10-09','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16842,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-10-09','2028-10-09','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-09/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16843,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-09','2028-10-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16844,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-10-09','2028-10-09','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16845,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-10','2028-10-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16846,'Krabbelgruppe in Spöck',NULL,'2028-10-10','2028-10-10','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16847,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-10-10','2028-10-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16848,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-10-10','2028-10-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-10/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16849,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-10-10','2028-10-10','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-10/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16851,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-10-10','2028-10-10','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-10/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16852,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-10-11','2028-10-11','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-11/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16853,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-10-11','2028-10-11','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-11/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16854,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-10-12','2028-10-12','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16855,'Korallengarde (10–14 Jahre)',NULL,'2028-10-12','2028-10-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16856,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-10-12','2028-10-12','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-12/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16857,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-12','2028-10-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16858,'Seesternchengarde (3–6 Jahre)',NULL,'2028-10-12','2028-10-12','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16859,'Tee- und Spielstube',NULL,'2028-10-12','2028-10-12','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-12/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16860,'Teen Girls im GrauBau',NULL,'2028-10-12','2028-10-12','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16861,'Kreativfreitag im GrauBau',NULL,'2028-10-13','2028-10-13','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16862,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-10-13','2028-10-13','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16863,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-13','2028-10-13','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16864,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-10-14','2028-10-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-14/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16865,'Eltern-Baby-Café',NULL,'2028-10-16','2028-10-16','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16866,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-10-16','2028-10-16','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-16/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16867,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-16','2028-10-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16868,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-10-16','2028-10-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16869,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-17','2028-10-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16870,'Krabbelgruppe in Spöck',NULL,'2028-10-17','2028-10-17','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16871,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-10-17','2028-10-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16872,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-10-17','2028-10-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-17/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16873,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-10-17','2028-10-17','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-17/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16875,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-10-17','2028-10-17','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-17/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16876,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-10-18','2028-10-18','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-18/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16877,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-10-18','2028-10-18','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-18/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16878,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-10-19','2028-10-19','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16879,'Korallengarde (10–14 Jahre)',NULL,'2028-10-19','2028-10-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16880,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-10-19','2028-10-19','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-19/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16881,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-19','2028-10-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16882,'Seesternchengarde (3–6 Jahre)',NULL,'2028-10-19','2028-10-19','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16883,'Tee- und Spielstube',NULL,'2028-10-19','2028-10-19','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-19/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16884,'Teen Girls im GrauBau',NULL,'2028-10-19','2028-10-19','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16885,'Kreativfreitag im GrauBau',NULL,'2028-10-20','2028-10-20','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16886,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-10-20','2028-10-20','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16887,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-20','2028-10-20','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16888,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-10-21','2028-10-21','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-21/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16889,'Eltern-Baby-Café',NULL,'2028-10-23','2028-10-23','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16890,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-10-23','2028-10-23','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-23/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16891,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-23','2028-10-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16892,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-10-23','2028-10-23','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16893,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-24','2028-10-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16894,'Krabbelgruppe in Spöck',NULL,'2028-10-24','2028-10-24','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16895,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-10-24','2028-10-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16896,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-10-24','2028-10-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-24/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16897,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-10-24','2028-10-24','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-24/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16899,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-10-24','2028-10-24','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-24/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16900,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-10-25','2028-10-25','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-10-25/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16901,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-10-25','2028-10-25','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-10-25/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16902,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-10-26','2028-10-26','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-10-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16903,'Korallengarde (10–14 Jahre)',NULL,'2028-10-26','2028-10-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16904,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-10-26','2028-10-26','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-10-26/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16905,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-26','2028-10-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16906,'Seesternchengarde (3–6 Jahre)',NULL,'2028-10-26','2028-10-26','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-10-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16907,'Tee- und Spielstube',NULL,'2028-10-26','2028-10-26','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-10-26/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16908,'Teen Girls im GrauBau',NULL,'2028-10-26','2028-10-26','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-10-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16909,'Kreativfreitag im GrauBau',NULL,'2028-10-27','2028-10-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-10-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16910,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-10-27','2028-10-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-10-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16911,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-27','2028-10-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-10-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16912,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-10-28','2028-10-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-10-28/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16913,'Eltern-Baby-Café',NULL,'2028-10-30','2028-10-30','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-10-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16914,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-10-30','2028-10-30','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-10-30/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16915,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-10-30','2028-10-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-10-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16916,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-10-30','2028-10-30','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-10-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16917,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-10-31','2028-10-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-10-31/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16918,'Krabbelgruppe in Spöck',NULL,'2028-10-31','2028-10-31','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-10-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16919,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-10-31','2028-10-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-10-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16920,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-10-31','2028-10-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-10-31/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16921,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-10-31','2028-10-31','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-10-31/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16923,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-10-31','2028-10-31','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-10-31/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16924,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-11-01','2028-11-01','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-11-01/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16925,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-11-01','2028-11-01','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-11-01/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16926,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-11-02','2028-11-02','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-11-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16927,'Korallengarde (10–14 Jahre)',NULL,'2028-11-02','2028-11-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16928,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-11-02','2028-11-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-11-02/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16929,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-02','2028-11-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16930,'Seesternchengarde (3–6 Jahre)',NULL,'2028-11-02','2028-11-02','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-11-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16931,'Tee- und Spielstube',NULL,'2028-11-02','2028-11-02','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-11-02/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16932,'Teen Girls im GrauBau',NULL,'2028-11-02','2028-11-02','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-11-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16933,'Kreativfreitag im GrauBau',NULL,'2028-11-03','2028-11-03','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-11-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16934,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-11-03','2028-11-03','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-11-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16935,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-03','2028-11-03','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-11-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16936,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-11-04','2028-11-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-11-04/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16937,'Eltern-Baby-Café',NULL,'2028-11-06','2028-11-06','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-11-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16938,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-11-06','2028-11-06','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-11-06/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16939,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-06','2028-11-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16940,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-11-06','2028-11-06','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-11-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16941,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-07','2028-11-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16942,'Krabbelgruppe in Spöck',NULL,'2028-11-07','2028-11-07','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-11-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16943,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-11-07','2028-11-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-11-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16944,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-11-07','2028-11-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-11-07/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16945,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-11-07','2028-11-07','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-11-07/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16947,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-11-07','2028-11-07','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-11-07/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16948,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-11-08','2028-11-08','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-11-08/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16949,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-11-08','2028-11-08','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-11-08/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16950,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-11-09','2028-11-09','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-11-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16951,'Korallengarde (10–14 Jahre)',NULL,'2028-11-09','2028-11-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16952,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-11-09','2028-11-09','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-11-09/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16953,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-09','2028-11-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16954,'Seesternchengarde (3–6 Jahre)',NULL,'2028-11-09','2028-11-09','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-11-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16955,'Tee- und Spielstube',NULL,'2028-11-09','2028-11-09','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-11-09/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16956,'Teen Girls im GrauBau',NULL,'2028-11-09','2028-11-09','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-11-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16957,'Kreativfreitag im GrauBau',NULL,'2028-11-10','2028-11-10','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-11-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16958,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-11-10','2028-11-10','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-11-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16959,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-10','2028-11-10','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-11-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16960,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-11-11','2028-11-11','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-11-11/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16961,'Eltern-Baby-Café',NULL,'2028-11-13','2028-11-13','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-11-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16962,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-11-13','2028-11-13','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-11-13/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16963,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-13','2028-11-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16964,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-11-13','2028-11-13','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-11-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16965,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-14','2028-11-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16966,'Krabbelgruppe in Spöck',NULL,'2028-11-14','2028-11-14','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-11-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16967,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-11-14','2028-11-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-11-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16968,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-11-14','2028-11-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-11-14/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16969,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-11-14','2028-11-14','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-11-14/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16971,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-11-14','2028-11-14','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-11-14/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16972,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-11-15','2028-11-15','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-11-15/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16973,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-11-15','2028-11-15','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-11-15/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16974,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-11-16','2028-11-16','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-11-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16975,'Korallengarde (10–14 Jahre)',NULL,'2028-11-16','2028-11-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16976,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-11-16','2028-11-16','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-11-16/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16977,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-16','2028-11-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16978,'Seesternchengarde (3–6 Jahre)',NULL,'2028-11-16','2028-11-16','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-11-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16979,'Tee- und Spielstube',NULL,'2028-11-16','2028-11-16','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-11-16/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16980,'Teen Girls im GrauBau',NULL,'2028-11-16','2028-11-16','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-11-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16981,'Kreativfreitag im GrauBau',NULL,'2028-11-17','2028-11-17','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-11-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16982,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-11-17','2028-11-17','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-11-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16983,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-17','2028-11-17','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-11-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16984,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-11-18','2028-11-18','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-11-18/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16985,'Eltern-Baby-Café',NULL,'2028-11-20','2028-11-20','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-11-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16986,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-11-20','2028-11-20','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-11-20/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16987,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-20','2028-11-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16988,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-11-20','2028-11-20','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-11-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16989,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-21','2028-11-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(16990,'Krabbelgruppe in Spöck',NULL,'2028-11-21','2028-11-21','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-11-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16991,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-11-21','2028-11-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-11-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16992,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-11-21','2028-11-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-11-21/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16993,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-11-21','2028-11-21','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-11-21/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16995,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-11-21','2028-11-21','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-11-21/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16996,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-11-22','2028-11-22','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-11-22/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16997,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-11-22','2028-11-22','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-11-22/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16998,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-11-23','2028-11-23','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-11-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(16999,'Korallengarde (10–14 Jahre)',NULL,'2028-11-23','2028-11-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17000,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-11-23','2028-11-23','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-11-23/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17001,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-23','2028-11-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17002,'Seesternchengarde (3–6 Jahre)',NULL,'2028-11-23','2028-11-23','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-11-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17003,'Tee- und Spielstube',NULL,'2028-11-23','2028-11-23','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-11-23/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17004,'Teen Girls im GrauBau',NULL,'2028-11-23','2028-11-23','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-11-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17005,'Kreativfreitag im GrauBau',NULL,'2028-11-24','2028-11-24','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-11-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17006,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-11-24','2028-11-24','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-11-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17007,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-24','2028-11-24','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-11-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17008,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-11-25','2028-11-25','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-11-25/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17009,'Eltern-Baby-Café',NULL,'2028-11-27','2028-11-27','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-11-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17010,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-11-27','2028-11-27','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-11-27/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17011,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-27','2028-11-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17012,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-11-27','2028-11-27','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-11-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17013,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-11-28','2028-11-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17014,'Krabbelgruppe in Spöck',NULL,'2028-11-28','2028-11-28','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-11-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17015,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-11-28','2028-11-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-11-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17016,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-11-28','2028-11-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-11-28/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17017,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-11-28','2028-11-28','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-11-28/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17019,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-11-28','2028-11-28','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-11-28/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17020,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-11-29','2028-11-29','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-11-29/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17021,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-11-29','2028-11-29','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-11-29/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17022,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-11-30','2028-11-30','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-11-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17023,'Korallengarde (10–14 Jahre)',NULL,'2028-11-30','2028-11-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-11-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17024,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-11-30','2028-11-30','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-11-30/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17025,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-11-30','2028-11-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-11-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17026,'Seesternchengarde (3–6 Jahre)',NULL,'2028-11-30','2028-11-30','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-11-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17027,'Tee- und Spielstube',NULL,'2028-11-30','2028-11-30','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-11-30/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17028,'Teen Girls im GrauBau',NULL,'2028-11-30','2028-11-30','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-11-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17029,'Kreativfreitag im GrauBau',NULL,'2028-12-01','2028-12-01','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-12-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17030,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-12-01','2028-12-01','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-12-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17031,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-01','2028-12-01','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-12-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17032,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-12-02','2028-12-02','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-12-02/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17033,'Eltern-Baby-Café',NULL,'2028-12-04','2028-12-04','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-12-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17034,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-12-04','2028-12-04','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-12-04/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17035,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-04','2028-12-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17036,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-12-04','2028-12-04','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-12-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17037,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-05','2028-12-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17038,'Krabbelgruppe in Spöck',NULL,'2028-12-05','2028-12-05','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-12-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17039,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-12-05','2028-12-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-12-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17040,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-12-05','2028-12-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-12-05/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17041,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-12-05','2028-12-05','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-12-05/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17043,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-12-05','2028-12-05','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-12-05/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17044,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-12-06','2028-12-06','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-12-06/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17045,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-12-06','2028-12-06','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-12-06/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17046,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-12-07','2028-12-07','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-12-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17047,'Korallengarde (10–14 Jahre)',NULL,'2028-12-07','2028-12-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17048,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-12-07','2028-12-07','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-12-07/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17049,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-07','2028-12-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17050,'Seesternchengarde (3–6 Jahre)',NULL,'2028-12-07','2028-12-07','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-12-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17051,'Tee- und Spielstube',NULL,'2028-12-07','2028-12-07','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-12-07/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17052,'Teen Girls im GrauBau',NULL,'2028-12-07','2028-12-07','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-12-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17053,'Kreativfreitag im GrauBau',NULL,'2028-12-08','2028-12-08','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-12-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17054,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-12-08','2028-12-08','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-12-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17055,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-08','2028-12-08','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-12-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17056,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-12-09','2028-12-09','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-12-09/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17057,'Eltern-Baby-Café',NULL,'2028-12-11','2028-12-11','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-12-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17058,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-12-11','2028-12-11','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-12-11/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17059,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-11','2028-12-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17060,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-12-11','2028-12-11','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-12-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17061,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-12','2028-12-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17062,'Krabbelgruppe in Spöck',NULL,'2028-12-12','2028-12-12','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-12-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17063,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-12-12','2028-12-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-12-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17064,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-12-12','2028-12-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-12-12/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17065,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-12-12','2028-12-12','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-12-12/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17067,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-12-12','2028-12-12','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-12-12/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17068,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-12-13','2028-12-13','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-12-13/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17069,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-12-13','2028-12-13','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-12-13/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17070,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-12-14','2028-12-14','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-12-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17071,'Korallengarde (10–14 Jahre)',NULL,'2028-12-14','2028-12-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17072,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-12-14','2028-12-14','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-12-14/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17073,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-14','2028-12-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17074,'Seesternchengarde (3–6 Jahre)',NULL,'2028-12-14','2028-12-14','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-12-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17075,'Tee- und Spielstube',NULL,'2028-12-14','2028-12-14','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-12-14/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17076,'Teen Girls im GrauBau',NULL,'2028-12-14','2028-12-14','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-12-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17077,'Kreativfreitag im GrauBau',NULL,'2028-12-15','2028-12-15','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-12-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17078,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-12-15','2028-12-15','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-12-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17079,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-15','2028-12-15','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-12-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17080,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-12-16','2028-12-16','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-12-16/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17081,'Eltern-Baby-Café',NULL,'2028-12-18','2028-12-18','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-12-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17082,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-12-18','2028-12-18','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-12-18/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17083,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-18','2028-12-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17084,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-12-18','2028-12-18','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-12-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17085,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-19','2028-12-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17086,'Krabbelgruppe in Spöck',NULL,'2028-12-19','2028-12-19','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-12-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17087,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-12-19','2028-12-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-12-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17088,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-12-19','2028-12-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-12-19/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17089,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-12-19','2028-12-19','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-12-19/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17091,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-12-19','2028-12-19','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-12-19/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17092,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-12-20','2028-12-20','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-12-20/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17093,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-12-20','2028-12-20','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-12-20/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17094,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-12-21','2028-12-21','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-12-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17095,'Korallengarde (10–14 Jahre)',NULL,'2028-12-21','2028-12-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17096,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-12-21','2028-12-21','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-12-21/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17097,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-21','2028-12-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17098,'Seesternchengarde (3–6 Jahre)',NULL,'2028-12-21','2028-12-21','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-12-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17099,'Tee- und Spielstube',NULL,'2028-12-21','2028-12-21','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-12-21/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17100,'Teen Girls im GrauBau',NULL,'2028-12-21','2028-12-21','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-12-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17101,'Kreativfreitag im GrauBau',NULL,'2028-12-22','2028-12-22','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-12-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17102,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-12-22','2028-12-22','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-12-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17103,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-22','2028-12-22','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-12-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17104,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-12-23','2028-12-23','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-12-23/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17105,'Eltern-Baby-Café',NULL,'2028-12-25','2028-12-25','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2028-12-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17106,'Kinder- und Jugendtraining – Wilde 13',NULL,'2028-12-25','2028-12-25','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-12-25/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17107,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-25','2028-12-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17108,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2028-12-25','2028-12-25','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-12-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17109,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-26','2028-12-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17110,'Krabbelgruppe in Spöck',NULL,'2028-12-26','2028-12-26','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2028-12-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17111,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2028-12-26','2028-12-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-12-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17112,'Pfadfinder*innengruppe Wölflinge',NULL,'2028-12-26','2028-12-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-12-26/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17113,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2028-12-26','2028-12-26','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-12-26/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17115,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2028-12-26','2028-12-26','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-12-26/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17116,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2028-12-27','2028-12-27','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-12-27/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17117,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2028-12-27','2028-12-27','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-12-27/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17118,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2028-12-28','2028-12-28','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2028-12-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17119,'Korallengarde (10–14 Jahre)',NULL,'2028-12-28','2028-12-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2028-12-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17120,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2028-12-28','2028-12-28','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2028-12-28/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17121,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2028-12-28','2028-12-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-12-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17122,'Seesternchengarde (3–6 Jahre)',NULL,'2028-12-28','2028-12-28','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2028-12-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17123,'Tee- und Spielstube',NULL,'2028-12-28','2028-12-28','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-12-28/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17124,'Teen Girls im GrauBau',NULL,'2028-12-28','2028-12-28','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2028-12-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17125,'Kreativfreitag im GrauBau',NULL,'2028-12-29','2028-12-29','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2028-12-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17126,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2028-12-29','2028-12-29','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-12-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17127,'Seepferdchengarde (6–10 Jahre)',NULL,'2028-12-29','2028-12-29','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2028-12-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17128,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2028-12-30','2028-12-30','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2028-12-30/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17129,'Eltern-Baby-Café',NULL,'2029-01-01','2029-01-01','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-01-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17130,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-01-01','2029-01-01','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-01-01/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17131,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-01','2029-01-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17132,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-01-01','2029-01-01','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-01-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17133,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-02','2029-01-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17134,'Krabbelgruppe in Spöck',NULL,'2029-01-02','2029-01-02','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-01-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17135,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-01-02','2029-01-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-01-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17136,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-01-02','2029-01-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-01-02/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17137,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-01-02','2029-01-02','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-01-02/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17139,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-01-02','2029-01-02','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-01-02/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17140,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-01-03','2029-01-03','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-01-03/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17141,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-01-03','2029-01-03','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-01-03/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17142,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-01-04','2029-01-04','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-01-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17143,'Korallengarde (10–14 Jahre)',NULL,'2029-01-04','2029-01-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17144,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-01-04','2029-01-04','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-01-04/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17145,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-04','2029-01-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17146,'Seesternchengarde (3–6 Jahre)',NULL,'2029-01-04','2029-01-04','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-01-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17147,'Tee- und Spielstube',NULL,'2029-01-04','2029-01-04','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-01-04/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17148,'Teen Girls im GrauBau',NULL,'2029-01-04','2029-01-04','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-01-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17149,'Kreativfreitag im GrauBau',NULL,'2029-01-05','2029-01-05','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-01-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17150,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-01-05','2029-01-05','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-01-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17151,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-05','2029-01-05','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-01-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17152,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-01-06','2029-01-06','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-01-06/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17153,'Eltern-Baby-Café',NULL,'2029-01-08','2029-01-08','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-01-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17154,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-01-08','2029-01-08','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-01-08/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17155,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-08','2029-01-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17156,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-01-08','2029-01-08','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-01-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17157,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-09','2029-01-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17158,'Krabbelgruppe in Spöck',NULL,'2029-01-09','2029-01-09','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-01-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17159,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-01-09','2029-01-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-01-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17160,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-01-09','2029-01-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-01-09/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17161,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-01-09','2029-01-09','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-01-09/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17163,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-01-09','2029-01-09','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-01-09/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17164,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-01-10','2029-01-10','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-01-10/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17165,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-01-10','2029-01-10','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-01-10/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17166,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-01-11','2029-01-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-01-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17167,'Korallengarde (10–14 Jahre)',NULL,'2029-01-11','2029-01-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17168,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-01-11','2029-01-11','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-01-11/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17169,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-11','2029-01-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17170,'Seesternchengarde (3–6 Jahre)',NULL,'2029-01-11','2029-01-11','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-01-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17171,'Tee- und Spielstube',NULL,'2029-01-11','2029-01-11','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-01-11/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17172,'Teen Girls im GrauBau',NULL,'2029-01-11','2029-01-11','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-01-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17173,'Kreativfreitag im GrauBau',NULL,'2029-01-12','2029-01-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-01-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17174,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-01-12','2029-01-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-01-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17175,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-12','2029-01-12','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-01-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17176,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-01-13','2029-01-13','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-01-13/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17177,'Eltern-Baby-Café',NULL,'2029-01-15','2029-01-15','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-01-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17178,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-01-15','2029-01-15','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-01-15/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17179,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-15','2029-01-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17180,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-01-15','2029-01-15','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-01-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17181,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-16','2029-01-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17182,'Krabbelgruppe in Spöck',NULL,'2029-01-16','2029-01-16','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-01-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17183,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-01-16','2029-01-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-01-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17184,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-01-16','2029-01-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-01-16/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17185,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-01-16','2029-01-16','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-01-16/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17187,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-01-16','2029-01-16','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-01-16/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17188,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-01-17','2029-01-17','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-01-17/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17189,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-01-17','2029-01-17','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-01-17/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17190,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-01-18','2029-01-18','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-01-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17191,'Korallengarde (10–14 Jahre)',NULL,'2029-01-18','2029-01-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17192,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-01-18','2029-01-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-01-18/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17193,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-18','2029-01-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17194,'Seesternchengarde (3–6 Jahre)',NULL,'2029-01-18','2029-01-18','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-01-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17195,'Tee- und Spielstube',NULL,'2029-01-18','2029-01-18','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-01-18/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17196,'Teen Girls im GrauBau',NULL,'2029-01-18','2029-01-18','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-01-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17197,'Kreativfreitag im GrauBau',NULL,'2029-01-19','2029-01-19','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-01-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17198,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-01-19','2029-01-19','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-01-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17199,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-19','2029-01-19','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-01-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17200,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-01-20','2029-01-20','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-01-20/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17201,'Eltern-Baby-Café',NULL,'2029-01-22','2029-01-22','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-01-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17202,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-01-22','2029-01-22','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-01-22/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17203,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-22','2029-01-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17204,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-01-22','2029-01-22','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-01-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17205,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-23','2029-01-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17206,'Krabbelgruppe in Spöck',NULL,'2029-01-23','2029-01-23','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-01-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17207,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-01-23','2029-01-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-01-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17208,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-01-23','2029-01-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-01-23/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17209,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-01-23','2029-01-23','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-01-23/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17211,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-01-23','2029-01-23','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-01-23/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17212,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-01-24','2029-01-24','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-01-24/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17213,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-01-24','2029-01-24','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-01-24/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17214,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-01-25','2029-01-25','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-01-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17215,'Korallengarde (10–14 Jahre)',NULL,'2029-01-25','2029-01-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17216,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-01-25','2029-01-25','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-01-25/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17217,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-25','2029-01-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17218,'Seesternchengarde (3–6 Jahre)',NULL,'2029-01-25','2029-01-25','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-01-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17219,'Tee- und Spielstube',NULL,'2029-01-25','2029-01-25','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-01-25/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17220,'Teen Girls im GrauBau',NULL,'2029-01-25','2029-01-25','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-01-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17221,'Kreativfreitag im GrauBau',NULL,'2029-01-26','2029-01-26','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-01-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17222,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-01-26','2029-01-26','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-01-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17223,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-26','2029-01-26','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-01-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17224,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-01-27','2029-01-27','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-01-27/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17225,'Eltern-Baby-Café',NULL,'2029-01-29','2029-01-29','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-01-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17226,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-01-29','2029-01-29','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-01-29/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17227,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-01-29','2029-01-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-01-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17228,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-01-29','2029-01-29','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-01-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17229,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-01-30','2029-01-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-01-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17230,'Krabbelgruppe in Spöck',NULL,'2029-01-30','2029-01-30','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-01-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17231,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-01-30','2029-01-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-01-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17232,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-01-30','2029-01-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-01-30/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17233,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-01-30','2029-01-30','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-01-30/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17235,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-01-30','2029-01-30','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-01-30/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17236,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-01-31','2029-01-31','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-01-31/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17237,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-01-31','2029-01-31','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-01-31/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17238,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-02-01','2029-02-01','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-02-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17239,'Korallengarde (10–14 Jahre)',NULL,'2029-02-01','2029-02-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17240,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-02-01','2029-02-01','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-02-01/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17241,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-01','2029-02-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17242,'Seesternchengarde (3–6 Jahre)',NULL,'2029-02-01','2029-02-01','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-02-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17243,'Tee- und Spielstube',NULL,'2029-02-01','2029-02-01','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-02-01/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17244,'Teen Girls im GrauBau',NULL,'2029-02-01','2029-02-01','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-02-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17245,'Kreativfreitag im GrauBau',NULL,'2029-02-02','2029-02-02','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-02-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17246,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-02-02','2029-02-02','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-02-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17247,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-02','2029-02-02','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-02-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17248,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-02-03','2029-02-03','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-02-03/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17249,'Eltern-Baby-Café',NULL,'2029-02-05','2029-02-05','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-02-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17250,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-02-05','2029-02-05','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-02-05/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17251,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-05','2029-02-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17252,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-02-05','2029-02-05','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-02-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17253,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-06','2029-02-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17254,'Krabbelgruppe in Spöck',NULL,'2029-02-06','2029-02-06','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-02-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17255,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-02-06','2029-02-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-02-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17256,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-02-06','2029-02-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-02-06/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17257,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-02-06','2029-02-06','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-02-06/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17259,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-02-06','2029-02-06','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-02-06/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17260,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-02-07','2029-02-07','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-02-07/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17261,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-02-07','2029-02-07','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-02-07/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17262,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-02-08','2029-02-08','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-02-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17263,'Korallengarde (10–14 Jahre)',NULL,'2029-02-08','2029-02-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17264,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-02-08','2029-02-08','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-02-08/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17265,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-08','2029-02-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17266,'Seesternchengarde (3–6 Jahre)',NULL,'2029-02-08','2029-02-08','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-02-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17267,'Tee- und Spielstube',NULL,'2029-02-08','2029-02-08','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-02-08/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17268,'Teen Girls im GrauBau',NULL,'2029-02-08','2029-02-08','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-02-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17269,'Kreativfreitag im GrauBau',NULL,'2029-02-09','2029-02-09','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-02-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17270,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-02-09','2029-02-09','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-02-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17271,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-09','2029-02-09','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-02-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17272,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-02-10','2029-02-10','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-02-10/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17273,'Eltern-Baby-Café',NULL,'2029-02-12','2029-02-12','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-02-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17274,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-02-12','2029-02-12','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-02-12/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17275,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-12','2029-02-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17276,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-02-12','2029-02-12','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-02-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17277,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-13','2029-02-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17278,'Krabbelgruppe in Spöck',NULL,'2029-02-13','2029-02-13','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-02-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17279,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-02-13','2029-02-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-02-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17280,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-02-13','2029-02-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-02-13/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17281,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-02-13','2029-02-13','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-02-13/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17283,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-02-13','2029-02-13','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-02-13/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17284,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-02-14','2029-02-14','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-02-14/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17285,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-02-14','2029-02-14','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-02-14/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17286,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-02-15','2029-02-15','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-02-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17287,'Korallengarde (10–14 Jahre)',NULL,'2029-02-15','2029-02-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17288,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-02-15','2029-02-15','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-02-15/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17289,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-15','2029-02-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17290,'Seesternchengarde (3–6 Jahre)',NULL,'2029-02-15','2029-02-15','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-02-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17291,'Tee- und Spielstube',NULL,'2029-02-15','2029-02-15','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-02-15/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17292,'Teen Girls im GrauBau',NULL,'2029-02-15','2029-02-15','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-02-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17293,'Kreativfreitag im GrauBau',NULL,'2029-02-16','2029-02-16','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-02-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17294,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-02-16','2029-02-16','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-02-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17295,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-16','2029-02-16','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-02-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17296,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-02-17','2029-02-17','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-02-17/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17297,'Eltern-Baby-Café',NULL,'2029-02-19','2029-02-19','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-02-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17298,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-02-19','2029-02-19','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-02-19/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17299,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-19','2029-02-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17300,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-02-19','2029-02-19','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-02-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17301,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-20','2029-02-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17302,'Krabbelgruppe in Spöck',NULL,'2029-02-20','2029-02-20','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-02-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17303,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-02-20','2029-02-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-02-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17304,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-02-20','2029-02-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-02-20/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17305,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-02-20','2029-02-20','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-02-20/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17307,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-02-20','2029-02-20','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-02-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17308,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-02-21','2029-02-21','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-02-21/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17309,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-02-21','2029-02-21','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-02-21/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17310,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-02-22','2029-02-22','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-02-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17311,'Korallengarde (10–14 Jahre)',NULL,'2029-02-22','2029-02-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17312,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-02-22','2029-02-22','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-02-22/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17313,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-22','2029-02-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17314,'Seesternchengarde (3–6 Jahre)',NULL,'2029-02-22','2029-02-22','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-02-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17315,'Tee- und Spielstube',NULL,'2029-02-22','2029-02-22','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-02-22/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17316,'Teen Girls im GrauBau',NULL,'2029-02-22','2029-02-22','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-02-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17317,'Kreativfreitag im GrauBau',NULL,'2029-02-23','2029-02-23','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-02-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17318,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-02-23','2029-02-23','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-02-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17319,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-23','2029-02-23','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-02-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17320,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-02-24','2029-02-24','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-02-24/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17321,'Eltern-Baby-Café',NULL,'2029-02-26','2029-02-26','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-02-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17322,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-02-26','2029-02-26','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-02-26/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17323,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-02-26','2029-02-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-02-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17324,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-02-26','2029-02-26','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-02-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17325,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-02-27','2029-02-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-02-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17326,'Krabbelgruppe in Spöck',NULL,'2029-02-27','2029-02-27','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-02-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17327,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-02-27','2029-02-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-02-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17328,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-02-27','2029-02-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-02-27/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17329,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-02-27','2029-02-27','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-02-27/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17331,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-02-27','2029-02-27','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-02-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17332,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-02-28','2029-02-28','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-02-28/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17333,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-02-28','2029-02-28','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-02-28/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17334,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-03-01','2029-03-01','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-03-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17335,'Korallengarde (10–14 Jahre)',NULL,'2029-03-01','2029-03-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17336,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-03-01','2029-03-01','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-03-01/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17337,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-01','2029-03-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17338,'Seesternchengarde (3–6 Jahre)',NULL,'2029-03-01','2029-03-01','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-03-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17339,'Tee- und Spielstube',NULL,'2029-03-01','2029-03-01','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-03-01/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17340,'Teen Girls im GrauBau',NULL,'2029-03-01','2029-03-01','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-03-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17341,'Kreativfreitag im GrauBau',NULL,'2029-03-02','2029-03-02','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-03-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17342,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-03-02','2029-03-02','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-03-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17343,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-02','2029-03-02','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-03-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17344,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-03-03','2029-03-03','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-03-03/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17345,'Eltern-Baby-Café',NULL,'2029-03-05','2029-03-05','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-03-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17346,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-03-05','2029-03-05','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-03-05/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17347,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-05','2029-03-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17348,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-03-05','2029-03-05','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-03-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17349,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-06','2029-03-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17350,'Krabbelgruppe in Spöck',NULL,'2029-03-06','2029-03-06','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-03-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17351,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-03-06','2029-03-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-03-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17352,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-03-06','2029-03-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-03-06/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17353,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-03-06','2029-03-06','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-03-06/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17355,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-03-06','2029-03-06','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-03-06/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17356,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-03-07','2029-03-07','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-03-07/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17357,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-03-07','2029-03-07','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-03-07/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17358,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-03-08','2029-03-08','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-03-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17359,'Korallengarde (10–14 Jahre)',NULL,'2029-03-08','2029-03-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17360,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-03-08','2029-03-08','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-03-08/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17361,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-08','2029-03-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17362,'Seesternchengarde (3–6 Jahre)',NULL,'2029-03-08','2029-03-08','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-03-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17363,'Tee- und Spielstube',NULL,'2029-03-08','2029-03-08','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-03-08/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17364,'Teen Girls im GrauBau',NULL,'2029-03-08','2029-03-08','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-03-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17365,'Kreativfreitag im GrauBau',NULL,'2029-03-09','2029-03-09','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-03-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17366,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-03-09','2029-03-09','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-03-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17367,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-09','2029-03-09','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-03-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17368,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-03-10','2029-03-10','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-03-10/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17369,'Eltern-Baby-Café',NULL,'2029-03-12','2029-03-12','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-03-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17370,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-03-12','2029-03-12','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-03-12/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17371,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-12','2029-03-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17372,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-03-12','2029-03-12','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-03-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17373,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-13','2029-03-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17374,'Krabbelgruppe in Spöck',NULL,'2029-03-13','2029-03-13','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-03-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17375,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-03-13','2029-03-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-03-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17376,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-03-13','2029-03-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-03-13/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17377,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-03-13','2029-03-13','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-03-13/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17379,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-03-13','2029-03-13','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-03-13/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17380,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-03-14','2029-03-14','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-03-14/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17381,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-03-14','2029-03-14','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-03-14/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17382,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-03-15','2029-03-15','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-03-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17383,'Korallengarde (10–14 Jahre)',NULL,'2029-03-15','2029-03-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17384,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-03-15','2029-03-15','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-03-15/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17385,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-15','2029-03-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17386,'Seesternchengarde (3–6 Jahre)',NULL,'2029-03-15','2029-03-15','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-03-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17387,'Tee- und Spielstube',NULL,'2029-03-15','2029-03-15','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-03-15/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17388,'Teen Girls im GrauBau',NULL,'2029-03-15','2029-03-15','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-03-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17389,'Kreativfreitag im GrauBau',NULL,'2029-03-16','2029-03-16','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-03-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17390,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-03-16','2029-03-16','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-03-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17391,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-16','2029-03-16','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-03-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17392,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-03-17','2029-03-17','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-03-17/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17393,'Eltern-Baby-Café',NULL,'2029-03-19','2029-03-19','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-03-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17394,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-03-19','2029-03-19','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-03-19/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17395,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-19','2029-03-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17396,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-03-19','2029-03-19','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-03-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17397,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-20','2029-03-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17398,'Krabbelgruppe in Spöck',NULL,'2029-03-20','2029-03-20','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-03-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17399,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-03-20','2029-03-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-03-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17400,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-03-20','2029-03-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-03-20/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17401,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-03-20','2029-03-20','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-03-20/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17403,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-03-20','2029-03-20','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-03-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17404,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-03-21','2029-03-21','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-03-21/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17405,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-03-21','2029-03-21','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-03-21/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17406,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-03-22','2029-03-22','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-03-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17407,'Korallengarde (10–14 Jahre)',NULL,'2029-03-22','2029-03-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17408,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-03-22','2029-03-22','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-03-22/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17409,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-22','2029-03-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17410,'Seesternchengarde (3–6 Jahre)',NULL,'2029-03-22','2029-03-22','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-03-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17411,'Tee- und Spielstube',NULL,'2029-03-22','2029-03-22','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-03-22/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17412,'Teen Girls im GrauBau',NULL,'2029-03-22','2029-03-22','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-03-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17413,'Kreativfreitag im GrauBau',NULL,'2029-03-23','2029-03-23','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-03-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17414,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-03-23','2029-03-23','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-03-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17415,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-23','2029-03-23','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-03-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17416,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-03-24','2029-03-24','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-03-24/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17417,'Eltern-Baby-Café',NULL,'2029-03-26','2029-03-26','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-03-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17418,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-03-26','2029-03-26','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-03-26/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17419,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-26','2029-03-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17420,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-03-26','2029-03-26','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-03-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17421,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-27','2029-03-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17422,'Krabbelgruppe in Spöck',NULL,'2029-03-27','2029-03-27','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-03-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17423,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-03-27','2029-03-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-03-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17424,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-03-27','2029-03-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-03-27/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17425,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-03-27','2029-03-27','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-03-27/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17427,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-03-27','2029-03-27','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-03-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17428,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-03-28','2029-03-28','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-03-28/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17429,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-03-28','2029-03-28','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-03-28/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17430,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-03-29','2029-03-29','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-03-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17431,'Korallengarde (10–14 Jahre)',NULL,'2029-03-29','2029-03-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-03-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17432,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-03-29','2029-03-29','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-03-29/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17433,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-03-29','2029-03-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-03-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17434,'Seesternchengarde (3–6 Jahre)',NULL,'2029-03-29','2029-03-29','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-03-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17435,'Tee- und Spielstube',NULL,'2029-03-29','2029-03-29','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-03-29/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17436,'Teen Girls im GrauBau',NULL,'2029-03-29','2029-03-29','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-03-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17437,'Kreativfreitag im GrauBau',NULL,'2029-03-30','2029-03-30','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-03-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17438,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-03-30','2029-03-30','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-03-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17439,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-03-30','2029-03-30','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-03-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17440,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-03-31','2029-03-31','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-03-31/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17441,'Eltern-Baby-Café',NULL,'2029-04-02','2029-04-02','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-04-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17442,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-04-02','2029-04-02','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-04-02/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17443,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-02','2029-04-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17444,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-04-02','2029-04-02','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-04-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17445,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-03','2029-04-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17446,'Krabbelgruppe in Spöck',NULL,'2029-04-03','2029-04-03','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-04-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17447,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-04-03','2029-04-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-04-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17448,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-04-03','2029-04-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-04-03/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17449,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-04-03','2029-04-03','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-04-03/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17451,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-04-03','2029-04-03','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-04-03/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17452,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-04-04','2029-04-04','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-04-04/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17453,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-04-04','2029-04-04','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-04-04/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17454,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-04-05','2029-04-05','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-04-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17455,'Korallengarde (10–14 Jahre)',NULL,'2029-04-05','2029-04-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17456,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-04-05','2029-04-05','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-04-05/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17457,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-05','2029-04-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17458,'Seesternchengarde (3–6 Jahre)',NULL,'2029-04-05','2029-04-05','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-04-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17459,'Tee- und Spielstube',NULL,'2029-04-05','2029-04-05','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-04-05/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17460,'Teen Girls im GrauBau',NULL,'2029-04-05','2029-04-05','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-04-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17461,'Kreativfreitag im GrauBau',NULL,'2029-04-06','2029-04-06','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-04-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17462,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-04-06','2029-04-06','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-04-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17463,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-06','2029-04-06','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-04-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17464,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-04-07','2029-04-07','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-04-07/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17465,'Eltern-Baby-Café',NULL,'2029-04-09','2029-04-09','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-04-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17466,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-04-09','2029-04-09','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-04-09/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17467,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-09','2029-04-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17468,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-04-09','2029-04-09','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-04-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17469,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-10','2029-04-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17470,'Krabbelgruppe in Spöck',NULL,'2029-04-10','2029-04-10','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-04-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17471,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-04-10','2029-04-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-04-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17472,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-04-10','2029-04-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-04-10/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17473,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-04-10','2029-04-10','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-04-10/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17475,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-04-10','2029-04-10','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-04-10/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17476,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-04-11','2029-04-11','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-04-11/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17477,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-04-11','2029-04-11','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-04-11/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17478,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-04-12','2029-04-12','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-04-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17479,'Korallengarde (10–14 Jahre)',NULL,'2029-04-12','2029-04-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17480,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-04-12','2029-04-12','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-04-12/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17481,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-12','2029-04-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17482,'Seesternchengarde (3–6 Jahre)',NULL,'2029-04-12','2029-04-12','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-04-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17483,'Tee- und Spielstube',NULL,'2029-04-12','2029-04-12','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-04-12/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17484,'Teen Girls im GrauBau',NULL,'2029-04-12','2029-04-12','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-04-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17485,'Kreativfreitag im GrauBau',NULL,'2029-04-13','2029-04-13','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-04-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17486,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-04-13','2029-04-13','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-04-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17487,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-13','2029-04-13','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-04-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17488,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-04-14','2029-04-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-04-14/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17489,'Eltern-Baby-Café',NULL,'2029-04-16','2029-04-16','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-04-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17490,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-04-16','2029-04-16','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-04-16/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17491,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-16','2029-04-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17492,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-04-16','2029-04-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-04-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17493,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-17','2029-04-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17494,'Krabbelgruppe in Spöck',NULL,'2029-04-17','2029-04-17','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-04-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17495,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-04-17','2029-04-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-04-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17496,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-04-17','2029-04-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-04-17/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17497,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-04-17','2029-04-17','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-04-17/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17499,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-04-17','2029-04-17','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-04-17/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17500,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-04-18','2029-04-18','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-04-18/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17501,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-04-18','2029-04-18','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-04-18/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17502,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-04-19','2029-04-19','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-04-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17503,'Korallengarde (10–14 Jahre)',NULL,'2029-04-19','2029-04-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17504,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-04-19','2029-04-19','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-04-19/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17505,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-19','2029-04-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17506,'Seesternchengarde (3–6 Jahre)',NULL,'2029-04-19','2029-04-19','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-04-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17507,'Tee- und Spielstube',NULL,'2029-04-19','2029-04-19','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-04-19/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17508,'Teen Girls im GrauBau',NULL,'2029-04-19','2029-04-19','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-04-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17509,'Kreativfreitag im GrauBau',NULL,'2029-04-20','2029-04-20','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-04-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17510,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-04-20','2029-04-20','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-04-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17511,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-20','2029-04-20','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-04-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17512,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-04-21','2029-04-21','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-04-21/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17513,'Eltern-Baby-Café',NULL,'2029-04-23','2029-04-23','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-04-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17514,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-04-23','2029-04-23','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-04-23/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17515,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-23','2029-04-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17516,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-04-23','2029-04-23','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-04-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17517,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-24','2029-04-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17518,'Krabbelgruppe in Spöck',NULL,'2029-04-24','2029-04-24','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-04-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17519,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-04-24','2029-04-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-04-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17520,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-04-24','2029-04-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-04-24/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17521,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-04-24','2029-04-24','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-04-24/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17523,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-04-24','2029-04-24','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-04-24/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17524,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-04-25','2029-04-25','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-04-25/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17525,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-04-25','2029-04-25','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-04-25/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17526,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-04-26','2029-04-26','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-04-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17527,'Korallengarde (10–14 Jahre)',NULL,'2029-04-26','2029-04-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-04-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17528,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-04-26','2029-04-26','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-04-26/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17529,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-26','2029-04-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17530,'Seesternchengarde (3–6 Jahre)',NULL,'2029-04-26','2029-04-26','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-04-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17531,'Tee- und Spielstube',NULL,'2029-04-26','2029-04-26','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-04-26/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17532,'Teen Girls im GrauBau',NULL,'2029-04-26','2029-04-26','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-04-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17533,'Kreativfreitag im GrauBau',NULL,'2029-04-27','2029-04-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-04-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17534,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-04-27','2029-04-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-04-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17535,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-04-27','2029-04-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-04-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17536,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-04-28','2029-04-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-04-28/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17537,'Eltern-Baby-Café',NULL,'2029-04-30','2029-04-30','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-04-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17538,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-04-30','2029-04-30','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-04-30/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17539,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-04-30','2029-04-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-04-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17540,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-04-30','2029-04-30','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-04-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17541,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-01','2029-05-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17542,'Krabbelgruppe in Spöck',NULL,'2029-05-01','2029-05-01','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-05-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17543,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-05-01','2029-05-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-05-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17544,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-05-01','2029-05-01','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-05-01/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17545,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-05-01','2029-05-01','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-05-01/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17547,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-05-01','2029-05-01','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-05-01/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17548,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-05-02','2029-05-02','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-05-02/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17549,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-05-02','2029-05-02','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-05-02/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17550,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-05-03','2029-05-03','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-05-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17551,'Korallengarde (10–14 Jahre)',NULL,'2029-05-03','2029-05-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17552,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-05-03','2029-05-03','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-05-03/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17553,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-03','2029-05-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17554,'Seesternchengarde (3–6 Jahre)',NULL,'2029-05-03','2029-05-03','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-05-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17555,'Tee- und Spielstube',NULL,'2029-05-03','2029-05-03','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-05-03/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17556,'Teen Girls im GrauBau',NULL,'2029-05-03','2029-05-03','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-05-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17557,'Kreativfreitag im GrauBau',NULL,'2029-05-04','2029-05-04','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-05-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17558,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-05-04','2029-05-04','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-05-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17559,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-04','2029-05-04','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-05-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17560,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-05-05','2029-05-05','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-05-05/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17561,'Eltern-Baby-Café',NULL,'2029-05-07','2029-05-07','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-05-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17562,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-05-07','2029-05-07','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-05-07/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17563,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-07','2029-05-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17564,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-05-07','2029-05-07','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-05-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17565,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-08','2029-05-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17566,'Krabbelgruppe in Spöck',NULL,'2029-05-08','2029-05-08','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-05-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17567,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-05-08','2029-05-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-05-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17568,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-05-08','2029-05-08','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-05-08/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17569,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-05-08','2029-05-08','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-05-08/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17571,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-05-08','2029-05-08','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-05-08/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17572,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-05-09','2029-05-09','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-05-09/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17573,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-05-09','2029-05-09','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-05-09/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17574,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-05-10','2029-05-10','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-05-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17575,'Korallengarde (10–14 Jahre)',NULL,'2029-05-10','2029-05-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17576,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-05-10','2029-05-10','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-05-10/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17577,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-10','2029-05-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17578,'Seesternchengarde (3–6 Jahre)',NULL,'2029-05-10','2029-05-10','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-05-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17579,'Tee- und Spielstube',NULL,'2029-05-10','2029-05-10','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-05-10/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17580,'Teen Girls im GrauBau',NULL,'2029-05-10','2029-05-10','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-05-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17581,'Kreativfreitag im GrauBau',NULL,'2029-05-11','2029-05-11','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-05-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17582,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-05-11','2029-05-11','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-05-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17583,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-11','2029-05-11','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-05-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17584,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-05-12','2029-05-12','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-05-12/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17585,'Eltern-Baby-Café',NULL,'2029-05-14','2029-05-14','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-05-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17586,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-05-14','2029-05-14','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-05-14/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17587,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-14','2029-05-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17588,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-05-14','2029-05-14','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-05-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17589,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-15','2029-05-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17590,'Krabbelgruppe in Spöck',NULL,'2029-05-15','2029-05-15','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-05-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17591,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-05-15','2029-05-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-05-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17592,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-05-15','2029-05-15','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-05-15/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17593,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-05-15','2029-05-15','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-05-15/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17595,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-05-15','2029-05-15','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-05-15/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17596,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-05-16','2029-05-16','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-05-16/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17597,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-05-16','2029-05-16','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-05-16/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17598,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-05-17','2029-05-17','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-05-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17599,'Korallengarde (10–14 Jahre)',NULL,'2029-05-17','2029-05-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17600,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-05-17','2029-05-17','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-05-17/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17601,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-17','2029-05-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17602,'Seesternchengarde (3–6 Jahre)',NULL,'2029-05-17','2029-05-17','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-05-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17603,'Tee- und Spielstube',NULL,'2029-05-17','2029-05-17','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-05-17/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17604,'Teen Girls im GrauBau',NULL,'2029-05-17','2029-05-17','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-05-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17605,'Kreativfreitag im GrauBau',NULL,'2029-05-18','2029-05-18','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-05-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17606,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-05-18','2029-05-18','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-05-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17607,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-18','2029-05-18','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-05-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17608,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-05-19','2029-05-19','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-05-19/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17609,'Eltern-Baby-Café',NULL,'2029-05-21','2029-05-21','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-05-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17610,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-05-21','2029-05-21','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-05-21/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17611,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-21','2029-05-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17612,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-05-21','2029-05-21','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-05-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17613,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-22','2029-05-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17614,'Krabbelgruppe in Spöck',NULL,'2029-05-22','2029-05-22','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-05-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17615,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-05-22','2029-05-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-05-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17616,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-05-22','2029-05-22','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-05-22/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17617,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-05-22','2029-05-22','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-05-22/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17619,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-05-22','2029-05-22','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-05-22/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17620,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-05-23','2029-05-23','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-05-23/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17621,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-05-23','2029-05-23','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-05-23/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17622,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-05-24','2029-05-24','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-05-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17623,'Korallengarde (10–14 Jahre)',NULL,'2029-05-24','2029-05-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17624,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-05-24','2029-05-24','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-05-24/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17625,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-24','2029-05-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17626,'Seesternchengarde (3–6 Jahre)',NULL,'2029-05-24','2029-05-24','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-05-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17627,'Tee- und Spielstube',NULL,'2029-05-24','2029-05-24','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-05-24/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17628,'Teen Girls im GrauBau',NULL,'2029-05-24','2029-05-24','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-05-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17629,'Kreativfreitag im GrauBau',NULL,'2029-05-25','2029-05-25','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-05-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17630,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-05-25','2029-05-25','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-05-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17631,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-25','2029-05-25','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-05-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17632,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-05-26','2029-05-26','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-05-26/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17633,'Eltern-Baby-Café',NULL,'2029-05-28','2029-05-28','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-05-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17634,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-05-28','2029-05-28','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-05-28/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17635,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-28','2029-05-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17636,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-05-28','2029-05-28','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-05-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17637,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-05-29','2029-05-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17638,'Krabbelgruppe in Spöck',NULL,'2029-05-29','2029-05-29','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-05-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17639,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-05-29','2029-05-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-05-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17640,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-05-29','2029-05-29','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-05-29/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17641,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-05-29','2029-05-29','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-05-29/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17643,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-05-29','2029-05-29','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-05-29/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17644,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-05-30','2029-05-30','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-05-30/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17645,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-05-30','2029-05-30','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-05-30/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17646,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-05-31','2029-05-31','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-05-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17647,'Korallengarde (10–14 Jahre)',NULL,'2029-05-31','2029-05-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-05-31/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17648,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-05-31','2029-05-31','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-05-31/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17649,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-05-31','2029-05-31','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-05-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17650,'Seesternchengarde (3–6 Jahre)',NULL,'2029-05-31','2029-05-31','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-05-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17651,'Tee- und Spielstube',NULL,'2029-05-31','2029-05-31','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-05-31/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17652,'Teen Girls im GrauBau',NULL,'2029-05-31','2029-05-31','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-05-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17653,'Kreativfreitag im GrauBau',NULL,'2029-06-01','2029-06-01','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-06-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17654,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-06-01','2029-06-01','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-06-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17655,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-01','2029-06-01','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-06-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17656,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-06-02','2029-06-02','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-06-02/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17657,'Eltern-Baby-Café',NULL,'2029-06-04','2029-06-04','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-06-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17658,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-06-04','2029-06-04','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-06-04/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17659,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-04','2029-06-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17660,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-06-04','2029-06-04','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-06-04/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17661,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-05','2029-06-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17662,'Krabbelgruppe in Spöck',NULL,'2029-06-05','2029-06-05','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-06-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17663,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-06-05','2029-06-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-06-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17664,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-06-05','2029-06-05','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-06-05/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17665,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-06-05','2029-06-05','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-06-05/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17667,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-06-05','2029-06-05','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-06-05/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17668,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-06-06','2029-06-06','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-06-06/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17669,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-06-06','2029-06-06','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-06-06/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17670,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-06-07','2029-06-07','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-06-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17671,'Korallengarde (10–14 Jahre)',NULL,'2029-06-07','2029-06-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17672,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-06-07','2029-06-07','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-06-07/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17673,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-07','2029-06-07','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17674,'Seesternchengarde (3–6 Jahre)',NULL,'2029-06-07','2029-06-07','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-06-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17675,'Tee- und Spielstube',NULL,'2029-06-07','2029-06-07','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-06-07/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17676,'Teen Girls im GrauBau',NULL,'2029-06-07','2029-06-07','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-06-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17677,'Kreativfreitag im GrauBau',NULL,'2029-06-08','2029-06-08','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-06-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17678,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-06-08','2029-06-08','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-06-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17679,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-08','2029-06-08','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-06-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17680,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-06-09','2029-06-09','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-06-09/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17681,'Eltern-Baby-Café',NULL,'2029-06-11','2029-06-11','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-06-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17682,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-06-11','2029-06-11','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-06-11/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17683,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-11','2029-06-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17684,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-06-11','2029-06-11','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-06-11/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17685,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-12','2029-06-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17686,'Krabbelgruppe in Spöck',NULL,'2029-06-12','2029-06-12','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-06-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17687,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-06-12','2029-06-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-06-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17688,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-06-12','2029-06-12','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-06-12/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17689,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-06-12','2029-06-12','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-06-12/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17691,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-06-12','2029-06-12','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-06-12/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17692,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-06-13','2029-06-13','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-06-13/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17693,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-06-13','2029-06-13','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-06-13/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17694,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-06-14','2029-06-14','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-06-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17695,'Korallengarde (10–14 Jahre)',NULL,'2029-06-14','2029-06-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17696,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-06-14','2029-06-14','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-06-14/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17697,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-14','2029-06-14','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17698,'Seesternchengarde (3–6 Jahre)',NULL,'2029-06-14','2029-06-14','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-06-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17699,'Tee- und Spielstube',NULL,'2029-06-14','2029-06-14','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-06-14/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17700,'Teen Girls im GrauBau',NULL,'2029-06-14','2029-06-14','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-06-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17701,'Kreativfreitag im GrauBau',NULL,'2029-06-15','2029-06-15','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-06-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17702,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-06-15','2029-06-15','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-06-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17703,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-15','2029-06-15','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-06-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17704,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-06-16','2029-06-16','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-06-16/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17705,'Eltern-Baby-Café',NULL,'2029-06-18','2029-06-18','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-06-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17706,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-06-18','2029-06-18','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-06-18/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17707,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-18','2029-06-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17708,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-06-18','2029-06-18','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-06-18/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17709,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-19','2029-06-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17710,'Krabbelgruppe in Spöck',NULL,'2029-06-19','2029-06-19','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-06-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17711,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-06-19','2029-06-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-06-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17712,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-06-19','2029-06-19','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-06-19/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17713,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-06-19','2029-06-19','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-06-19/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17715,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-06-19','2029-06-19','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-06-19/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17716,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-06-20','2029-06-20','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-06-20/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17717,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-06-20','2029-06-20','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-06-20/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17718,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-06-21','2029-06-21','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-06-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17719,'Korallengarde (10–14 Jahre)',NULL,'2029-06-21','2029-06-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17720,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-06-21','2029-06-21','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-06-21/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17721,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-21','2029-06-21','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17722,'Seesternchengarde (3–6 Jahre)',NULL,'2029-06-21','2029-06-21','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-06-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17723,'Tee- und Spielstube',NULL,'2029-06-21','2029-06-21','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-06-21/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17724,'Teen Girls im GrauBau',NULL,'2029-06-21','2029-06-21','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-06-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17725,'Kreativfreitag im GrauBau',NULL,'2029-06-22','2029-06-22','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-06-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17726,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-06-22','2029-06-22','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-06-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17727,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-22','2029-06-22','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-06-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17728,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-06-23','2029-06-23','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-06-23/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17729,'Eltern-Baby-Café',NULL,'2029-06-25','2029-06-25','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-06-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17730,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-06-25','2029-06-25','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-06-25/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17731,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-25','2029-06-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17732,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-06-25','2029-06-25','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-06-25/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17733,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-26','2029-06-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17734,'Krabbelgruppe in Spöck',NULL,'2029-06-26','2029-06-26','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-06-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17735,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-06-26','2029-06-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-06-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17736,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-06-26','2029-06-26','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-06-26/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17737,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-06-26','2029-06-26','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-06-26/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17739,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-06-26','2029-06-26','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-06-26/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17740,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-06-27','2029-06-27','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-06-27/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17741,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-06-27','2029-06-27','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-06-27/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17742,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-06-28','2029-06-28','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-06-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17743,'Korallengarde (10–14 Jahre)',NULL,'2029-06-28','2029-06-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-06-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17744,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-06-28','2029-06-28','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-06-28/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17745,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-06-28','2029-06-28','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-06-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17746,'Seesternchengarde (3–6 Jahre)',NULL,'2029-06-28','2029-06-28','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-06-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17747,'Tee- und Spielstube',NULL,'2029-06-28','2029-06-28','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-06-28/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17748,'Teen Girls im GrauBau',NULL,'2029-06-28','2029-06-28','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-06-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17749,'Kreativfreitag im GrauBau',NULL,'2029-06-29','2029-06-29','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-06-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17750,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-06-29','2029-06-29','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-06-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17751,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-06-29','2029-06-29','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-06-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17752,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-06-30','2029-06-30','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-06-30/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17753,'Eltern-Baby-Café',NULL,'2029-07-02','2029-07-02','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-07-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17754,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-07-02','2029-07-02','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-07-02/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17755,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-02','2029-07-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17756,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-07-02','2029-07-02','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-07-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17757,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-03','2029-07-03','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-03/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17758,'Krabbelgruppe in Spöck',NULL,'2029-07-03','2029-07-03','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-07-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17759,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-07-03','2029-07-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-07-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17760,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-07-03','2029-07-03','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-07-03/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17761,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-07-03','2029-07-03','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-07-03/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17763,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-07-03','2029-07-03','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-07-03/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17764,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-07-04','2029-07-04','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-07-04/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17765,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-07-04','2029-07-04','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-07-04/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17766,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-07-05','2029-07-05','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-07-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17767,'Korallengarde (10–14 Jahre)',NULL,'2029-07-05','2029-07-05','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-05/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17768,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-07-05','2029-07-05','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-07-05/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17769,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-05','2029-07-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17770,'Seesternchengarde (3–6 Jahre)',NULL,'2029-07-05','2029-07-05','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-07-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17771,'Tee- und Spielstube',NULL,'2029-07-05','2029-07-05','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-07-05/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17772,'Teen Girls im GrauBau',NULL,'2029-07-05','2029-07-05','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-07-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17773,'Kreativfreitag im GrauBau',NULL,'2029-07-06','2029-07-06','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-07-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17774,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-07-06','2029-07-06','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-07-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17775,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-06','2029-07-06','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-07-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17776,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-07-07','2029-07-07','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-07-07/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17777,'Eltern-Baby-Café',NULL,'2029-07-09','2029-07-09','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-07-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17778,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-07-09','2029-07-09','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-07-09/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17779,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-09','2029-07-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17780,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-07-09','2029-07-09','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-07-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17781,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-10','2029-07-10','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-10/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17782,'Krabbelgruppe in Spöck',NULL,'2029-07-10','2029-07-10','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-07-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17783,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-07-10','2029-07-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-07-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17784,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-07-10','2029-07-10','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-07-10/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17785,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-07-10','2029-07-10','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-07-10/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17787,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-07-10','2029-07-10','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-07-10/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17788,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-07-11','2029-07-11','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-07-11/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17789,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-07-11','2029-07-11','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-07-11/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17790,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-07-12','2029-07-12','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-07-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17791,'Korallengarde (10–14 Jahre)',NULL,'2029-07-12','2029-07-12','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-12/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17792,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-07-12','2029-07-12','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-07-12/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17793,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-12','2029-07-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17794,'Seesternchengarde (3–6 Jahre)',NULL,'2029-07-12','2029-07-12','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-07-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17795,'Tee- und Spielstube',NULL,'2029-07-12','2029-07-12','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-07-12/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17796,'Teen Girls im GrauBau',NULL,'2029-07-12','2029-07-12','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-07-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17797,'Kreativfreitag im GrauBau',NULL,'2029-07-13','2029-07-13','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-07-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17798,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-07-13','2029-07-13','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-07-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17799,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-13','2029-07-13','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-07-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17800,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-07-14','2029-07-14','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-07-14/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17801,'Eltern-Baby-Café',NULL,'2029-07-16','2029-07-16','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-07-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17802,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-07-16','2029-07-16','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-07-16/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17803,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-16','2029-07-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17804,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-07-16','2029-07-16','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-07-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17805,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-17','2029-07-17','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-17/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17806,'Krabbelgruppe in Spöck',NULL,'2029-07-17','2029-07-17','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-07-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17807,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-07-17','2029-07-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-07-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17808,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-07-17','2029-07-17','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-07-17/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17809,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-07-17','2029-07-17','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-07-17/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17811,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-07-17','2029-07-17','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-07-17/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17812,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-07-18','2029-07-18','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-07-18/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17813,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-07-18','2029-07-18','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-07-18/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17814,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-07-19','2029-07-19','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-07-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17815,'Korallengarde (10–14 Jahre)',NULL,'2029-07-19','2029-07-19','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-19/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17816,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-07-19','2029-07-19','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-07-19/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17817,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-19','2029-07-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17818,'Seesternchengarde (3–6 Jahre)',NULL,'2029-07-19','2029-07-19','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-07-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17819,'Tee- und Spielstube',NULL,'2029-07-19','2029-07-19','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-07-19/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17820,'Teen Girls im GrauBau',NULL,'2029-07-19','2029-07-19','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-07-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17821,'Kreativfreitag im GrauBau',NULL,'2029-07-20','2029-07-20','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-07-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17822,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-07-20','2029-07-20','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-07-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17823,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-20','2029-07-20','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-07-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17824,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-07-21','2029-07-21','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-07-21/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17825,'Eltern-Baby-Café',NULL,'2029-07-23','2029-07-23','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-07-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17826,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-07-23','2029-07-23','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-07-23/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17827,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-23','2029-07-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17828,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-07-23','2029-07-23','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-07-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17829,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-24','2029-07-24','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-24/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17830,'Krabbelgruppe in Spöck',NULL,'2029-07-24','2029-07-24','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-07-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17831,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-07-24','2029-07-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-07-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17832,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-07-24','2029-07-24','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-07-24/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17833,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-07-24','2029-07-24','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-07-24/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17835,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-07-24','2029-07-24','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-07-24/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17836,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-07-25','2029-07-25','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-07-25/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17837,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-07-25','2029-07-25','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-07-25/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17838,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-07-26','2029-07-26','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-07-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17839,'Korallengarde (10–14 Jahre)',NULL,'2029-07-26','2029-07-26','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-26/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17840,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-07-26','2029-07-26','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-07-26/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17841,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-26','2029-07-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17842,'Seesternchengarde (3–6 Jahre)',NULL,'2029-07-26','2029-07-26','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-07-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17843,'Tee- und Spielstube',NULL,'2029-07-26','2029-07-26','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-07-26/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17844,'Teen Girls im GrauBau',NULL,'2029-07-26','2029-07-26','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-07-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17845,'Kreativfreitag im GrauBau',NULL,'2029-07-27','2029-07-27','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-07-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17846,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-07-27','2029-07-27','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-07-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17847,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-27','2029-07-27','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-07-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17848,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-07-28','2029-07-28','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-07-28/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17849,'Eltern-Baby-Café',NULL,'2029-07-30','2029-07-30','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-07-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17850,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-07-30','2029-07-30','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-07-30/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17851,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-07-30','2029-07-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-07-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17852,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-07-30','2029-07-30','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-07-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17853,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-07-31','2029-07-31','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-07-31/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17854,'Krabbelgruppe in Spöck',NULL,'2029-07-31','2029-07-31','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-07-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17855,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-07-31','2029-07-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-07-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17856,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-07-31','2029-07-31','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-07-31/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17857,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-07-31','2029-07-31','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-07-31/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17859,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-07-31','2029-07-31','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-07-31/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17860,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-08-01','2029-08-01','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-08-01/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17861,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-08-01','2029-08-01','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-08-01/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17862,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-08-02','2029-08-02','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-08-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17863,'Korallengarde (10–14 Jahre)',NULL,'2029-08-02','2029-08-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17864,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-08-02','2029-08-02','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-08-02/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17865,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-02','2029-08-02','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17866,'Seesternchengarde (3–6 Jahre)',NULL,'2029-08-02','2029-08-02','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-08-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17867,'Tee- und Spielstube',NULL,'2029-08-02','2029-08-02','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-08-02/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17868,'Teen Girls im GrauBau',NULL,'2029-08-02','2029-08-02','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-08-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17869,'Kreativfreitag im GrauBau',NULL,'2029-08-03','2029-08-03','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-08-03/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17870,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-08-03','2029-08-03','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-08-03/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17871,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-03','2029-08-03','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-08-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17872,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-08-04','2029-08-04','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-08-04/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17873,'Eltern-Baby-Café',NULL,'2029-08-06','2029-08-06','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-08-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17874,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-08-06','2029-08-06','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-08-06/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17875,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-06','2029-08-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17876,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-08-06','2029-08-06','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-08-06/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17877,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-07','2029-08-07','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-07/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17878,'Krabbelgruppe in Spöck',NULL,'2029-08-07','2029-08-07','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-08-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17879,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-08-07','2029-08-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-08-07/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17880,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-08-07','2029-08-07','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-08-07/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17881,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-08-07','2029-08-07','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-08-07/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17883,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-08-07','2029-08-07','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-08-07/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17884,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-08-08','2029-08-08','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-08-08/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17885,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-08-08','2029-08-08','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-08-08/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17886,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-08-09','2029-08-09','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-08-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17887,'Korallengarde (10–14 Jahre)',NULL,'2029-08-09','2029-08-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17888,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-08-09','2029-08-09','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-08-09/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17889,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-09','2029-08-09','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17890,'Seesternchengarde (3–6 Jahre)',NULL,'2029-08-09','2029-08-09','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-08-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17891,'Tee- und Spielstube',NULL,'2029-08-09','2029-08-09','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-08-09/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17892,'Teen Girls im GrauBau',NULL,'2029-08-09','2029-08-09','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-08-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17893,'Kreativfreitag im GrauBau',NULL,'2029-08-10','2029-08-10','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-08-10/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17894,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-08-10','2029-08-10','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-08-10/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17895,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-10','2029-08-10','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-08-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17896,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-08-11','2029-08-11','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-08-11/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17897,'Eltern-Baby-Café',NULL,'2029-08-13','2029-08-13','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-08-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17898,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-08-13','2029-08-13','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-08-13/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17899,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-13','2029-08-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17900,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-08-13','2029-08-13','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-08-13/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17901,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-14','2029-08-14','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-14/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17902,'Krabbelgruppe in Spöck',NULL,'2029-08-14','2029-08-14','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-08-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17903,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-08-14','2029-08-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-08-14/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17904,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-08-14','2029-08-14','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-08-14/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17905,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-08-14','2029-08-14','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-08-14/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17907,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-08-14','2029-08-14','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-08-14/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17908,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-08-15','2029-08-15','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-08-15/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17909,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-08-15','2029-08-15','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-08-15/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17910,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-08-16','2029-08-16','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-08-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17911,'Korallengarde (10–14 Jahre)',NULL,'2029-08-16','2029-08-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17912,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-08-16','2029-08-16','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-08-16/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17913,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-16','2029-08-16','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17914,'Seesternchengarde (3–6 Jahre)',NULL,'2029-08-16','2029-08-16','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-08-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17915,'Tee- und Spielstube',NULL,'2029-08-16','2029-08-16','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-08-16/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17916,'Teen Girls im GrauBau',NULL,'2029-08-16','2029-08-16','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-08-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17917,'Kreativfreitag im GrauBau',NULL,'2029-08-17','2029-08-17','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-08-17/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17918,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-08-17','2029-08-17','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-08-17/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17919,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-17','2029-08-17','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-08-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17920,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-08-18','2029-08-18','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-08-18/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17921,'Eltern-Baby-Café',NULL,'2029-08-20','2029-08-20','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-08-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17922,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-08-20','2029-08-20','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-08-20/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17923,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-20','2029-08-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17924,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-08-20','2029-08-20','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-08-20/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17925,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-21','2029-08-21','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-21/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17926,'Krabbelgruppe in Spöck',NULL,'2029-08-21','2029-08-21','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-08-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17927,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-08-21','2029-08-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-08-21/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17928,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-08-21','2029-08-21','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-08-21/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17929,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-08-21','2029-08-21','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-08-21/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17931,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-08-21','2029-08-21','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-08-21/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17932,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-08-22','2029-08-22','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-08-22/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17933,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-08-22','2029-08-22','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-08-22/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17934,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-08-23','2029-08-23','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-08-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17935,'Korallengarde (10–14 Jahre)',NULL,'2029-08-23','2029-08-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17936,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-08-23','2029-08-23','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-08-23/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17937,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-23','2029-08-23','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17938,'Seesternchengarde (3–6 Jahre)',NULL,'2029-08-23','2029-08-23','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-08-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17939,'Tee- und Spielstube',NULL,'2029-08-23','2029-08-23','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-08-23/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17940,'Teen Girls im GrauBau',NULL,'2029-08-23','2029-08-23','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-08-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17941,'Kreativfreitag im GrauBau',NULL,'2029-08-24','2029-08-24','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-08-24/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17942,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-08-24','2029-08-24','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-08-24/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17943,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-24','2029-08-24','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-08-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17944,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-08-25','2029-08-25','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-08-25/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17945,'Eltern-Baby-Café',NULL,'2029-08-27','2029-08-27','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-08-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17946,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-08-27','2029-08-27','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-08-27/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17947,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-27','2029-08-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17948,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-08-27','2029-08-27','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-08-27/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17949,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-28','2029-08-28','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-28/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17950,'Krabbelgruppe in Spöck',NULL,'2029-08-28','2029-08-28','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-08-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17951,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-08-28','2029-08-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-08-28/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17952,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-08-28','2029-08-28','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-08-28/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17953,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-08-28','2029-08-28','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-08-28/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17955,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-08-28','2029-08-28','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-08-28/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17956,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-08-29','2029-08-29','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-08-29/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17957,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-08-29','2029-08-29','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-08-29/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17958,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-08-30','2029-08-30','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-08-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17959,'Korallengarde (10–14 Jahre)',NULL,'2029-08-30','2029-08-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-08-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17960,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-08-30','2029-08-30','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-08-30/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17961,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-08-30','2029-08-30','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-08-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17962,'Seesternchengarde (3–6 Jahre)',NULL,'2029-08-30','2029-08-30','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-08-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17963,'Tee- und Spielstube',NULL,'2029-08-30','2029-08-30','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-08-30/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17964,'Teen Girls im GrauBau',NULL,'2029-08-30','2029-08-30','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-08-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17965,'Kreativfreitag im GrauBau',NULL,'2029-08-31','2029-08-31','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-08-31/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17966,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-08-31','2029-08-31','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-08-31/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17967,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-08-31','2029-08-31','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-08-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17968,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-09-01','2029-09-01','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-09-01/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17969,'Eltern-Baby-Café',NULL,'2029-09-03','2029-09-03','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-09-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17970,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-09-03','2029-09-03','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-09-03/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17971,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-03','2029-09-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17972,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-09-03','2029-09-03','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-09-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17973,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-04','2029-09-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17974,'Krabbelgruppe in Spöck',NULL,'2029-09-04','2029-09-04','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-09-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17975,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-09-04','2029-09-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-09-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17976,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-09-04','2029-09-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-09-04/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17977,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-09-04','2029-09-04','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-09-04/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17979,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-09-04','2029-09-04','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-09-04/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17980,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-09-05','2029-09-05','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-09-05/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17981,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-09-05','2029-09-05','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-09-05/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17982,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-09-06','2029-09-06','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-09-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17983,'Korallengarde (10–14 Jahre)',NULL,'2029-09-06','2029-09-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17984,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-09-06','2029-09-06','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-09-06/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17985,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-06','2029-09-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17986,'Seesternchengarde (3–6 Jahre)',NULL,'2029-09-06','2029-09-06','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-09-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17987,'Tee- und Spielstube',NULL,'2029-09-06','2029-09-06','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-09-06/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17988,'Teen Girls im GrauBau',NULL,'2029-09-06','2029-09-06','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-09-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17989,'Kreativfreitag im GrauBau',NULL,'2029-09-07','2029-09-07','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-09-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17990,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-09-07','2029-09-07','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-09-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17991,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-07','2029-09-07','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-09-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17992,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-09-08','2029-09-08','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-09-08/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17993,'Eltern-Baby-Café',NULL,'2029-09-10','2029-09-10','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-09-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17994,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-09-10','2029-09-10','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-09-10/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17995,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-10','2029-09-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17996,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-09-10','2029-09-10','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-09-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17997,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-11','2029-09-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(17998,'Krabbelgruppe in Spöck',NULL,'2029-09-11','2029-09-11','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-09-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(17999,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-09-11','2029-09-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-09-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18000,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-09-11','2029-09-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-09-11/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18001,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-09-11','2029-09-11','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-09-11/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18003,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-09-11','2029-09-11','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-09-11/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18004,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-09-12','2029-09-12','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-09-12/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18005,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-09-12','2029-09-12','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-09-12/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18006,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-09-13','2029-09-13','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-09-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18007,'Korallengarde (10–14 Jahre)',NULL,'2029-09-13','2029-09-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18008,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-09-13','2029-09-13','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-09-13/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18009,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-13','2029-09-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18010,'Seesternchengarde (3–6 Jahre)',NULL,'2029-09-13','2029-09-13','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-09-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18011,'Tee- und Spielstube',NULL,'2029-09-13','2029-09-13','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-09-13/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18012,'Teen Girls im GrauBau',NULL,'2029-09-13','2029-09-13','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-09-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18013,'Kreativfreitag im GrauBau',NULL,'2029-09-14','2029-09-14','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-09-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18014,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-09-14','2029-09-14','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-09-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18015,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-14','2029-09-14','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-09-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18016,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-09-15','2029-09-15','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-09-15/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18017,'Eltern-Baby-Café',NULL,'2029-09-17','2029-09-17','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-09-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18018,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-09-17','2029-09-17','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-09-17/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18019,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-17','2029-09-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18020,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-09-17','2029-09-17','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-09-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18021,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-18','2029-09-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18022,'Krabbelgruppe in Spöck',NULL,'2029-09-18','2029-09-18','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-09-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18023,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-09-18','2029-09-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-09-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18024,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-09-18','2029-09-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-09-18/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18025,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-09-18','2029-09-18','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-09-18/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18027,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-09-18','2029-09-18','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-09-18/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18028,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-09-19','2029-09-19','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-09-19/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18029,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-09-19','2029-09-19','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-09-19/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18030,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-09-20','2029-09-20','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-09-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18031,'Korallengarde (10–14 Jahre)',NULL,'2029-09-20','2029-09-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18032,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-09-20','2029-09-20','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-09-20/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18033,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-20','2029-09-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18034,'Seesternchengarde (3–6 Jahre)',NULL,'2029-09-20','2029-09-20','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-09-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18035,'Tee- und Spielstube',NULL,'2029-09-20','2029-09-20','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-09-20/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18036,'Teen Girls im GrauBau',NULL,'2029-09-20','2029-09-20','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-09-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18037,'Kreativfreitag im GrauBau',NULL,'2029-09-21','2029-09-21','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-09-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18038,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-09-21','2029-09-21','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-09-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18039,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-21','2029-09-21','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-09-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18040,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-09-22','2029-09-22','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-09-22/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18041,'Eltern-Baby-Café',NULL,'2029-09-24','2029-09-24','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-09-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18042,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-09-24','2029-09-24','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-09-24/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18043,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-24','2029-09-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18044,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-09-24','2029-09-24','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-09-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18045,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-25','2029-09-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18046,'Krabbelgruppe in Spöck',NULL,'2029-09-25','2029-09-25','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-09-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18047,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-09-25','2029-09-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-09-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18048,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-09-25','2029-09-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-09-25/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18049,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-09-25','2029-09-25','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-09-25/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18051,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-09-25','2029-09-25','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-09-25/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18052,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-09-26','2029-09-26','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-09-26/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18053,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-09-26','2029-09-26','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-09-26/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18054,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-09-27','2029-09-27','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-09-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18055,'Korallengarde (10–14 Jahre)',NULL,'2029-09-27','2029-09-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-09-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18056,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-09-27','2029-09-27','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-09-27/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18057,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-09-27','2029-09-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-09-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18058,'Seesternchengarde (3–6 Jahre)',NULL,'2029-09-27','2029-09-27','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-09-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18059,'Tee- und Spielstube',NULL,'2029-09-27','2029-09-27','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-09-27/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18060,'Teen Girls im GrauBau',NULL,'2029-09-27','2029-09-27','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-09-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18061,'Kreativfreitag im GrauBau',NULL,'2029-09-28','2029-09-28','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-09-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18062,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-09-28','2029-09-28','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-09-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18063,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-09-28','2029-09-28','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-09-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18064,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-09-29','2029-09-29','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-09-29/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18065,'Eltern-Baby-Café',NULL,'2029-10-01','2029-10-01','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-10-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18066,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-10-01','2029-10-01','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-10-01/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18067,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-01','2029-10-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18068,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-10-01','2029-10-01','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-10-01/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18069,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-02','2029-10-02','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-02/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18070,'Krabbelgruppe in Spöck',NULL,'2029-10-02','2029-10-02','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-10-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18071,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-10-02','2029-10-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-10-02/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18072,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-10-02','2029-10-02','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-10-02/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18073,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-10-02','2029-10-02','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-10-02/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18075,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-10-02','2029-10-02','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-10-02/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18076,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-10-03','2029-10-03','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-10-03/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18077,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-10-03','2029-10-03','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-10-03/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18078,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-10-04','2029-10-04','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-10-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18079,'Korallengarde (10–14 Jahre)',NULL,'2029-10-04','2029-10-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18080,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-10-04','2029-10-04','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-10-04/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18081,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-04','2029-10-04','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18082,'Seesternchengarde (3–6 Jahre)',NULL,'2029-10-04','2029-10-04','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-10-04/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18083,'Tee- und Spielstube',NULL,'2029-10-04','2029-10-04','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-10-04/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18084,'Teen Girls im GrauBau',NULL,'2029-10-04','2029-10-04','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-10-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18085,'Kreativfreitag im GrauBau',NULL,'2029-10-05','2029-10-05','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-10-05/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18086,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-10-05','2029-10-05','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-10-05/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18087,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-05','2029-10-05','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-10-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18088,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-10-06','2029-10-06','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-10-06/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18089,'Eltern-Baby-Café',NULL,'2029-10-08','2029-10-08','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-10-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18090,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-10-08','2029-10-08','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-10-08/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18091,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-08','2029-10-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18092,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-10-08','2029-10-08','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-10-08/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18093,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-09','2029-10-09','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-09/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18094,'Krabbelgruppe in Spöck',NULL,'2029-10-09','2029-10-09','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-10-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18095,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-10-09','2029-10-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-10-09/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18096,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-10-09','2029-10-09','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-10-09/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18097,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-10-09','2029-10-09','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-10-09/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18099,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-10-09','2029-10-09','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-10-09/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18100,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-10-10','2029-10-10','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-10-10/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18101,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-10-10','2029-10-10','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-10-10/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18102,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-10-11','2029-10-11','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-10-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18103,'Korallengarde (10–14 Jahre)',NULL,'2029-10-11','2029-10-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18104,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-10-11','2029-10-11','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-10-11/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18105,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-11','2029-10-11','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18106,'Seesternchengarde (3–6 Jahre)',NULL,'2029-10-11','2029-10-11','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-10-11/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18107,'Tee- und Spielstube',NULL,'2029-10-11','2029-10-11','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-10-11/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18108,'Teen Girls im GrauBau',NULL,'2029-10-11','2029-10-11','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-10-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18109,'Kreativfreitag im GrauBau',NULL,'2029-10-12','2029-10-12','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-10-12/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18110,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-10-12','2029-10-12','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-10-12/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18111,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-12','2029-10-12','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-10-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18112,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-10-13','2029-10-13','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-10-13/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18113,'Eltern-Baby-Café',NULL,'2029-10-15','2029-10-15','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-10-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18114,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-10-15','2029-10-15','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-10-15/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18115,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-15','2029-10-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18116,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-10-15','2029-10-15','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-10-15/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18117,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-16','2029-10-16','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-16/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18118,'Krabbelgruppe in Spöck',NULL,'2029-10-16','2029-10-16','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-10-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18119,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-10-16','2029-10-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-10-16/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18120,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-10-16','2029-10-16','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-10-16/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18121,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-10-16','2029-10-16','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-10-16/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18123,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-10-16','2029-10-16','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-10-16/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18124,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-10-17','2029-10-17','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-10-17/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18125,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-10-17','2029-10-17','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-10-17/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18126,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-10-18','2029-10-18','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-10-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18127,'Korallengarde (10–14 Jahre)',NULL,'2029-10-18','2029-10-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18128,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-10-18','2029-10-18','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-10-18/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18129,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-18','2029-10-18','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18130,'Seesternchengarde (3–6 Jahre)',NULL,'2029-10-18','2029-10-18','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-10-18/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18131,'Tee- und Spielstube',NULL,'2029-10-18','2029-10-18','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-10-18/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18132,'Teen Girls im GrauBau',NULL,'2029-10-18','2029-10-18','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-10-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18133,'Kreativfreitag im GrauBau',NULL,'2029-10-19','2029-10-19','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-10-19/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18134,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-10-19','2029-10-19','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-10-19/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18135,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-19','2029-10-19','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-10-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18136,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-10-20','2029-10-20','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-10-20/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18137,'Eltern-Baby-Café',NULL,'2029-10-22','2029-10-22','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-10-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18138,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-10-22','2029-10-22','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-10-22/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18139,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-22','2029-10-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18140,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-10-22','2029-10-22','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-10-22/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18141,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-23','2029-10-23','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-23/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18142,'Krabbelgruppe in Spöck',NULL,'2029-10-23','2029-10-23','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-10-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18143,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-10-23','2029-10-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-10-23/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18144,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-10-23','2029-10-23','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-10-23/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18145,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-10-23','2029-10-23','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-10-23/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18147,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-10-23','2029-10-23','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-10-23/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18148,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-10-24','2029-10-24','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-10-24/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18149,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-10-24','2029-10-24','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-10-24/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18150,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-10-25','2029-10-25','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-10-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18151,'Korallengarde (10–14 Jahre)',NULL,'2029-10-25','2029-10-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18152,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-10-25','2029-10-25','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-10-25/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18153,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-25','2029-10-25','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18154,'Seesternchengarde (3–6 Jahre)',NULL,'2029-10-25','2029-10-25','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-10-25/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18155,'Tee- und Spielstube',NULL,'2029-10-25','2029-10-25','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-10-25/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18156,'Teen Girls im GrauBau',NULL,'2029-10-25','2029-10-25','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-10-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18157,'Kreativfreitag im GrauBau',NULL,'2029-10-26','2029-10-26','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-10-26/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18158,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-10-26','2029-10-26','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-10-26/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18159,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-26','2029-10-26','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-10-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18160,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-10-27','2029-10-27','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-10-27/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18161,'Eltern-Baby-Café',NULL,'2029-10-29','2029-10-29','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-10-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18162,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-10-29','2029-10-29','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-10-29/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18163,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-10-29','2029-10-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-10-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18164,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-10-29','2029-10-29','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-10-29/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18165,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-10-30','2029-10-30','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-10-30/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18166,'Krabbelgruppe in Spöck',NULL,'2029-10-30','2029-10-30','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-10-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18167,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-10-30','2029-10-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-10-30/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18168,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-10-30','2029-10-30','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-10-30/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18169,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-10-30','2029-10-30','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-10-30/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18171,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-10-30','2029-10-30','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-10-30/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18172,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-10-31','2029-10-31','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-10-31/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18173,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-10-31','2029-10-31','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-10-31/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18174,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-11-01','2029-11-01','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-11-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18175,'Korallengarde (10–14 Jahre)',NULL,'2029-11-01','2029-11-01','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-01/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18176,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-11-01','2029-11-01','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-11-01/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18177,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-01','2029-11-01','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-01/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18178,'Seesternchengarde (3–6 Jahre)',NULL,'2029-11-01','2029-11-01','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-11-01/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18179,'Tee- und Spielstube',NULL,'2029-11-01','2029-11-01','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-11-01/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18180,'Teen Girls im GrauBau',NULL,'2029-11-01','2029-11-01','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-11-01/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18181,'Kreativfreitag im GrauBau',NULL,'2029-11-02','2029-11-02','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-11-02/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18182,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-11-02','2029-11-02','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-11-02/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18183,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-02','2029-11-02','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-11-02/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18184,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-11-03','2029-11-03','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-11-03/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18185,'Eltern-Baby-Café',NULL,'2029-11-05','2029-11-05','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-11-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18186,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-11-05','2029-11-05','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-11-05/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18187,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-05','2029-11-05','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-05/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18188,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-11-05','2029-11-05','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-11-05/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18189,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-06','2029-11-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18190,'Krabbelgruppe in Spöck',NULL,'2029-11-06','2029-11-06','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-11-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18191,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-11-06','2029-11-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-11-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18192,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-11-06','2029-11-06','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-11-06/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18193,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-11-06','2029-11-06','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-11-06/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18195,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-11-06','2029-11-06','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-11-06/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18196,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-11-07','2029-11-07','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-11-07/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18197,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-11-07','2029-11-07','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-11-07/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18198,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-11-08','2029-11-08','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-11-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18199,'Korallengarde (10–14 Jahre)',NULL,'2029-11-08','2029-11-08','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-08/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18200,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-11-08','2029-11-08','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-11-08/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18201,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-08','2029-11-08','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-08/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18202,'Seesternchengarde (3–6 Jahre)',NULL,'2029-11-08','2029-11-08','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-11-08/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18203,'Tee- und Spielstube',NULL,'2029-11-08','2029-11-08','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-11-08/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18204,'Teen Girls im GrauBau',NULL,'2029-11-08','2029-11-08','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-11-08/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18205,'Kreativfreitag im GrauBau',NULL,'2029-11-09','2029-11-09','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-11-09/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18206,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-11-09','2029-11-09','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-11-09/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18207,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-09','2029-11-09','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-11-09/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18208,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-11-10','2029-11-10','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-11-10/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18209,'Eltern-Baby-Café',NULL,'2029-11-12','2029-11-12','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-11-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18210,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-11-12','2029-11-12','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-11-12/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18211,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-12','2029-11-12','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-12/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18212,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-11-12','2029-11-12','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-11-12/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18213,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-13','2029-11-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18214,'Krabbelgruppe in Spöck',NULL,'2029-11-13','2029-11-13','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-11-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18215,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-11-13','2029-11-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-11-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18216,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-11-13','2029-11-13','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-11-13/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18217,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-11-13','2029-11-13','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-11-13/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18219,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-11-13','2029-11-13','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-11-13/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18220,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-11-14','2029-11-14','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-11-14/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18221,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-11-14','2029-11-14','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-11-14/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18222,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-11-15','2029-11-15','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-11-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18223,'Korallengarde (10–14 Jahre)',NULL,'2029-11-15','2029-11-15','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-15/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18224,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-11-15','2029-11-15','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-11-15/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18225,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-15','2029-11-15','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-15/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18226,'Seesternchengarde (3–6 Jahre)',NULL,'2029-11-15','2029-11-15','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-11-15/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18227,'Tee- und Spielstube',NULL,'2029-11-15','2029-11-15','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-11-15/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18228,'Teen Girls im GrauBau',NULL,'2029-11-15','2029-11-15','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-11-15/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18229,'Kreativfreitag im GrauBau',NULL,'2029-11-16','2029-11-16','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-11-16/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18230,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-11-16','2029-11-16','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-11-16/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18231,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-16','2029-11-16','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-11-16/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18232,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-11-17','2029-11-17','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-11-17/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18233,'Eltern-Baby-Café',NULL,'2029-11-19','2029-11-19','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-11-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18234,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-11-19','2029-11-19','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-11-19/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18235,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-19','2029-11-19','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-19/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18236,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-11-19','2029-11-19','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-11-19/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18237,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-20','2029-11-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18238,'Krabbelgruppe in Spöck',NULL,'2029-11-20','2029-11-20','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-11-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18239,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-11-20','2029-11-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-11-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18240,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-11-20','2029-11-20','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-11-20/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18241,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-11-20','2029-11-20','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-11-20/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18243,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-11-20','2029-11-20','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-11-20/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18244,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-11-21','2029-11-21','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-11-21/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18245,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-11-21','2029-11-21','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-11-21/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18246,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-11-22','2029-11-22','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-11-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18247,'Korallengarde (10–14 Jahre)',NULL,'2029-11-22','2029-11-22','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-22/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18248,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-11-22','2029-11-22','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-11-22/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18249,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-22','2029-11-22','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-22/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18250,'Seesternchengarde (3–6 Jahre)',NULL,'2029-11-22','2029-11-22','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-11-22/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18251,'Tee- und Spielstube',NULL,'2029-11-22','2029-11-22','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-11-22/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18252,'Teen Girls im GrauBau',NULL,'2029-11-22','2029-11-22','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-11-22/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18253,'Kreativfreitag im GrauBau',NULL,'2029-11-23','2029-11-23','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-11-23/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18254,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-11-23','2029-11-23','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-11-23/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18255,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-23','2029-11-23','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-11-23/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18256,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-11-24','2029-11-24','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-11-24/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18257,'Eltern-Baby-Café',NULL,'2029-11-26','2029-11-26','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-11-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18258,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-11-26','2029-11-26','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-11-26/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18259,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-26','2029-11-26','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-26/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18260,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-11-26','2029-11-26','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-11-26/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18261,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-27','2029-11-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18262,'Krabbelgruppe in Spöck',NULL,'2029-11-27','2029-11-27','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-11-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18263,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-11-27','2029-11-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-11-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18264,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-11-27','2029-11-27','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-11-27/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18265,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-11-27','2029-11-27','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-11-27/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18267,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-11-27','2029-11-27','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-11-27/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18268,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-11-28','2029-11-28','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-11-28/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18269,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-11-28','2029-11-28','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-11-28/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18270,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-11-29','2029-11-29','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-11-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18271,'Korallengarde (10–14 Jahre)',NULL,'2029-11-29','2029-11-29','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-11-29/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18272,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-11-29','2029-11-29','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-11-29/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18273,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-11-29','2029-11-29','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-11-29/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18274,'Seesternchengarde (3–6 Jahre)',NULL,'2029-11-29','2029-11-29','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-11-29/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18275,'Tee- und Spielstube',NULL,'2029-11-29','2029-11-29','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-11-29/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18276,'Teen Girls im GrauBau',NULL,'2029-11-29','2029-11-29','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-11-29/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18277,'Kreativfreitag im GrauBau',NULL,'2029-11-30','2029-11-30','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-11-30/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18278,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-11-30','2029-11-30','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-11-30/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18279,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-11-30','2029-11-30','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-11-30/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18280,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-12-01','2029-12-01','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-12-01/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18281,'Eltern-Baby-Café',NULL,'2029-12-03','2029-12-03','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-12-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18282,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-12-03','2029-12-03','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-12-03/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18283,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-03','2029-12-03','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-03/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18284,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-12-03','2029-12-03','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-12-03/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18285,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-04','2029-12-04','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-04/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18286,'Krabbelgruppe in Spöck',NULL,'2029-12-04','2029-12-04','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-12-04/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18287,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-12-04','2029-12-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-12-04/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18288,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-12-04','2029-12-04','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-12-04/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18289,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-12-04','2029-12-04','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-12-04/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18291,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-12-04','2029-12-04','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-12-04/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18292,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-12-05','2029-12-05','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-12-05/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18293,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-12-05','2029-12-05','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-12-05/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18294,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-12-06','2029-12-06','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-12-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18295,'Korallengarde (10–14 Jahre)',NULL,'2029-12-06','2029-12-06','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-06/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18296,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-12-06','2029-12-06','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-12-06/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18297,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-06','2029-12-06','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-06/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18298,'Seesternchengarde (3–6 Jahre)',NULL,'2029-12-06','2029-12-06','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-12-06/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18299,'Tee- und Spielstube',NULL,'2029-12-06','2029-12-06','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-12-06/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18300,'Teen Girls im GrauBau',NULL,'2029-12-06','2029-12-06','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-12-06/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18301,'Kreativfreitag im GrauBau',NULL,'2029-12-07','2029-12-07','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-12-07/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18302,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-12-07','2029-12-07','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-12-07/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18303,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-07','2029-12-07','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-12-07/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18304,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-12-08','2029-12-08','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-12-08/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18305,'Eltern-Baby-Café',NULL,'2029-12-10','2029-12-10','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-12-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18306,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-12-10','2029-12-10','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-12-10/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18307,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-10','2029-12-10','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-10/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18308,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-12-10','2029-12-10','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-12-10/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18309,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-11','2029-12-11','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-11/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18310,'Krabbelgruppe in Spöck',NULL,'2029-12-11','2029-12-11','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-12-11/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18311,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-12-11','2029-12-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-12-11/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18312,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-12-11','2029-12-11','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-12-11/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18313,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-12-11','2029-12-11','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-12-11/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18315,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-12-11','2029-12-11','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-12-11/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18316,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-12-12','2029-12-12','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-12-12/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18317,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-12-12','2029-12-12','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-12-12/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18318,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-12-13','2029-12-13','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-12-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18319,'Korallengarde (10–14 Jahre)',NULL,'2029-12-13','2029-12-13','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-13/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18320,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-12-13','2029-12-13','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-12-13/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18321,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-13','2029-12-13','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-13/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18322,'Seesternchengarde (3–6 Jahre)',NULL,'2029-12-13','2029-12-13','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-12-13/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18323,'Tee- und Spielstube',NULL,'2029-12-13','2029-12-13','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-12-13/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18324,'Teen Girls im GrauBau',NULL,'2029-12-13','2029-12-13','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-12-13/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18325,'Kreativfreitag im GrauBau',NULL,'2029-12-14','2029-12-14','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-12-14/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18326,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-12-14','2029-12-14','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-12-14/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18327,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-14','2029-12-14','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-12-14/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18328,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-12-15','2029-12-15','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-12-15/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18329,'Eltern-Baby-Café',NULL,'2029-12-17','2029-12-17','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-12-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18330,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-12-17','2029-12-17','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-12-17/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18331,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-17','2029-12-17','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-17/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18332,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-12-17','2029-12-17','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-12-17/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18333,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-18','2029-12-18','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-18/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18334,'Krabbelgruppe in Spöck',NULL,'2029-12-18','2029-12-18','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-12-18/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18335,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-12-18','2029-12-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-12-18/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18336,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-12-18','2029-12-18','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-12-18/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18337,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-12-18','2029-12-18','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-12-18/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18339,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-12-18','2029-12-18','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-12-18/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18340,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-12-19','2029-12-19','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-12-19/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18341,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-12-19','2029-12-19','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-12-19/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18342,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-12-20','2029-12-20','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-12-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18343,'Korallengarde (10–14 Jahre)',NULL,'2029-12-20','2029-12-20','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-20/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18344,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-12-20','2029-12-20','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-12-20/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18345,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-20','2029-12-20','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-20/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18346,'Seesternchengarde (3–6 Jahre)',NULL,'2029-12-20','2029-12-20','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-12-20/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18347,'Tee- und Spielstube',NULL,'2029-12-20','2029-12-20','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-12-20/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18348,'Teen Girls im GrauBau',NULL,'2029-12-20','2029-12-20','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-12-20/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18349,'Kreativfreitag im GrauBau',NULL,'2029-12-21','2029-12-21','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-12-21/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18350,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-12-21','2029-12-21','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-12-21/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18351,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-21','2029-12-21','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-12-21/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18352,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-12-22','2029-12-22','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-12-22/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18353,'Eltern-Baby-Café',NULL,'2029-12-24','2029-12-24','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-12-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18354,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-12-24','2029-12-24','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-12-24/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18355,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-24','2029-12-24','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-24/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18356,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-12-24','2029-12-24','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-12-24/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18357,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-25','2029-12-25','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-25/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,1,'2026-04-25 19:01:27','2026-04-25 19:06:48');
INSERT INTO curated_events VALUES(18358,'Krabbelgruppe in Spöck',NULL,'2029-12-25','2029-12-25','09:30','Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297','CVJM Spöck e.V.',unistr('Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.\u000aIn den Schulferien findet die Krabbelgruppe nicht statt.\u000aAnmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de\u000a'),'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2029-12-25/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kirche,Musik,Spöck,Treff,Verein',12437,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18359,'Pfadfinder*innengruppe (11–15 Jahre)',NULL,'2029-12-25','2029-12-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.\u000aGeländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.\u000aHöhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).\u000a\u000a\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.\u000a\u000a\u000a\u000a\u000a'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2029-12-25/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Natur,Spöck,Treff,Verein,Workshop',12988,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18360,'Pfadfinder*innengruppe Wölflinge',NULL,'2029-12-25','2029-12-25','17:30','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297','Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler',unistr('Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.\u000aDer Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!\u000aUnsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.'),'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2029-12-25/','https://stutenseekinderkalender.de','Friedrichstal,Kinder,Natur,Spöck,Verein,Workshop',12989,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18361,'Schach für Schüler, Jugendliche & Anfänger',NULL,'2029-12-25','2029-12-25','16:30','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Schachclub Blankenloch 1947 e.V.',unistr('Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.\u000aEin Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.\u000aAnmeldung: Gerhard Crocoll, 015233943935'),'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2029-12-25/','https://stutenseekinderkalender.de','Bildung,Essen,Kinder,Kirche,Politik,Treff,Verein,Workshop',12507,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18363,'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern',NULL,'2029-12-25','2029-12-25','19:00','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297','Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus',unistr('Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.\u000aDie Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.\u000aHinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.\u000a\u000aJeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)\u000aKostenfrei\u000a\u000aAnmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)'),'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-12-25/','https://stutenseekinderkalender.de','Friedrichstal,Handwerk,Kinder,Politik,Treff,Wohltätigkeit',12535,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18364,'Eltern-Kind-Kreis in Friedrichstal',NULL,'2029-12-26','2029-12-26','10:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.\u000aAnsprechpartnerin: Corinna Konrad, 01725618123'),'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-12-26/','https://stutenseekinderkalender.de','Essen,Friedrichstal,Handwerk,Kinder,Kirche,Sport,Treff',12459,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18365,'Krabbelgruppe im ev. Gemeindehaus Staffort',NULL,'2029-12-26','2029-12-26','09:30','Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297','Kirchengemeinde Staffort-Büchenau',unistr('Bist du im Alter von 0 bis 3 Jahren?\u000aDann komm doch zum…\u000a\u000a… Spielen\u000a… Singen\u000a… Freunde finden\u000a… Basteln und Malen\u000a… Feste feiern\u000aund weitere Aktionen in die Krabbelgruppe.\u000a\u000aWir freuen uns auf dich!\u000a\u000aAnsprechpartner: Janine Kirchner'),'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2029-12-26/','https://stutenseekinderkalender.de','Fest,Handwerk,Kinder,Kirche,Kultur,Musik,Natur,Staffort',12460,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18366,'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)',NULL,'2029-12-27','2029-12-27','18:30','DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297','DRK Blankenloch e.V.',unistr('Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.\u000aInteressierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.'),'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2029-12-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Treff,Verein,Wohltätigkeit,Workshop',12542,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18367,'Korallengarde (10–14 Jahre)',NULL,'2029-12-27','2029-12-27','18:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.\u000a\u000aDienstags & Donnerstags, 18:00–20:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/korallengarde-10-14-jahre/2029-12-27/','https://stutenseekinderkalender.de','Kinder,Musik,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18368,'Krabbelgruppe Stutensee-Blankenloch',NULL,'2029-12-27','2029-12-27','09:30','Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297','Michaelisgemeinde Blankenloch',unistr('Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.\u000aHerzlich willkommen sind alle Babys und Kleinkinder mit Begleitperson. In gemütlicher Runde wird gesungen, gespielt, gebastelt und sich ausgetauscht.\u000aKontakt\u000a\u000aWhatsApp-Gruppe (QR-Code auf Krabbelgruppe Blankenloch Flyer)\u000aTelefon: 0151 47776116\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/krabbelgruppe-stutensee-blankenloch/2029-12-27/','https://stutenseekinderkalender.de','Digital,Handwerk,Kinder,Kirche,Treff,Verein',12432,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18369,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-27','2029-12-27','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-27/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18370,'Seesternchengarde (3–6 Jahre)',NULL,'2029-12-27','2029-12-27','16:30','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die jüngste Garde des Vereins tanzt mit viel Freude und Energie!Kinder zwischen 3 und 6 Jahren lernen hier spielerisch erste Tanzschritte, Teamgeist und Bühnengefühl – immer mit Spaß und Bewegung.\u000a\u000aDonnerstags, 16:30–18:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a\u000a '),'https://stutenseekinderkalender.de/event/seesternchengarde-3-6-jahre/2029-12-27/','https://stutenseekinderkalender.de','Bildung,Kinder,Kultur,Politik,Sport,Verein,Workshop',12493,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18371,'Tee- und Spielstube',NULL,'2029-12-27','2029-12-27','16:00','Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298','Flüchtlingshilfe Stutensee e.V.',unistr('Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.\u000a\u000aFür Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen\u000aJeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)\u000a\u000aAnmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de '),'https://stutenseekinderkalender.de/event/tee-und-spielstube/2029-12-27/','https://stutenseekinderkalender.de','Essen,Fest,Handwerk,Kinder,Kirche,Kultur,Politik,Treff,Verein,Wohltätigkeit',12547,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18372,'Teen Girls im GrauBau',NULL,'2029-12-27','2029-12-27','18:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr\u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/teen-girls-im-graubau/2029-12-27/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Musik,Treff',12433,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18373,'Kreativfreitag im GrauBau',NULL,'2029-12-28','2029-12-28','14:00','GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297','GrauBau Jugendzentrum Stutensee',unistr('Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. \u000aVeranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de\u000a\u000aHinweis\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass Angaben nicht vollständig oder aktuell sind – bitte prüft sie bei der Ansprechperson oder auf der Website.'),'https://stutenseekinderkalender.de/event/kreativfreitag-im-graubau/2029-12-28/','https://stutenseekinderkalender.de','Essen,Handwerk,Kinder,Kultur,Sport',12434,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18374,'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee',NULL,'2029-12-28','2029-12-28','13:15','Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297','Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium',unistr('In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.\u000aInteressierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.\u000aWeitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de'),'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-12-28/','https://stutenseekinderkalender.de','Bildung,Kinder,Musik',12551,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18375,'Seepferdchengarde (6–10 Jahre)',NULL,'2029-12-28','2029-12-28','15:00','Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297','Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.',unistr('Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.\u000a\u000aDienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr\u000aVeranstalter: Karnevalsclub Die Piraten Blankenloch e. V.\u000a'),'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre/2029-12-28/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Sport,Verein',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18376,'Tanzen für die Kleinsten (4-6 Jahre)',NULL,'2029-12-29','2029-12-29','11:15','Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297','Tanzgruppe Rowan Berry',unistr('Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.\u000aWeitere Informationen und Anmeldung unter: 0176 38172576\u000a\u000a '),'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2029-12-29/','https://stutenseekinderkalender.de','Kinder,Musik,Sport,Spöck',12898,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18377,'Eltern-Baby-Café',NULL,'2029-12-31','2029-12-31','10:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.\u000aDie Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.\u000aDie Babys haben Spaß miteinander beim Singen, Spielen und Basteln.\u000aEltern-Baby-Cafe im MGH Flyer\u000aKostenDie Teilnahme ist kostenfrei.\u000aDie Veranstaltung findet nicht in den Ferien statt.\u000aAnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115\u000aHinweis:\u000aHier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt auf der Website oder bei der Ansprechperson.'),'https://stutenseekinderkalender.de/event/eltern-baby-cafe/2029-12-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Musik,Politik,Treff,Verein',12435,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18378,'Kinder- und Jugendtraining – Wilde 13',NULL,'2029-12-31','2029-12-31','18:00','Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297','BSG Wilde 13 Stutensee e.V.',unistr('Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.\u000aDas Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.\u000aKontakt bei Fragen: boehm.uwe@outlook.com\u000a'),'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-12-31/','https://stutenseekinderkalender.de','Kinder,Natur,Sport,Verein,Workshop',12636,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18379,'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal',NULL,'2029-12-31','2029-12-31','09:00','Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297','Ev. Kirchengemeinde Friedrichstal',unistr('\u000aIn der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.\u000aMontags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.\u000a\u000aWeitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.\u000aAnsprechpartnerin:\u000aSabrina Strohal, Tel. 387483 oder 0160 98567729\u000aFlyer Kükenstube 2025'),'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2029-12-31/','https://stutenseekinderkalender.de','Bildung,Friedrichstal,Kinder,Kirche,Musik,Workshop',NULL,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
INSERT INTO curated_events VALUES(18380,'Spiele-Treff vom Teenie bis zum Oldie',NULL,'2029-12-31','2029-12-31','16:00','Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297','Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.',unistr('Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.\u000aBegeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!\u000aNicht in den Ferien.'),'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2029-12-31/','https://stutenseekinderkalender.de','Handwerk,Kinder,Politik,Treff,Verein',13043,NULL,'2026-04-25 19:01:27','2026-04-25 19:01:27');
