PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE raw_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            source_url TEXT NOT NULL,
            title TEXT,
            date_start TEXT,
            date_end TEXT,
            time_raw TEXT,
            location TEXT,
            organizer TEXT,
            description TEXT,
            event_url TEXT,
            raw_html_hash TEXT,
            scraped_at TEXT DEFAULT (datetime('now')),
            UNIQUE(source_url, event_url, date_start, title)
        );
CREATE TABLE curated_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            normalized_title TEXT,
            date_start TEXT,
            date_end TEXT,
            time_raw TEXT,
            location TEXT,
            organizer TEXT,
            description TEXT,
            event_url TEXT,
            sources TEXT,
            tags TEXT DEFAULT '',
            recurring_group_id INTEGER DEFAULT NULL,
            dedup_round INTEGER,
            created_at TEXT DEFAULT (datetime('now')),
            updated_at TEXT DEFAULT (datetime('now'))
        );
CREATE TABLE raw_to_curated (
            raw_id INTEGER NOT NULL,
            curated_id INTEGER NOT NULL,
            dedup_round INTEGER NOT NULL,
            PRIMARY KEY (raw_id, curated_id),
            FOREIGN KEY (raw_id) REFERENCES raw_events(id),
            FOREIGN KEY (curated_id) REFERENCES curated_events(id)
        );
CREATE INDEX idx_curated_dates ON curated_events(date_start);
CREATE INDEX idx_curated_title ON curated_events(normalized_title);
COMMIT;
